fn stable_iroh_endpoint_id_raw(node_id: &NodeId, endpoint_public_key: &str) -> ClusterEndpointId {
    ClusterEndpointId::derived(
        "sinomo.iroh.endpoint",
        format!("{}\0{endpoint_public_key}", node_id.as_str()),
    )
}

fn stable_iroh_endpoint_id(node_id: &NodeId, endpoint_public_key: &str) -> ClusterEndpointId {
    install_test_iroh_network_module();
    stable_iroh_endpoint_id_raw(node_id, endpoint_public_key)
}

fn test_iroh_endpoint_public_key(address: &str) -> Option<&str> {
    let rest = address.strip_prefix("iroh://")?;
    rest.split(['?', '#']).next().filter(|key| !key.is_empty())
}

fn test_iroh_endpoint(
    cluster_id: &ClusterId,
    node_id: &NodeId,
    endpoint_public_key: &str,
    relay_url: Option<&str>,
) -> ClusterEndpointRecord {
    let address = match relay_url {
        Some(relay_url) => format!("iroh://{endpoint_public_key}?relay={relay_url}"),
        None => format!("iroh://{endpoint_public_key}"),
    };
    let privacy = if relay_url.is_some() {
        ClusterEndpointPrivacy::Relayed
    } else {
        ClusterEndpointPrivacy::InternetDirect
    };
    let _ = cluster_id;
    ClusterEndpointRecord {
        endpoint_id: stable_iroh_endpoint_id(node_id, endpoint_public_key),
        node_id: node_id.clone(),
        transport: ClusterTransportKind::Iroh,
        address,
        source: ClusterEndpointSource::Rendezvous,
        privacy,
        priority: 90,
        last_observed_latency_ms: None,
    }
}

/// Installs the KV-backed cluster directory provider once for the whole test
/// process. Stable cluster facts still come from KV through the registered
/// directory; cluster connectivity is supplied by KV when present and local
/// connectivity files are used only as bootstrap fallback.
/// Tests own distinct data roots, so the per-paths factory keeps them isolated.
fn install_kv_directory_for_tests() {
    static INSTALL: std::sync::Once = std::sync::Once::new();
    INSTALL.call_once(sinomo_cluster::install_kv_cluster_directory);
}

struct TestIrohNetworkModule;

impl NetworkModule for TestIrohNetworkModule {
    fn descriptor(&self) -> NetworkModuleDescriptor {
        NetworkModuleDescriptor {
            id: "test-iroh".to_string(),
            transports: vec![ClusterTransportKind::Iroh],
            address_schemes: vec!["iroh".to_string()],
            dialer: true,
            listener: false,
            supports_runtime_toggle: true,
        }
    }

    fn start(&self, _ctx: &NetworkModuleContext) -> Result<(), NetworkError> {
        Ok(())
    }

    fn stop(&self) -> Result<(), NetworkError> {
        Ok(())
    }

    fn connect_link(
        &self,
        endpoint: &ClusterEndpointRecord,
        _health: NetworkHealthPolicy,
    ) -> NetworkFuture<AuthenticatedLink> {
        let peer_node_id = endpoint.node_id.clone();
        let link_id = endpoint.endpoint_id.clone();
        Box::pin(async move {
            AuthenticatedLink::new(
                NodeId::generate(),
                peer_node_id,
                link_id,
                [7; 32],
                DirectStreamCapabilities::multiplexed_full_duplex(8),
                || {
                    Box::pin(async move {
                        let (client, mut server) = tokio::io::duplex(64 * 1024);
                        tokio::spawn(async move {
                            let mut buffer = [0_u8; 8192];
                            loop {
                                let read =
                                    tokio::io::AsyncReadExt::read(&mut server, &mut buffer).await?;
                                if read == 0 {
                                    return Ok::<(), std::io::Error>(());
                                }
                                tokio::io::AsyncWriteExt::write_all(&mut server, &buffer[..read])
                                    .await?;
                            }
                        });
                        Ok(Box::new(client) as BoxedNetworkStream)
                    })
                },
            )
        })
    }

    fn local_endpoints(&self) -> Result<Vec<ClusterEndpointRecord>, NetworkError> {
        Ok(Vec::new())
    }

    fn endpoint_role(&self, endpoint: &ClusterEndpointRecord) -> NetworkModuleEndpointRole {
        let Some(public_key) = test_iroh_endpoint_public_key(&endpoint.address) else {
            return NetworkModuleEndpointRole::Unknown;
        };
        let shadow_node_id = shadow_daemon_node_id(&endpoint.node_id);
        if endpoint.endpoint_id == stable_iroh_endpoint_id_raw(&shadow_node_id, public_key) {
            return NetworkModuleEndpointRole::ShadowDaemon;
        }
        if endpoint.endpoint_id == stable_iroh_endpoint_id_raw(&endpoint.node_id, public_key) {
            return NetworkModuleEndpointRole::MainDaemon;
        }
        NetworkModuleEndpointRole::Unknown
    }
}

fn install_test_iroh_network_module() {
    static INSTALL: std::sync::Once = std::sync::Once::new();
    INSTALL.call_once(|| {
        let registry = NetworkModuleRegistry::new();
        registry.register(Arc::new(TestIrohNetworkModule), None, true, false);
        set_network_module_registry(Arc::new(registry));
    });
}

#[test]
fn object_rpc_requests_carry_operation_cancellation_metadata() {
    let request = ObjectRpcRequest::encode_body("/test/run", "test", &())
        .expect("request")
        .with_operation_id("op_1");
    assert_eq!(request.operation_id(), Some("op_1"));
    assert_eq!(request.cancels_operation_id(), None);
    assert!(!request.is_response_retry_safe());

    let cancel = ObjectRpcRequest::encode_body(
        "/test/cancel",
        "test",
        &ObjectRpcCancelRequest::new("op_1", "turn cancelled"),
    )
    .expect("cancel request")
    .with_cancels_operation_id("op_1");
    assert_eq!(cancel.operation_id(), None);
    assert_eq!(cancel.cancels_operation_id(), Some("op_1"));
    let body: ObjectRpcCancelRequest = cancel.decode_body().expect("cancel body");
    assert_eq!(
        body,
        ObjectRpcCancelRequest {
            operation_id: "op_1".to_string(),
            reason: "turn cancelled".to_string(),
        }
    );

    let retry_safe = ObjectRpcRequest::encode_body("/test/retry-safe", "test", &())
        .expect("retry-safe request")
        .with_response_retry_safe();
    assert!(retry_safe.is_response_retry_safe());
}

#[test]
fn network_publishes_agent_cluster_inspection_specs() {
    assert_eq!(
        NETWORK_CAPABILITY_EXPORTS,
        &[
            CLUSTER_HEALTH_READ_CAPABILITY,
            CLUSTER_NETWORK_CONNECTIVITY_READ_CAPABILITY,
            CLUSTER_NETWORK_PING_CAPABILITY
        ]
    );
    assert!(NETWORK_CAPABILITY_IMPORTS.contains(&"cluster.kv.read"));

    let skill = NETWORK_DECLARATIVE_RESOURCE_SURFACES
        .iter()
        .find(|resource| resource.id == CLUSTER_NETWORK_INSPECTION_SKILL_ID)
        .expect("cluster network inspection skill");
    assert_eq!(skill.kind, NetworkDeclarativeResourceKind::Skill);
    assert_eq!(skill.path, CLUSTER_NETWORK_INSPECTION_SKILL_PATH);
    assert!(skill.model_families.contains(&"gpt"));
    assert!(skill.activation_tags.contains(&"cluster"));
    assert!(
        skill
            .required_capabilities
            .contains(&CLUSTER_HEALTH_READ_CAPABILITY)
    );
    assert!(CLUSTER_NETWORK_INSPECTION_SKILL_MARKDOWN.contains(CLUSTER_HEALTH_READ_CAPABILITY));

    let prompt = NETWORK_DECLARATIVE_RESOURCE_SURFACES
        .iter()
        .find(|resource| resource.id == CLUSTER_NETWORK_INSPECTION_PROMPT_ID)
        .expect("cluster network inspection prompt");
    assert_eq!(prompt.kind, NetworkDeclarativeResourceKind::Prompt);
    assert_eq!(prompt.path, CLUSTER_NETWORK_INSPECTION_PROMPT_PATH);
    assert!(CLUSTER_NETWORK_INSPECTION_PROMPT_MARKDOWN.contains("cluster network"));
}

#[test]
fn cluster_network_ping_can_measure_request_and_response_payload_bytes() {
    let request = cluster_network_ping_rpc_request_with_response_payload("payload-probe", 7, 11)
        .expect("ping request");
    let responder = NodeId::from_legacy_named("node.payload").expect("legacy node id");
    let response = handle_cluster_network_ping_rpc_request_for_node(
        &responder,
        request,
        time::OffsetDateTime::UNIX_EPOCH,
    )
    .expect("ping response");
    let response = decode_cluster_network_ping_rpc_response(&response).expect("decode response");

    assert_eq!(response.nonce, "payload-probe");
    assert_eq!(response.responder_node_id, responder);
    assert_eq!(response.payload_bytes, 7);
    assert_eq!(response.response_payload.len(), 11);
}

#[test]
fn direct_cluster_rpc_handlers_return_unknown_route_errors() {
    struct NoopClusterStatusProbe;

    impl ClusterStatusProbe for NoopClusterStatusProbe {
        fn probe_member_status(
            &self,
            _state: &ClusterBootstrapState,
            _member: &ClusterMemberRecord,
        ) -> Option<ClusterNodeStatusRecord> {
            panic!("unknown-route dispatch must not probe member status")
        }

        fn peer_health_rows(
            &self,
            _state: &ClusterBootstrapState,
            _member: &ClusterMemberRecord,
            _timeout: Duration,
        ) -> Option<Vec<ClusterHealthRow>> {
            panic!("unknown-route dispatch must not fetch peer health rows")
        }
    }

    impl ClusterStatusAsyncProbe for NoopClusterStatusProbe {
        fn probe_member_status_async<'a>(
            &'a self,
            _state: &'a ClusterBootstrapState,
            _member: &'a ClusterMemberRecord,
        ) -> ClusterMembershipRpcFuture<'a, Option<ClusterNodeStatusRecord>> {
            Box::pin(async {
                panic!("unknown-route dispatch must not probe member status asynchronously")
            })
        }

        fn peer_health_rows_async<'a>(
            &'a self,
            _state: &'a ClusterBootstrapState,
            _member: &'a ClusterMemberRecord,
            _timeout: Duration,
        ) -> ClusterMembershipRpcFuture<'a, Option<Vec<ClusterHealthRow>>> {
            Box::pin(async {
                panic!("unknown-route dispatch must not fetch peer health rows asynchronously")
            })
        }
    }

    let root = sinomo_testdir::TestDir::new("sinomo-network-direct-rpc-unknown-route");
    let data_dir = SinomoDataDir::new(&root);
    let paths = ClusterPaths::new(&data_dir);
    let now = OffsetDateTime::now_utc();
    let state = ClusterBootstrapState::initialized_locally(
        ClusterId::from_legacy_named("cluster_direct_rpc_unknown_route").expect("cluster"),
        "direct rpc unknown route",
        NodeId::from_legacy_named("node_direct_rpc_unknown_route").expect("node"),
        "local",
        "pk-local",
        now,
    );
    let unknown_route = "/cluster/not-registered";

    let health_request =
        ObjectRpcRequest::encode_body(unknown_route, CLUSTER_HEALTH_RPC_CATEGORY, &())
            .expect("health unknown route request");
    let health_error = handle_cluster_health_rpc_request(
        &paths,
        &state,
        &NoopClusterStatusProbe,
        health_request,
        now,
    )
    .expect_err("unknown health route should be a dispatch error");
    assert!(
        matches!(health_error, NetworkError::UnknownRoute { ref route } if route == unknown_route)
    );

    let runtime = tokio::runtime::Builder::new_current_thread()
        .enable_all()
        .build()
        .expect("runtime");
    let async_health_request =
        ObjectRpcRequest::encode_body(unknown_route, CLUSTER_HEALTH_RPC_CATEGORY, &())
            .expect("async health unknown route request");
    let async_health_error = runtime
        .block_on(handle_cluster_health_rpc_request_async(
            &paths,
            &state,
            &NoopClusterStatusProbe,
            async_health_request,
            now,
        ))
        .expect_err("unknown async health route should be a dispatch error");
    assert!(
        matches!(async_health_error, NetworkError::UnknownRoute { ref route } if route == unknown_route)
    );

    let raft_request = ObjectRpcRequest::encode_body(unknown_route, CLUSTER_RAFT_RPC_CATEGORY, &())
        .expect("raft unknown route request");
    let raft_error = handle_cluster_raft_rpc_request(
        &paths,
        raft_request,
        &ClusterAuthenticatedPeer {
            node_id: "node-direct-rpc-unknown-route".to_string(),
            public_key: "pk-local".to_string(),
        },
    )
    .expect_err("unknown raft route should be a dispatch error");
    assert!(
        matches!(raft_error, NetworkError::UnknownRoute { ref route } if route == unknown_route)
    );

    let membership_request =
        ObjectRpcRequest::encode_body(unknown_route, CLUSTER_MEMBERSHIP_RPC_CATEGORY, &())
            .expect("membership unknown route request");
    let mut join_host = UnusedClusterJoinRegistrationHost;
    let mut member_host = RecordingClusterMemberPublishHost::default();
    let mut invite_host = UnusedClusterInvitePublishHost;
    let membership_error =
        handle_cluster_membership_rpc_request_with_hosts::<NetworkError, _, _, _>(
            &paths,
            membership_request,
            "node-direct-rpc-unknown-route",
            "pk-local",
            now,
            &mut join_host,
            &mut member_host,
            &mut invite_host,
        )
        .expect_err("unknown membership route should be a dispatch error");
    assert!(
        matches!(membership_error, NetworkError::UnknownRoute { ref route } if route == unknown_route)
    );
}

#[test]
fn cluster_kv_txn_rpc_preserves_nested_sobj_values_as_raw_bytes() {
    #[derive(Debug, Clone, Eq, PartialEq, serde::Serialize, serde::Deserialize)]
    struct ClusterConfigFixture {
        name: String,
        value: u64,
    }

    let record = ClusterConfigFixture {
        name: "runtime".to_string(),
        value: 42,
    };
    let op = KvOp::put_serde("/config/test/runtime", &record, None).expect("typed kv op");
    let raw_value = match &op {
        KvOp::Put { value, .. } => value.clone(),
        _ => unreachable!("put_serde must produce a put op"),
    };
    assert!(raw_value.starts_with(sinomo_object::MAGIC));
    assert!(
        !raw_value.starts_with(b"U09CSg"),
        "typed KV values must be raw SOBJ bytes, not base64 text"
    );

    let txn = KvTxn {
        compares: Vec::new(),
        success: vec![op],
        failure: Vec::new(),
    };
    let txn_request = KvTxnRequest::generated(txn);
    let request = object_rpc_request_from_kv_payload(
        sinomo_kv::cluster_kv_txn_rpc_payload(&txn_request).expect("encode txn request"),
    );
    assert!(
        request
            .body
            .windows(raw_value.len())
            .any(|window| window == raw_value.as_slice()),
        "cluster RPC encoding must embed nested KV values verbatim instead of base64 wrapping them"
    );

    let decoded: KvTxnRequest = request.decode_body().expect("decode txn request");
    let decoded_value = match decoded.txn.success.first().expect("put op") {
        KvOp::Put { value, .. } => value,
        _ => unreachable!("expected put op"),
    };
    assert_eq!(decoded_value, &raw_value);
    assert!(decoded_value.starts_with(sinomo_object::MAGIC));
}

#[test]
fn async_object_frame_helpers_round_trip_binary_payloads() {
    let runtime = tokio::runtime::Builder::new_current_thread()
        .enable_all()
        .build()
        .expect("runtime");
    runtime.block_on(async {
        let (mut client, mut server) = tokio::io::duplex(4096);
        let writer = tokio::spawn(async move {
            write_object_frame_async(
                &mut client,
                &ObjectRpcRequest::encode_body("/test/status", "test", &()).expect("request"),
                ObjectFrameIoOptions::none(),
            )
            .await
            .expect("write frame");
        });
        let request: DaemonControlRequest =
            read_object_frame_async(&mut server, ObjectFrameIoOptions::none())
                .await
                .expect("read frame");
        writer.await.expect("writer task");
        assert_eq!(request.route, "/test/status");
    });
}

#[test]
fn daemon_control_stream_idle_timeout_configures_blocking_timeouts() {
    let listener = std::net::TcpListener::bind("127.0.0.1:0").expect("listener");
    let stream = std::net::TcpStream::connect(listener.local_addr().expect("local addr"))
        .expect("client stream");

    sinomo_network::configure_daemon_control_stream_idle_timeout(
        &stream,
        "127.0.0.1",
        Duration::from_millis(500),
        true,
        true,
    )
    .expect("initial timeout configuration");
    let initial_read_timeout = stream
        .read_timeout()
        .expect("read timeout")
        .expect("read timeout set");
    let initial_write_timeout = stream
        .write_timeout()
        .expect("write timeout")
        .expect("write timeout set");

    sinomo_network::configure_daemon_control_stream_idle_timeout(
        &stream,
        "127.0.0.1",
        Duration::from_millis(500),
        true,
        false,
    )
    .expect("refreshed read timeout");
    let refreshed_read_timeout = stream
        .read_timeout()
        .expect("read timeout")
        .expect("read timeout set");

    assert!(
        refreshed_read_timeout == initial_read_timeout,
        "blocking daemon proxy reads should use an idle timeout, not a shrinking route budget"
    );
    assert_eq!(
        stream
            .write_timeout()
            .expect("write timeout")
            .expect("write timeout set"),
        initial_write_timeout,
        "refreshing the read phase should not lengthen the write timeout"
    );
}

#[test]
fn lan_ip_filter_rejects_non_invitable_addresses() {
    assert!(!is_invitable_ip("127.0.0.1".parse().expect("loopback")));
    assert!(!is_invitable_ip("0.0.0.0".parse().expect("unspecified")));
    assert!(!is_invitable_ip("224.0.0.1".parse().expect("multicast")));
    assert!(is_invitable_ip("192.168.1.10".parse().expect("lan")));
}

#[test]
fn interface_ip_filter_keeps_routable_lan_addresses() {
    assert!(is_advertisable_interface_ip(
        "10.42.0.15".parse().expect("wireguard lan")
    ));
    assert!(is_advertisable_interface_ip(
        "192.168.1.154".parse().expect("ethernet lan")
    ));
    assert!(!is_advertisable_interface_ip(
        "169.254.147.92".parse().expect("link local")
    ));
    assert!(!is_advertisable_interface_ip(
        "127.0.0.1".parse().expect("loopback")
    ));
}

#[test]
fn interface_candidate_filter_rejects_common_local_only_bridges() {
    let docker_bridge = "172.17.0.1".parse().expect("docker bridge");
    let docker_network = "172.18.0.1".parse().expect("docker network");
    let routable_lan = "10.42.0.15".parse().expect("routable lan");

    assert!(!is_advertisable_interface_candidate(
        "docker0",
        docker_bridge
    ));
    assert!(!is_advertisable_interface_candidate(
        "br-6f2c4e8a",
        docker_network
    ));
    assert!(!is_advertisable_interface_candidate(
        "veth1234",
        "169.254.147.92".parse().expect("link local")
    ));
    assert!(!is_advertisable_interface_candidate(
        "vEthernet (WSL)",
        "172.26.176.1".parse().expect("wsl bridge")
    ));
    assert!(!is_advertisable_interface_candidate(
        "vEthernet (Docker Desktop)",
        "192.168.245.1".parse().expect("docker desktop bridge")
    ));
    assert!(!is_advertisable_interface_candidate(
        "VMware Network Adapter VMnet8",
        "192.168.245.1".parse().expect("vmware nat bridge")
    ));
    assert!(is_advertisable_interface_candidate("eth0", routable_lan));
    assert!(is_advertisable_interface_candidate(
        "eth0",
        "172.18.0.2".parse().expect("docker guest lan")
    ));
    assert!(is_advertisable_interface_candidate(
        "ens160",
        "192.168.245.42".parse().expect("vm guest lan")
    ));
    assert!(is_advertisable_interface_candidate(
        "Ethernet",
        "192.168.126.42".parse().expect("windows vm guest lan")
    ));
}

#[test]
fn invite_channel_uri_uses_compact_iroh_endpoint() {
    let cluster_id = ClusterId::from_legacy_named("cluster_invite_full_iroh").expect("cluster");
    let node_id = NodeId::from_legacy_named("node_invite_full_iroh").expect("node");
    let endpoint = ClusterEndpointRecord {
        endpoint_id: stable_iroh_endpoint_id(&node_id, "iroh_public_key_test"),
        node_id: node_id.clone(),
        transport: ClusterTransportKind::Iroh,
        address: "iroh://iroh_public_key_test?relay=https://relay.example./".to_string(),
        source: ClusterEndpointSource::Rendezvous,
        privacy: ClusterEndpointPrivacy::Relayed,
        priority: 90,
        last_observed_latency_ms: Some(42),
    };
    let invite = ClusterJoinInvite {
        invite_id: ClusterInviteId::from_legacy_named("invite_full_iroh").expect("invite"),
        cluster_id,
        cluster_name: Some("full iroh".to_string()),
        cluster_public_key: "cluster-pk".to_string(),
        invitation_secret: "secret".to_string(),
        communication_channels: vec![sinomo_base::ClusterInvitationChannel {
            endpoint: endpoint.clone(),
            node_public_key: "node-pk".to_string(),
        }],
        introducers: Vec::new(),
        token_id: "token".to_string(),
        expires_at: OffsetDateTime::UNIX_EPOCH,
        trust_domain: TrustDomain::new("trust.local").expect("trust domain"),
        allowed_member_roles: vec![ClusterMemberRole::Learner],
        issuer_node_id: node_id.clone(),
        issuer_public_key: "issuer-pk".to_string(),
        signature: String::new(),
    };

    let uri = encode_cluster_join_invite(&invite).expect("encode invite");
    let decoded = decode_cluster_join_invite(&uri).expect("decode invite");

    assert!(!uri.contains(node_id.as_str()));
    assert!(!uri.contains(endpoint.endpoint_id.as_str()));
    assert_eq!(decoded.communication_channels.len(), 1);
    assert_eq!(
        decoded.communication_channels[0].endpoint.transport,
        endpoint.transport
    );
    assert_eq!(
        decoded.communication_channels[0].endpoint.address,
        endpoint.address
    );
    assert_eq!(decoded.communication_channels[0].node_public_key, "node-pk");
}

