#[test]
fn cluster_invite_challenge_proof_verification_uses_network_contract() {
    use base64::{Engine as _, engine::general_purpose::URL_SAFE_NO_PAD};

    let root = sinomo_testdir::TestDir::new("sinomo-network-invite-challenge-proof");
    let issuer_identity =
        sinomo_node::load_or_create_main_node_identity(&root).expect("issuer identity");
    let cluster_id =
        ClusterId::from_legacy_named("cluster_invite_challenge_proof").expect("cluster");
    let invite_id = ClusterInviteId::from_legacy_named("invite_challenge_proof").expect("invite");
    let issuer_node_id = NodeId::from_legacy_named("node_invite_challenge_issuer").expect("issuer");
    let invite = ClusterJoinInvite {
        invite_id: invite_id.clone(),
        cluster_id: cluster_id.clone(),
        cluster_name: Some("invite challenge proof".to_string()),
        cluster_public_key: issuer_identity.public_key.clone(),
        invitation_secret: "secret".to_string(),
        communication_channels: Vec::new(),
        introducers: Vec::new(),
        token_id: "token".to_string(),
        expires_at: OffsetDateTime::now_utc() + time::Duration::hours(1),
        trust_domain: TrustDomain::new("trust.local").expect("trust domain"),
        allowed_member_roles: vec![ClusterMemberRole::Learner],
        issuer_node_id: issuer_node_id.clone(),
        issuer_public_key: issuer_identity.public_key.clone(),
        signature: String::new(),
    };
    let challenge = "join-challenge";
    let timestamp = OffsetDateTime::now_utc()
        .format(&time::format_description::well_known::Rfc3339)
        .expect("timestamp");
    let payload = cluster_invite_challenge_signing_payload(
        &invite_id,
        &cluster_id,
        issuer_node_id.as_str(),
        &issuer_identity.public_key,
        challenge,
        &timestamp,
    );
    let signature = issuer_identity
        .key_pair()
        .expect("issuer key")
        .sign(payload.as_bytes());
    let proof = ClusterInviteChallengeProof {
        protocol: CLUSTER_INVITE_CHALLENGE_PROTOCOL.to_string(),
        invite_id,
        cluster_id,
        responder_node_id: issuer_node_id.to_string(),
        responder_public_key: issuer_identity.public_key,
        challenge: challenge.to_string(),
        timestamp,
        signature: URL_SAFE_NO_PAD.encode(signature.as_ref()),
    };

    verify_cluster_invite_challenge_proof(&invite, challenge, &proof).expect("valid proof");
    assert!(matches!(
        verify_cluster_invite_challenge_proof(&invite, "different-challenge", &proof),
        Err(NetworkError::AuthDenied)
    ));
}

// These two existing signer callers use a genuine single-voter ReadIndex.
// Unused remote operations fail closed; this host supplies no acknowledgement.
struct InviteChallengeReadHost;
impl ClusterObjectRpcAsyncHost for InviteChallengeReadHost {}
impl ClusterKvQuorumAsyncHost for InviteChallengeReadHost {
    fn last_local_kv_replication_index_async<'a>(
        &'a mut self,
        _paths: &'a ClusterPaths,
        _state: &'a ClusterBootstrapState,
    ) -> ClusterMembershipRpcFuture<'a, u64> {
        Box::pin(async {
            Err(NetworkError::ClusterReadOnly {
                detail: "single-voter invite read unexpectedly requested replication".into(),
            })
        })
    }
    fn build_kv_replication_request_async<'a>(
        &'a mut self,
        _paths: &'a ClusterPaths,
        _state: &'a ClusterBootstrapState,
        _next_index: u64,
    ) -> ClusterMembershipRpcFuture<'a, sinomo_kv::ClusterRaftAppendRequest> {
        Box::pin(async {
            Err(NetworkError::ClusterReadOnly {
                detail: "single-voter invite read unexpectedly built replication".into(),
            })
        })
    }
    fn send_cluster_kv_replication_to_node_async<'a>(
        &'a mut self,
        _paths: &'a ClusterPaths,
        _state: &'a ClusterBootstrapState,
        _target: &'a NodeId,
        _request: &'a sinomo_kv::ClusterRaftAppendRequest,
        _timeout: Duration,
    ) -> ClusterMembershipRpcFuture<'a, sinomo_kv::ClusterRaftAppendResponse> {
        Box::pin(async {
            Err(NetworkError::ClusterReadOnly {
                detail: "single-voter invite read unexpectedly sent replication".into(),
            })
        })
    }
}
impl ClusterStateAuthorityReachabilityAsyncHost for InviteChallengeReadHost {
    fn probe_cluster_state_authority_node_async<'a>(
        &'a mut self,
        _state: &'a ClusterBootstrapState,
        _target: &'a NodeId,
        _timeout: Duration,
    ) -> ClusterMembershipRpcFuture<'a, bool> {
        Box::pin(async { Ok(false) })
    }
}
impl ClusterKvTxnQuorumAsyncHost for InviteChallengeReadHost {
    fn request_kv_state_authority_vote_async<'a>(
        &'a mut self,
        _state: &'a ClusterBootstrapState,
        _target: &'a NodeId,
        _request: &'a sinomo_kv::ClusterKvStateAuthorityVoteRequest,
        _timeout: Duration,
    ) -> ClusterMembershipRpcFuture<'a, sinomo_kv::ClusterKvStateAuthorityVoteResponse> {
        Box::pin(async {
            Err(NetworkError::ClusterReadOnly {
                detail: "single-voter invite read unexpectedly requested a vote".into(),
            })
        })
    }
}
struct InviteChallengeNativeAccess<'a> {
    paths: &'a ClusterPaths,
    allow_forwarding: bool,
}
impl sinomo_service::ClusterAccess for InviteChallengeNativeAccess<'_> {
    fn kv_get_local(
        &self,
        _key: &str,
    ) -> Result<sinomo_kv::KvLocalRead<Option<sinomo_kv::KvEntry>>, sinomo_service::ServiceError>
    {
        Err(sinomo_service::ServiceError::Service(
            "invite signer must use native exact-set authority".into(),
        ))
    }
    fn kv_range_prefix_local(
        &self,
        _prefix: &str,
    ) -> Result<sinomo_kv::KvLocalRead<Vec<sinomo_kv::KvEntry>>, sinomo_service::ServiceError> {
        Err(sinomo_service::ServiceError::Service(
            "invite signer must use native exact-set authority".into(),
        ))
    }
    fn kv_get_authoritative_async<'a>(
        &'a self,
        _key: &'a str,
    ) -> ClusterMembershipServiceFuture<
        'a,
        sinomo_kv::KvAuthoritativeRead<Option<sinomo_kv::KvEntry>>,
    > {
        Box::pin(async {
            Err(sinomo_service::ServiceError::Service(
                "invite signer must use one native exact-set read".into(),
            ))
        })
    }
    fn kv_get_authoritative_exact_set_async<'a>(
        &'a self,
        keys: Vec<String>,
    ) -> ClusterMembershipServiceFuture<
        'a,
        sinomo_kv::KvAuthoritativeRead<Vec<Option<sinomo_kv::KvEntry>>>,
    > {
        Box::pin(async move {
            let mut state = read_cluster_state_without_kv(self.paths)?;
            let runtime = tokio::runtime::Handle::current();
            read_cluster_kv_authoritative_entries_async_with_host(
                &runtime,
                self.paths,
                &mut state,
                keys,
                ClusterControlPlaneTimeouts::default_daemon_transport()
                    .kv_txn_quorum_options(self.allow_forwarding),
                &mut InviteChallengeReadHost,
            )
            .await
            .map_err(sinomo_service::ServiceError::Network)
        })
    }
    fn kv_commit_async<'a>(
        &'a self,
        _request: sinomo_kv::KvTxnRequest,
    ) -> ClusterMembershipServiceFuture<'a, sinomo_kv::ClusterKvTxnCommitResult> {
        Box::pin(async {
            Err(sinomo_service::ServiceError::Service(
                "invite read adapter cannot commit".into(),
            ))
        })
    }
}
fn native_test_invite_challenge_proof(
    paths: &ClusterPaths,
    identity: &sinomo_node::NodeIdentity,
    request: &ClusterInviteChallengeRequest,
) -> Result<ClusterInviteChallengeProof, NetworkError> {
    let runtime = tokio::runtime::Runtime::new().map_err(|error| NetworkError::Io {
        operation: "start native invite read runtime".into(),
        detail: error.to_string(),
    })?;
    runtime.block_on(create_cluster_invite_challenge_proof(
        paths,
        identity,
        request,
        &InviteChallengeNativeAccess {
            paths,
            allow_forwarding: false,
        },
    ))
}

fn native_invite_challenge_fixture() -> (
    sinomo_testdir::TestDir,
    ClusterPaths,
    sinomo_node::NodeIdentity,
    ClusterJoinInvite,
    ClusterInviteChallengeRequest,
) {
    let root = sinomo_testdir::TestDir::new("sinomo-network-invite-challenge-create");
    let data_dir = SinomoDataDir::new(&root);
    let paths = ClusterPaths::new(&data_dir);
    paths.ensure().expect("cluster paths");
    let now = OffsetDateTime::now_utc();
    let identity = sinomo_node::load_or_create_main_node_identity(&root).expect("node identity");
    let cluster_id =
        ClusterId::from_legacy_named("cluster_invite_challenge_create").expect("cluster");
    let local_node_id = NodeId::from_legacy_named("node_invite_challenge_create").expect("node");
    let mut state = ClusterBootstrapState::initialized_locally(
        cluster_id.clone(),
        "invite challenge create",
        local_node_id.clone(),
        "local",
        identity.public_key.clone(),
        now,
    );
    ensure_main_daemon_cluster_member(&mut state, Vec::new(), now);
    write_cluster_state(&paths, &state).expect("write state");
    let mut node = open_cluster_raft_kv_node(&paths, &local_node_id).expect("open native voter");
    node.become_leader(state.term)
        .expect("initial sole-voter leader");
    drop(node);
    bootstrap_single_voter_cluster_state_to_local_kv(&paths, &state)
        .expect("publish actual initial member and config");
    let invite = ClusterJoinInvite {
        invite_id: ClusterInviteId::from_legacy_named("invite_challenge_create").expect("invite"),
        cluster_id,
        cluster_name: Some("invite challenge create".to_string()),
        cluster_public_key: identity.public_key.clone(),
        invitation_secret: "secret".to_string(),
        communication_channels: Vec::new(),
        introducers: Vec::new(),
        token_id: "token".to_string(),
        expires_at: now + time::Duration::hours(1),
        trust_domain: TrustDomain::new("trust.local").expect("trust domain"),
        allowed_member_roles: vec![ClusterMemberRole::Learner],
        issuer_node_id: local_node_id.clone(),
        issuer_public_key: identity.public_key.clone(),
        signature: String::new(),
    };
    sync_cluster_invitation_to_local_raft_unchecked(&paths, &invite).expect("sync invite");
    let request = ClusterInviteChallengeRequest {
        protocol: CLUSTER_INVITE_CHALLENGE_PROTOCOL.to_string(),
        invite_id: invite.invite_id.clone(),
        challenge: "create-proof-challenge".to_string(),
    };

    (root, paths, identity, invite, request)
}

#[test]
fn cluster_invite_challenge_proof_creation_uses_network_state() {
    let (_root, paths, identity, invite, request) = native_invite_challenge_fixture();
    let local_node_id = read_cluster_state_without_kv(&paths).unwrap().local_node_id;
    let proof = native_test_invite_challenge_proof(&paths, &identity, &request)
        .expect("create native authoritative proof");

    assert_eq!(proof.invite_id, invite.invite_id);
    assert_eq!(proof.cluster_id, invite.cluster_id);
    assert_eq!(proof.responder_node_id, local_node_id.to_string());
    assert_eq!(proof.responder_public_key, identity.public_key);
    verify_cluster_invite_challenge_proof(&invite, &request.challenge, &proof)
        .expect("created proof verifies");
}

fn invite_control_root_identity(root: &std::path::Path) -> Option<(u64, u64)> {
    #[cfg(unix)]
    {
        use std::os::unix::fs::MetadataExt;
        let metadata = std::fs::metadata(root).ok()?;
        Some((metadata.dev(), metadata.ino()))
    }
    #[cfg(not(unix))]
    {
        let _ = root;
        None
    }
}

// Same real signer/read path and single-voter current-term authority as the
// existing fixture. No remote host can supply an acknowledgement or proof.
#[test]
fn native_invite_challenge_reads_idle_resident_while_operation_owner_is_held() {
    let (_root, paths, identity, invite, request) = native_invite_challenge_fixture();
    let node_id = read_cluster_state_without_kv(&paths).unwrap().local_node_id;
    let wal = paths.kv_paths().raft_wal_paths(&node_id);
    let _pin = sinomo_kv::pin_resident_raft_node_registry_for_test(&wal).unwrap();
    assert!(
        sinomo_kv::with_cluster_kv_resident_read_projection(&wal, &node_id, |resident| resident
            .read_index_state(),)
        .is_some(),
        "the real canonical resident is idle before admission"
    );
    let owner = sinomo_kv::lock_cluster_kv_raft_operation_for_paths(&paths.kv_paths())
        .expect("actual operation admission owner");
    let observed = sinomo_kv::cluster_kv_raft_operation_owner_for_test(&paths.kv_paths())
        .expect("live held owner must be observable");
    let runtime = tokio::runtime::Runtime::new().unwrap();
    let start = Instant::now();
    let result = runtime.block_on(async {
        tokio::time::timeout_at(
            tokio::time::Instant::from_std(start + Duration::from_secs(20)),
            create_cluster_invite_challenge_proof(
                &paths,
                &identity,
                &request,
                &InviteChallengeNativeAccess {
                    paths: &paths,
                    allow_forwarding: true,
                },
            ),
        )
        .await
    });
    let after = sinomo_kv::cluster_kv_raft_operation_owner_for_test(&paths.kv_paths());
    eprintln!(
        "ADMISSION_CONTROL {}",
        serde_json::json!({
            "operation_root": paths.kv_paths().root, "resident_root": wal.root,
            "owner_before": observed, "owner_after": after,
            "elapsed_ms": start.elapsed().as_millis(), "result": format!("{result:?}"),
            "physical_root": {
            "metadata": format!("{:?}", std::fs::metadata(&paths.root)),
            "unix_device_inode": invite_control_root_identity(&paths.root),
        },
            "capture": "one synchronous before and after snapshot; no historical coverage claimed",
        })
    );
    assert_eq!(after, Some(observed));
    assert_eq!(
        sinomo_kv::cluster_kv_raft_operation_queue_depth_for_test(&paths.kv_paths()),
        0
    );
    drop(owner);
    assert!(sinomo_kv::cluster_kv_raft_operation_owner_for_test(&paths.kv_paths()).is_none());
    let proof = result
        .expect("unchanged 20-second challenge budget")
        .expect("an idle canonical resident must not require the mutation operation permit");
    verify_cluster_invite_challenge_proof(&invite, &request.challenge, &proof).unwrap();
}

#[test]
fn native_invite_challenge_mutable_owner_cancellation_and_release_are_fail_closed() {
    let (_root, paths, identity, invite, request) = native_invite_challenge_fixture();
    let node_id = read_cluster_state_without_kv(&paths).unwrap().local_node_id;
    let runtime = tokio::runtime::Runtime::new().unwrap();
    let owner = sinomo_kv::lock_cluster_kv_raft_operation_for_paths(&paths.kv_paths()).unwrap();
    let observed = sinomo_kv::cluster_kv_raft_operation_owner_for_test(&paths.kv_paths()).unwrap();
    let resident = open_cluster_raft_kv_node(&paths, &node_id).unwrap();
    let access = InviteChallengeNativeAccess {
        paths: &paths,
        allow_forwarding: true,
    };
    let failed = runtime.block_on(create_cluster_invite_challenge_proof(
        &paths, &identity, &request, &access,
    ));
    assert!(
        matches!(&failed, Err(NetworkError::ClusterReadOnly { detail }) if detail.contains("admission is busy")),
        "{failed:?}"
    );
    let cancelled = runtime.block_on(async {
        tokio::time::timeout(
            Duration::from_millis(20),
            create_cluster_invite_challenge_proof(&paths, &identity, &request, &access),
        )
        .await
    });
    assert!(
        cancelled.is_err(),
        "caller cancellation must not mint a proof"
    );
    let after = sinomo_kv::cluster_kv_raft_operation_owner_for_test(&paths.kv_paths());
    eprintln!(
        "ADMISSION_CONTROL {}",
        serde_json::json!({
            "operation_root": paths.kv_paths().root,
            "resident_root": paths.kv_paths().raft_wal_paths(&node_id).root,
            "owner_before": observed, "owner_after_cancellation": after,
            "failed_read": format!("{failed:?}"), "cancelled": cancelled.is_err(),
        })
    );
    assert_eq!(after, Some(observed));
    assert_eq!(
        sinomo_kv::cluster_kv_raft_operation_queue_depth_for_test(&paths.kv_paths()),
        0
    );
    drop(resident);
    drop(owner);
    assert!(sinomo_kv::cluster_kv_raft_operation_owner_for_test(&paths.kv_paths()).is_none());
    let proof = runtime
        .block_on(create_cluster_invite_challenge_proof(
            &paths, &identity, &request, &access,
        ))
        .expect("actual owner release permits progress");
    verify_cluster_invite_challenge_proof(&invite, &request.challenge, &proof).unwrap();
    let successor = sinomo_kv::lock_cluster_kv_raft_operation_for_paths(&paths.kv_paths()).unwrap();
    let successor_observation =
        sinomo_kv::cluster_kv_raft_operation_owner_for_test(&paths.kv_paths()).unwrap();
    assert_ne!(
        successor_observation.0,
        after.unwrap().0,
        "successor has a distinct permit lifetime"
    );
    drop(successor);
}

