#[test]
fn main_daemon_command_targets_filter_known_unreachable_endpoints() {
    let root = sinomo_testdir::TestDir::new("sinomo-network-main-daemon-targets-unreachable");
    let data_dir = SinomoDataDir::new(&root);
    let paths = ClusterPaths::new(&data_dir);
    paths.ensure().expect("paths");
    let now = OffsetDateTime::now_utc();
    let cluster_id =
        ClusterId::from_legacy_named("cluster_network_main_daemon_unreachable").expect("cluster");
    let local =
        NodeId::from_legacy_named("node_network_main_daemon_unreachable_local").expect("local");
    let remote =
        NodeId::from_legacy_named("node_network_main_daemon_unreachable_remote").expect("remote");
    let mut state = ClusterBootstrapState::initialized_locally(
        cluster_id.clone(),
        "network main daemon unreachable",
        local,
        "local",
        "pk-local",
        now,
    );
    let stale_tcp = daemon_lan_endpoint(&remote, "10.0.0.41:21353".to_string(), 10);
    let mut member =
        ClusterMemberRecord::local_voter(cluster_id, remote, "remote", "pk-remote", now);
    member.capabilities = main_daemon_capabilities(&member.role);
    member.allowed_capabilities = member.capabilities.clone();
    member.endpoints = vec![stale_tcp.clone()];
    state.members.push(member);
    write_cluster_state(&paths, &state).expect("write state");
    sync_cluster_state_to_local_raft_unchecked(&paths, &state).expect("sync state");
    sync_cluster_connectivity_records_to_kv(
        &paths,
        &state.local_node_id,
        vec![cluster_connectivity_record(
            &state,
            &stale_tcp,
            ClusterConnectivityState::Unreachable,
            None,
            CLUSTER_CONNECTIVITY_FAILURE_THRESHOLD,
            None,
            Some("identity mismatch".to_string()),
            now,
            60,
        )],
    )
    .expect("connectivity records");

    let targets = ClusterEndpointSelector::new(&paths, &state)
        .select(ClusterEndpointSelectionPurpose::MainDaemonCommand);

    assert!(
        targets.is_empty(),
        "known-unreachable direct endpoints should not remain daemon command targets"
    );
    let data_plane_targets = ClusterEndpointSelector::new(&paths, &state)
        .select(ClusterEndpointSelectionPurpose::MainDaemonDataPlane);
    assert_eq!(
        data_plane_targets
            .iter()
            .map(|endpoint| &endpoint.endpoint_id)
            .collect::<Vec<_>>(),
        vec![&stale_tcp.endpoint_id],
        "main-daemon data-plane routing should keep the target record so relay can handle known-bad direct paths"
    );
}

#[test]
fn main_daemon_data_plane_targets_include_kv_main_daemon_endpoints() {
    install_kv_directory_for_tests();
    let root = sinomo_testdir::TestDir::new("sinomo-network-main-data-kv-endpoints");
    let data_dir = SinomoDataDir::new(&root);
    let paths = ClusterPaths::new(&data_dir);
    paths.ensure().expect("paths");
    let now = OffsetDateTime::now_utc();
    let cluster_id =
        ClusterId::from_legacy_named("cluster_network_main_data_kv_endpoints").expect("cluster");
    let local = NodeId::from_legacy_named("node_network_main_data_kv_local").expect("local");
    let remote = NodeId::from_legacy_named("node_network_main_data_kv_remote").expect("remote");
    let shadow = sinomo_node::shadow_daemon_node_id(&remote);
    let mut state = ClusterBootstrapState::initialized_locally(
        cluster_id.clone(),
        "network main data-plane kv endpoints",
        local.clone(),
        "local",
        "pk-local",
        now,
    );
    let mut folded_shadow_endpoint =
        daemon_lan_endpoint(&shadow, "192.0.2.54:21354".to_string(), 0);
    folded_shadow_endpoint.node_id = remote.clone();
    let direct_main_endpoint = daemon_lan_endpoint(&remote, "198.51.100.54:21353".to_string(), 0);
    let mut member =
        ClusterMemberRecord::local_voter(cluster_id, remote.clone(), "remote", "pk-remote", now);
    member.capabilities = main_daemon_capabilities(&member.role);
    member.allowed_capabilities = member.capabilities.clone();
    member.endpoints = vec![folded_shadow_endpoint.clone()];
    state.members.push(member);
    write_cluster_state(&paths, &state).expect("write state");
    sync_cluster_state_to_local_raft_unchecked(&paths, &state).expect("sync state");
    append_cluster_raft_command(
        &paths,
        &local,
        sinomo_kv::KvCommand::Op(
            sinomo_kv::KvOp::put_serde(
                cluster_endpoint_key(&remote, &direct_main_endpoint),
                &direct_main_endpoint,
                None,
            )
            .expect("endpoint op"),
        ),
    )
    .expect("write endpoint record");
    sync_cluster_node_status_to_kv(
        &paths,
        ClusterNodeStatusRecord {
            cluster_id: state.cluster_id.clone(),
            node_id: remote.clone(),
            process: sinomo_node::DAEMON_MAIN_CLUSTER_ROLE.to_string(),
            availability: ClusterNodeAvailability::Offline,
            daemon_version: "0.1.0-test".to_string(),
            commit: None,
            target_os: Some("test-os".to_string()),
            target_arch: Some("test-arch".to_string()),
            hostname: None,
            pid: Some(42),
            address: Some("127.0.0.1:21353".to_string()),
            bind_address: Some("0.0.0.0:21353".to_string()),
            executable: Some("sinomo".to_string()),
            rollout: None,
            daemon_started_at: None,
            observed_at: now,
        },
    )
    .expect("write stale offline status");

    let selector = ClusterEndpointSelector::new(&paths, &state);
    let data_plane_targets = selector.select(ClusterEndpointSelectionPurpose::MainDaemonDataPlane);
    let raft_targets = selector.select(ClusterEndpointSelectionPurpose::ClusterStateCommand);
    let main_targets = selector.select(ClusterEndpointSelectionPurpose::MainDaemonCommand);

    assert!(
        data_plane_targets
            .iter()
            .any(|endpoint| endpoint.endpoint_id == direct_main_endpoint.endpoint_id),
        "main-daemon data-plane selection should include main daemon endpoints from cluster KV"
    );
    assert_eq!(
        data_plane_targets
            .iter()
            .filter(|endpoint| endpoint.node_id == remote)
            .map(|endpoint| endpoint.endpoint_id.clone())
            .collect::<Vec<_>>(),
        vec![direct_main_endpoint.endpoint_id.clone()],
        "main-daemon data-plane selection must use the KV main endpoint instead of folded shadow endpoints"
    );
    assert!(
        raft_targets
            .iter()
            .any(|endpoint| endpoint.endpoint_id == direct_main_endpoint.endpoint_id),
        "Raft command selection should include main daemon endpoints from cluster KV"
    );
    assert!(
        raft_targets
            .iter()
            .all(|endpoint| endpoint.endpoint_id != folded_shadow_endpoint.endpoint_id),
        "Raft command selection must not route consensus traffic to folded shadow endpoints"
    );
    assert!(
        main_targets
            .iter()
            .any(|endpoint| endpoint.endpoint_id == direct_main_endpoint.endpoint_id),
        "main daemon command selection should include main daemon endpoints from cluster KV"
    );
}

