#[test]
fn default_lan_ip_discovery_cache_reuses_recent_result() {
    let _guard = PUBLIC_ENDPOINT_CACHE_TEST_MUTEX
        .lock()
        .expect("cache mutex");
    sinomo_network::clear_default_lan_ip_discovery_cache();
    let calls = std::sync::atomic::AtomicU64::new(0);
    let first = sinomo_network::cached_default_lan_ip_candidates_with(|| {
        calls.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
        vec!["10.0.0.11".parse().expect("ip")]
    });
    let second = sinomo_network::cached_default_lan_ip_candidates_with(|| {
        calls.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
        vec!["10.0.0.12".parse().expect("ip")]
    });

    assert_eq!(first, vec!["10.0.0.11".parse::<IpAddr>().expect("ip")]);
    assert_eq!(
        second, first,
        "bursty LAN IP discovery should reuse the short cache"
    );
    assert_eq!(calls.load(std::sync::atomic::Ordering::Relaxed), 1);
    sinomo_network::clear_default_lan_ip_discovery_cache();
}

#[tokio::test(flavor = "current_thread")]
// The cache under test is process-global, so the cross-test mutex must cover
// both async cache calls. This current-thread test never reacquires it.
#[allow(clippy::await_holding_lock)]
async fn async_default_lan_ip_discovery_cache_reuses_recent_result() {
    let _guard = PUBLIC_ENDPOINT_CACHE_TEST_MUTEX
        .lock()
        .expect("cache mutex");
    sinomo_network::clear_default_lan_ip_discovery_cache();
    let calls = std::sync::atomic::AtomicU64::new(0);
    let first = sinomo_network::cached_default_lan_ip_candidates_with_async(|| async {
        calls.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
        vec!["10.0.0.21".parse().expect("ip")]
    })
    .await;
    let second = sinomo_network::cached_default_lan_ip_candidates_with_async(|| async {
        calls.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
        vec!["10.0.0.22".parse().expect("ip")]
    })
    .await;

    assert_eq!(first, vec!["10.0.0.21".parse::<IpAddr>().expect("ip")]);
    assert_eq!(
        second, first,
        "bursty async LAN IP discovery should reuse the short cache"
    );
    assert_eq!(calls.load(std::sync::atomic::Ordering::Relaxed), 1);
    sinomo_network::clear_default_lan_ip_discovery_cache();
}

