#[test]
fn cluster_member_removal_txns_bound_large_endpoint_prefix_cleanup() {
    let now = OffsetDateTime::now_utc();
    let cluster_id =
        ClusterId::from_legacy_named("cluster_network_removal_endpoint_limit").expect("cluster");
    let node_id = NodeId::from_legacy_named("node_network_removal_endpoint_limit").expect("node");
    let mut member = ClusterMemberRecord::pending_learner(
        cluster_id,
        node_id.clone(),
        "removal endpoint limit",
        "pk-removal-endpoint-limit",
        now,
    );
    member.state = ClusterMemberState::NonVoting;
    member.role = ClusterMemberRole::NonVoting;
    member.capabilities = sinomo_node::main_daemon_capabilities(&ClusterMemberRole::NonVoting);
    member.allowed_capabilities = member.capabilities.clone();
    member.endpoints = (0..=sinomo_kv::MAX_KV_MUTATION_EVENTS_PER_COMMAND)
        .map(|index| ClusterEndpointRecord {
            endpoint_id: ClusterEndpointId::from_legacy_named(format!(
                "endpoint_network_removal_limit_{index}"
            ))
            .expect("endpoint"),
            node_id: node_id.clone(),
            transport: ClusterTransportKind::LanTcp,
            address: format!("127.0.0.1:{}", 20_000 + index),
            source: ClusterEndpointSource::Static,
            privacy: ClusterEndpointPrivacy::Lan,
            priority: 0,
            last_observed_latency_ms: None,
        })
        .collect();

    let member_key = cluster_member_key(&node_id);
    let policy_key = cluster_capability_policy_key(&node_id);
    let endpoint_prefix = cluster_endpoint_prefix(&node_id);
    let mut store = InProcessKvStore::new();
    store
        .put_serde(member_key.clone(), &member, None)
        .expect("member");
    store
        .put_serde(
            policy_key.clone(),
            &ClusterCapabilityPolicyRecord::from(&member),
            None,
        )
        .expect("policy");
    for endpoint in &member.endpoints {
        store
            .put_serde(cluster_endpoint_key(&node_id, endpoint), endpoint, None)
            .expect("endpoint");
    }

    let txns = cluster_member_removal_txns_from_store(&store, std::slice::from_ref(&member))
        .expect("txns");

    assert!(
        txns.len() > 1,
        "large endpoint prefixes should be split before final removal"
    );
    assert!(
        txns.iter()
            .all(|txn| txn.success.len() <= sinomo_kv::MAX_KV_TXN_OPS_PER_BRANCH),
        "all removal transactions must fit within the KV branch op limit"
    );
    for txn in &txns[..txns.len() - 1] {
        assert!(
            txn.success.iter().all(|op| !matches!(
                op,
                KvOp::DeletePrefix { prefix } if prefix == &endpoint_prefix
            )),
            "pre-final removal batches should use explicit deletes"
        );
    }
    assert!(
        txns.last().is_some_and(|txn| txn.success.iter().any(|op| {
            matches!(op, KvOp::DeletePrefix { prefix } if prefix == &endpoint_prefix)
        })),
        "final removal should keep a prefix cleanup for residual endpoint keys"
    );

    for txn in txns {
        store
            .apply_command(KvCommand::Txn(txn))
            .expect("apply removal txn");
    }

    assert!(store.get(&member_key).is_none(), "member should be removed");
    assert!(store.get(&policy_key).is_none(), "policy should be removed");
    assert!(
        store
            .range_prefix(&endpoint_prefix)
            .expect("range prefix")
            .is_empty(),
        "endpoint records should be removed"
    );
}

#[test]
fn cleanup_legacy_shadow_daemon_members_removes_only_shadow_only_records() {
    struct MemoryMutationHost {
        store: InProcessKvStore,
        commits: usize,
    }

    impl ClusterMemberMutationHost for MemoryMutationHost {
        fn authoritative_cluster_kv_snapshot(
            &mut self,
            _paths: &ClusterPaths,
            _state: &mut ClusterBootstrapState,
        ) -> Result<sinomo_kv::KvAuthoritativeRead<KvSnapshot>, NetworkError> {
            let snapshot = self.store.try_snapshot().map_err(kv_err)?;
            Ok(sinomo_kv::KvAuthoritativeRead {
                authority: test_current_quorum_authority(&snapshot),
                value: snapshot,
            })
        }

        fn commit_cluster_kv_txn_with_quorum(
            &mut self,
            _paths: &ClusterPaths,
            _state: &mut ClusterBootstrapState,
            request: KvTxnRequest,
        ) -> Result<ClusterKvTxnCommitResult, NetworkError> {
            self.commits += 1;
            let response = self.store.txn(request.txn).map_err(kv_err)?;
            Ok(test_cluster_kv_txn_commit_result(
                self.store.snapshot().expect("snapshot"),
                Some(response),
            ))
        }
    }

    let root = sinomo_testdir::TestDir::new("sinomo-network-cleanup-legacy-shadow-members");
    let data_dir = SinomoDataDir::new(&root);
    let paths = ClusterPaths::new(&data_dir);
    paths.ensure().expect("cluster paths");
    let now = OffsetDateTime::now_utc();
    let cluster_id =
        ClusterId::from_legacy_named("cluster_cleanup_legacy_shadow").expect("cluster");
    let local_node_id =
        NodeId::from_legacy_named("node_cleanup_legacy_shadow_local").expect("local");
    let local_shadow_node_id = shadow_daemon_node_id(&local_node_id);
    let remote_node_id =
        NodeId::from_legacy_named("node_cleanup_legacy_shadow_remote").expect("remote");
    let remote_shadow_node_id = shadow_daemon_node_id(&remote_node_id);
    let mut state = ClusterBootstrapState::initialized_locally(
        cluster_id.clone(),
        "legacy shadow cleanup",
        local_node_id.clone(),
        "local",
        "pk-local",
        now,
    );
    state.members[0].capabilities = main_daemon_capabilities(&state.members[0].role);
    state.members[0].allowed_capabilities = state.members[0].capabilities.clone();

    let mut remote_main = ClusterMemberRecord::local_voter(
        cluster_id.clone(),
        remote_node_id.clone(),
        "remote",
        "pk-remote",
        now,
    );
    remote_main.capabilities = main_daemon_capabilities(&remote_main.role);
    remote_main.allowed_capabilities = remote_main.capabilities.clone();

    let mut local_shadow = ClusterMemberRecord::local_non_voting(
        cluster_id.clone(),
        local_shadow_node_id.clone(),
        "local shadow",
        "pk-local-shadow",
        now,
    );
    local_shadow.capabilities = vec![
        CapabilityName::new(sinomo_node::DAEMON_SHADOW_SUPERVISE_CAPABILITY)
            .expect("shadow capability"),
    ];
    local_shadow.allowed_capabilities = local_shadow.capabilities.clone();
    local_shadow.endpoints = vec![daemon_lan_endpoint(
        &local_shadow_node_id,
        "127.0.0.1:21354".to_string(),
        10,
    )];

    let mut remote_shadow = ClusterMemberRecord::local_non_voting(
        cluster_id.clone(),
        remote_shadow_node_id.clone(),
        "remote shadow",
        "pk-remote-shadow",
        now,
    );
    remote_shadow.capabilities = vec![
        CapabilityName::new(sinomo_node::DAEMON_SHADOW_SUPERVISE_CAPABILITY)
            .expect("shadow capability"),
    ];
    remote_shadow.allowed_capabilities = remote_shadow.capabilities.clone();
    remote_shadow.endpoints = vec![daemon_lan_endpoint(
        &remote_shadow_node_id,
        "192.0.2.45:21354".to_string(),
        10,
    )];

    let mut host = MemoryMutationHost {
        store: InProcessKvStore::new(),
        commits: 0,
    };
    for member in [
        state.members[0].clone(),
        remote_main.clone(),
        local_shadow.clone(),
        remote_shadow.clone(),
    ] {
        host.store
            .put_serde(cluster_member_key(&member.node_id), &member, None)
            .expect("member");
        host.store
            .put_serde(
                cluster_capability_policy_key(&member.node_id),
                &ClusterCapabilityPolicyRecord::from(&member),
                None,
            )
            .expect("policy");
        for endpoint in &member.endpoints {
            host.store
                .put_serde(
                    cluster_endpoint_key(&member.node_id, endpoint),
                    endpoint,
                    None,
                )
                .expect("endpoint");
        }
    }
    let local_shadow_connectivity = doctor_connectivity_record(
        &cluster_id,
        &local_node_id,
        &local_shadow_node_id,
        "endpoint_cleanup_legacy_local_shadow",
        "127.0.0.1:21354",
        ClusterConnectivityState::Unreachable,
    );
    let remote_shadow_connectivity = doctor_connectivity_record(
        &cluster_id,
        &remote_shadow_node_id,
        &remote_node_id,
        "endpoint_cleanup_legacy_remote_shadow",
        "192.0.2.45:21354",
        ClusterConnectivityState::Unreachable,
    );
    let retained_connectivity = doctor_connectivity_record(
        &cluster_id,
        &local_node_id,
        &remote_node_id,
        "endpoint_cleanup_legacy_main_peer",
        "192.0.2.45:21353",
        ClusterConnectivityState::Healthy,
    );
    let retained_connectivity_key = cluster_connectivity_key(
        &retained_connectivity.source_node_id,
        &retained_connectivity.target_node_id,
        &retained_connectivity.endpoint_id,
    );
    for record in [
        &local_shadow_connectivity,
        &remote_shadow_connectivity,
        &retained_connectivity,
    ] {
        host.store
            .put_serde(
                cluster_connectivity_key(
                    &record.source_node_id,
                    &record.target_node_id,
                    &record.endpoint_id,
                ),
                record,
                None,
            )
            .expect("connectivity");
    }

    let removal = cleanup_legacy_shadow_daemon_members_with_host(&paths, state.clone(), &mut host)
        .expect("cleanup");
    let removed_node_ids = removal
        .removed
        .iter()
        .map(|member| member.node_id.clone())
        .collect::<Vec<_>>();

    assert_eq!(
        removed_node_ids,
        vec![local_shadow_node_id, remote_shadow_node_id]
    );
    assert!(host.commits >= 1);
    assert!(
        host.store
            .get(&cluster_member_key(&local_node_id))
            .is_some()
    );
    assert!(
        host.store
            .get(&cluster_member_key(&remote_node_id))
            .is_some()
    );
    for member in [local_shadow, remote_shadow] {
        assert!(
            host.store
                .get(&cluster_member_key(&member.node_id))
                .is_none()
        );
        assert!(
            host.store
                .get(&cluster_capability_policy_key(&member.node_id))
                .is_none()
        );
        for endpoint in &member.endpoints {
            assert!(
                host.store
                    .get(&cluster_endpoint_key(&member.node_id, endpoint))
                    .is_none()
            );
        }
    }
    assert!(
        host.store.get(&retained_connectivity_key).is_some(),
        "main-member connectivity should be retained"
    );
    for record in [local_shadow_connectivity, remote_shadow_connectivity] {
        assert!(
            host.store
                .get(&cluster_connectivity_key(
                    &record.source_node_id,
                    &record.target_node_id,
                    &record.endpoint_id,
                ))
                .is_none(),
            "shadow connectivity should be removed"
        );
    }

    let orphan_shadow_node_id =
        NodeId::from_legacy_named("node_cleanup_legacy_shadow_orphan").expect("orphan shadow");
    let orphan_status = ClusterNodeStatusRecord {
        cluster_id: cluster_id.clone(),
        node_id: orphan_shadow_node_id.clone(),
        process: sinomo_node::DAEMON_SHADOW_CLUSTER_ROLE.to_string(),
        availability: ClusterNodeAvailability::Offline,
        daemon_version: "0.1.0".to_string(),
        commit: None,
        target_os: None,
        target_arch: None,
        hostname: None,
        pid: None,
        address: None,
        bind_address: None,
        executable: None,
        rollout: None,
        daemon_started_at: None,
        observed_at: now,
    };
    let orphan_connectivity = doctor_connectivity_record(
        &cluster_id,
        &local_node_id,
        &orphan_shadow_node_id,
        "endpoint_cleanup_legacy_orphan_shadow",
        "127.0.0.1:21354",
        ClusterConnectivityState::Unreachable,
    );
    let orphan_connectivity_key = cluster_connectivity_key(
        &orphan_connectivity.source_node_id,
        &orphan_connectivity.target_node_id,
        &orphan_connectivity.endpoint_id,
    );
    host.store
        .put_serde(
            cluster_node_status_key_for_process(
                &orphan_shadow_node_id,
                sinomo_node::DAEMON_SHADOW_CLUSTER_ROLE,
            ),
            &orphan_status,
            None,
        )
        .expect("orphan status");
    host.store
        .put_serde(orphan_connectivity_key.clone(), &orphan_connectivity, None)
        .expect("orphan connectivity");

    let orphan_cleanup = cleanup_legacy_shadow_daemon_members_with_host(&paths, state, &mut host)
        .expect("orphan cleanup");
    assert!(
        orphan_cleanup.removed.is_empty(),
        "orphan artifact cleanup should not report member removals"
    );
    assert!(
        host.store.get(&orphan_connectivity_key).is_none(),
        "orphan shadow connectivity should be removed"
    );
    assert!(
        host.store
            .get(&cluster_node_status_key_for_process(
                &orphan_shadow_node_id,
                sinomo_node::DAEMON_SHADOW_CLUSTER_ROLE
            ))
            .is_none(),
        "orphan shadow status should be removed"
    );
}

#[test]
fn raft_heartbeat_does_not_rewrite_materialized_snapshot() {
    let root = sinomo_testdir::TestDir::new("sinomo-network-raft-heartbeat-snapshot");
    let data_dir = SinomoDataDir::new(&root);
    let paths = ClusterPaths::new(&data_dir);
    paths.ensure().expect("cluster paths");
    let node_id = NodeId::from_legacy_named("node_heartbeat_snapshot").expect("node");

    append_cluster_raft_command(
        &paths,
        &node_id,
        KvCommand::Op(KvOp::Put {
            key: "/committed".to_string(),
            value: b"committed".to_vec(),
            lease_id: None,
        }),
    )
    .expect("seed committed snapshot");
    let heartbeat = {
        let node = open_cluster_raft_kv_node(&paths, &node_id).expect("open raft");
        RaftAppendEntriesRequest {
            term: node.hard_state().current_term,
            leader_id: node_id.clone(),
            prev_log_index: node.last_log_index(),
            prev_log_term: node.last_log_term(),
            entries: Vec::new(),
            leader_commit: node.hard_state().commit_index,
        }
    };
    std::fs::write(&paths.kv_paths().snapshot, b"sentinel snapshot").expect("sentinel snapshot");

    let response =
        apply_cluster_raft_append(&paths, &node_id, None, heartbeat).expect("apply heartbeat");

    assert!(response.success);
    assert_eq!(
        std::fs::read(&paths.kv_paths().snapshot).expect("read snapshot"),
        b"sentinel snapshot"
    );
}

fn mark_test_member_as_voter(member: &mut ClusterMemberRecord) {
    member.role = ClusterMemberRole::Voter;
    member.state = ClusterMemberState::Voter;
    member.capabilities = vec![CapabilityName::new("daemon.main.run").expect("capability")];
    member.allowed_capabilities = member.capabilities.clone();
}

fn cluster_raft_handler_test_state(
    cluster_name: &str,
    local_name: &str,
    peer_name: &str,
) -> (ClusterBootstrapState, NodeId, NodeId) {
    let now = OffsetDateTime::now_utc();
    let cluster_id = ClusterId::from_legacy_named(cluster_name).expect("cluster");
    let local_node_id = NodeId::from_legacy_named(local_name).expect("local");
    let peer_node_id = NodeId::from_legacy_named(peer_name).expect("peer");
    let mut state = ClusterBootstrapState::initialized_locally(
        cluster_id,
        "raft handler",
        local_node_id.clone(),
        "local",
        "local-public-key",
        now,
    );
    mark_test_member_as_voter(
        state
            .members
            .iter_mut()
            .find(|member| member.node_id == local_node_id)
            .expect("local member"),
    );
    let mut peer = state.members[0].clone();
    peer.node_id = peer_node_id.clone();
    peer.display_name = "peer".to_string();
    peer.node_public_key = "peer-public-key".to_string();
    peer.endpoints.clear();
    peer.joined_at = now;
    peer.updated_at = now;
    mark_test_member_as_voter(&mut peer);
    state.members.push(peer);
    (state, local_node_id, peer_node_id)
}

fn seed_marked_read_index_receiver(
    paths: &ClusterPaths,
    cluster_name: &str,
    local_name: &str,
    peer_name: &str,
) -> (
    ClusterBootstrapState,
    NodeId,
    NodeId,
    ClusterRaftAppendRequest,
    ClusterAuthenticatedPeer,
    sinomo_kv::ResidentRaftNodeRegistryPin,
) {
    let (state, local_node_id, peer_node_id) =
        cluster_raft_handler_test_state(cluster_name, local_name, peer_name);
    write_cluster_state(paths, &state).expect("write receiver state");
    let mut leader_state = state.clone();
    leader_state.local_node_id = peer_node_id.clone();
    let authenticated_peer = ClusterAuthenticatedPeer {
        node_id: peer_node_id.to_string(),
        public_key: "peer-public-key".to_string(),
    };
    let resident_pin = sinomo_kv::pin_resident_raft_node_registry_for_test(
        &paths.kv_paths().raft_wal_paths(&local_node_id),
    )
    .expect("pin receiver resident registry slot");
    let heartbeat = ClusterRaftAppendRequest {
        state: leader_state.clone(),
        snapshot: None,
        read_index_probe: false,
        append: RaftAppendEntriesRequest {
            term: 1,
            leader_id: peer_node_id.clone(),
            prev_log_index: 0,
            prev_log_term: 0,
            entries: Vec::new(),
            leader_commit: 0,
        },
    };
    let response = handle_cluster_raft_append_request(paths, heartbeat, &authenticated_peer)
        .expect("seed follower resident state");
    assert!(response.accepted);
    let probe = ClusterRaftAppendRequest {
        state: leader_state,
        snapshot: None,
        read_index_probe: true,
        append: RaftAppendEntriesRequest {
            term: 1,
            leader_id: peer_node_id.clone(),
            prev_log_index: 0,
            prev_log_term: 0,
            entries: Vec::new(),
            leader_commit: 0,
        },
    };
    (
        state,
        local_node_id,
        peer_node_id,
        probe,
        authenticated_peer,
        resident_pin,
    )
}

