#[test]
fn cluster_raft_vote_handler_rejects_stale_local_voter_from_exact_resident_config() {
    let root = sinomo_testdir::TestDir::new("sinomo-network-raft-vote-exact-config");
    let paths = ClusterPaths::new(&SinomoDataDir::new(&root));
    paths.ensure().expect("cluster paths");
    let (state, local_node_id, candidate_node_id) = cluster_raft_handler_test_state(
        "cluster_raft_vote_exact_config",
        "node_raft_vote_exact_config_local",
        "node_raft_vote_exact_config_candidate",
    );
    write_cluster_state(&paths, &state).expect("write stale bootstrap state");
    let config = ClusterKvRaftConfigRecord {
        cluster_id: state.cluster_id.clone(),
        term: 1,
        kv_revision: 1,
        voters: vec![local_node_id.clone()],
        learners: Vec::new(),
        non_voting: vec![candidate_node_id.clone()],
        updated_at: OffsetDateTime::now_utc(),
    };
    let mut store = InProcessKvStore::new();
    store
        .put_serde(sinomo_kv::cluster_kv_raft_config_key(), &config, None)
        .expect("encode committed config");
    {
        let mut node = open_cluster_raft_kv_node(&paths, &local_node_id).expect("open follower");
        node.apply_append_entries_with_optional_snapshot(
            Some(RaftSnapshot {
                last_included_index: 1,
                last_included_term: 1,
                kv: (store.snapshot().expect("config snapshot")).into(),
            }),
            RaftAppendEntriesRequest {
                term: 1,
                leader_id: candidate_node_id.clone(),
                prev_log_index: 1,
                prev_log_term: 1,
                entries: Vec::new(),
                leader_commit: 1,
            },
        )
        .expect("install exact config");
    }
    let mut candidate_state = state.clone();
    candidate_state.local_node_id = candidate_node_id.clone();

    let runtime = tokio::runtime::Builder::new_current_thread()
        .enable_all()
        .build()
        .expect("runtime");
    let response = runtime
        .block_on(handle_cluster_raft_vote_request_async(
            runtime.handle(),
            &paths,
            ClusterRaftVoteRequest {
                state: candidate_state,
                vote: RaftRequestVoteRequest {
                    term: 2,
                    candidate_id: candidate_node_id.clone(),
                    last_log_index: 1,
                    last_log_term: 1,
                },
            },
            &ClusterAuthenticatedPeer {
                node_id: candidate_node_id.to_string(),
                public_key: "peer-public-key".to_string(),
            },
        ))
        .expect("exact-config vote rejection must not race the higher-term closer");

    assert!(!response.accepted);
    assert!(!response.vote.vote_granted);
    assert!(response.detail.contains("unauthorized or mismatched"));
    assert_eq!(
        response
            .state
            .members
            .iter()
            .find(|member| member.node_id == candidate_node_id)
            .expect("candidate projection")
            .role,
        ClusterMemberRole::NonVoting
    );
}

#[test]
fn cancelled_admitted_vote_finishes_durability_before_a_subsequent_vote() {
    let root = sinomo_testdir::TestDir::new("sinomo-raft-vote-admitted-cancel");
    let paths = ClusterPaths::new(&SinomoDataDir::new(&root));
    paths.ensure().expect("cluster paths");
    let (state, local_node_id, candidate_node_id) = cluster_raft_handler_test_state(
        "cluster_raft_vote_admitted_cancel",
        "node_raft_vote_admitted_cancel_local",
        "node_raft_vote_admitted_cancel_candidate",
    );
    write_cluster_state(&paths, &state).expect("write state");
    let mut candidate_state = state.clone();
    candidate_state.local_node_id = candidate_node_id.clone();
    let request = ClusterRaftVoteRequest {
        state: candidate_state,
        vote: RaftRequestVoteRequest {
            term: 2,
            candidate_id: candidate_node_id.clone(),
            last_log_index: 0,
            last_log_term: 0,
        },
    };
    let peer = ClusterAuthenticatedPeer {
        node_id: candidate_node_id.to_string(),
        public_key: "peer-public-key".to_string(),
    };
    let operation_guard = sinomo_kv::lock_cluster_kv_raft_operation_for_paths(&paths.kv_paths())
        .expect("hold durable operation lock");
    let runtime = tokio::runtime::Builder::new_multi_thread()
        .worker_threads(2)
        .max_blocking_threads(2)
        .enable_all()
        .build()
        .expect("runtime");
    let request_paths = paths.clone();
    let cancelled_request = request.clone();
    let cancelled_peer = peer.clone();
    let vote = runtime.spawn(async move {
        handle_cluster_raft_vote_request_async(
            &tokio::runtime::Handle::current(),
            &request_paths,
            cancelled_request,
            &cancelled_peer,
        )
        .await
    });
    let admission_deadline = Instant::now() + Duration::from_secs(1);
    while sinomo_kv::cluster_kv_raft_operation_queue_depth_for_test(&paths.kv_paths()) != 1 {
        assert!(
            Instant::now() < admission_deadline,
            "vote blocking work never won admission"
        );
        std::thread::yield_now();
    }
    vote.abort();
    runtime.block_on(async {
        let _ = vote.await;
    });
    drop(operation_guard);

    // The canceled caller no longer owns a result receiver, but the admitted
    // worker remains supervised and serializes the next vote behind its exact
    // durable term/voted-for update.
    let response = runtime
        .block_on(async {
            tokio::time::timeout(
                Duration::from_secs(1),
                handle_cluster_raft_vote_request_async(runtime.handle(), &paths, request, &peer),
            )
            .await
        })
        .expect("subsequent vote must not hang behind canceled admitted work")
        .expect("subsequent vote response");
    assert!(response.accepted);
    assert!(response.vote.vote_granted);
    assert_eq!(
        read_cluster_state_without_kv(&paths)
            .expect("read projected vote term")
            .term,
        2,
        "durable RequestVote term must suppress redundant same-term preflight closers"
    );
    let node = open_cluster_raft_kv_node(&paths, &local_node_id).expect("inspect durable vote");
    assert_eq!(node.hard_state().current_term, 2);
    assert_eq!(
        node.hard_state().voted_for.as_ref(),
        Some(&candidate_node_id)
    );
}

#[test]
fn local_cluster_raft_command_storage_appends_commits_and_discards_under_network_lock() {
    let root = sinomo_testdir::TestDir::new("sinomo-network-local-raft-command-storage");
    let data_dir = SinomoDataDir::new(&root);
    let paths = ClusterPaths::new(&data_dir);
    paths.ensure().expect("cluster paths");
    let local_node_id = NodeId::from_legacy_named("node_local_raft_command_storage").expect("node");
    let mut storage = LocalClusterRaftCommandStorage::new(&paths, local_node_id);

    let command = KvCommand::Op(KvOp::Put {
        key: "/raft/local-storage/committed".to_string(),
        value: b"committed".to_vec(),
        lease_id: None,
    });
    let index = storage
        .append_cluster_raft_request_uncommitted(KvCommandRequest::generated(command))
        .expect("append uncommitted")
        .index;

    let commit = storage
        .commit_cluster_raft_index_with_events(index)
        .expect("commit index");
    assert_eq!(
        commit
            .snapshot
            .get("/raft/local-storage/committed")
            .expect("committed entry")
            .value,
        b"committed".to_vec()
    );

    let discarded = KvCommand::Op(KvOp::Put {
        key: "/raft/local-storage/discarded".to_string(),
        value: b"discarded".to_vec(),
        lease_id: None,
    });
    let _ = storage
        .append_cluster_raft_request_uncommitted(KvCommandRequest::generated(discarded))
        .expect("append discarded command");
    storage
        .discard_cluster_raft_uncommitted_tail_and_clear_leader()
        .expect("discard uncommitted tail");
    let snapshot = read_cluster_kv_snapshot(&paths).expect("read materialized snapshot");
    assert!(
        snapshot.get("/raft/local-storage/discarded").is_none(),
        "discarded uncommitted command must not become materialized"
    );
}

struct RecordingRaftAppendHost {
    responses: Vec<ClusterRaftAppendResponse>,
    sent_prev_log_indexes: Vec<u64>,
    sent_timeouts: Vec<Duration>,
    sent_count: usize,
}

impl ClusterRaftAppendReplicationHost for RecordingRaftAppendHost {
    fn last_local_raft_log_index(
        &mut self,
        paths: &ClusterPaths,
        state: &ClusterBootstrapState,
    ) -> Result<u64, NetworkError> {
        Ok(open_cluster_raft_kv_node(paths, &state.local_node_id)?.last_log_index())
    }

    fn build_raft_append_request(
        &mut self,
        paths: &ClusterPaths,
        state: &ClusterBootstrapState,
        next_index: u64,
    ) -> Result<ClusterRaftAppendRequest, NetworkError> {
        paths
            .kv_paths()
            .build_raft_append_request_from_next_index(state, next_index)
            .map_err(kv_err)
    }

    fn send_raft_append(
        &mut self,
        _endpoint: &ClusterEndpointRecord,
        request: &ClusterRaftAppendRequest,
        timeout: Duration,
    ) -> Result<ClusterRaftAppendResponse, NetworkError> {
        self.sent_prev_log_indexes
            .push(request.append.prev_log_index);
        self.sent_timeouts.push(timeout);
        Ok(self.responses.remove(0))
    }

    fn on_raft_append_sent(&mut self) {
        self.sent_count += 1;
    }
}

#[derive(Default)]
struct RecordingQuorumCommitHost {
    paths: Option<ClusterPaths>,
    local_node_id: Option<NodeId>,
    failing_nodes: BTreeSet<NodeId>,
    replicated_nodes: Vec<NodeId>,
    connectivity: Vec<(NodeId, ClusterConnectivityState, bool)>,
    committed_indices: Vec<u64>,
    fanout_targets: Vec<NodeId>,
    fanout_events: usize,
    discarded: bool,
}

impl RecordingQuorumCommitHost {
    fn new(paths: ClusterPaths, local_node_id: NodeId) -> Self {
        Self {
            paths: Some(paths),
            local_node_id: Some(local_node_id),
            ..Self::default()
        }
    }

    fn paths(&self) -> &ClusterPaths {
        self.paths.as_ref().expect("quorum storage paths")
    }

    fn local_node_id(&self) -> &NodeId {
        self.local_node_id
            .as_ref()
            .expect("quorum storage local node id")
    }
}

impl sinomo_kv::ClusterKvRaftCommandStorage for RecordingQuorumCommitHost {
    type Error = NetworkError;

    fn kv_error(error: KvError) -> Self::Error {
        sinomo_cluster::kv_err(error)
    }

    fn replay_cluster_raft_request_if_committed(
        &mut self,
        request: &KvCommandRequest,
    ) -> Result<Option<(KvSnapshot, sinomo_kv::KvCommittedRequestRecord)>, NetworkError> {
        let paths = self.paths().clone();
        let local_node_id = self.local_node_id().clone();
        LocalClusterRaftCommandStorage::new(&paths, local_node_id)
            .replay_cluster_raft_request_if_committed(request)
    }

    fn append_cluster_raft_request_uncommitted(
        &mut self,
        request: KvCommandRequest,
    ) -> Result<sinomo_kv::KvLogEntry, NetworkError> {
        let paths = self.paths().clone();
        let local_node_id = self.local_node_id().clone();
        LocalClusterRaftCommandStorage::new(&paths, local_node_id)
            .append_cluster_raft_request_uncommitted(request)
    }

    fn record_cluster_raft_request_rejected_before_commit(
        &mut self,
        request: &KvCommandRequest,
        failure: &sinomo_kv::KvAuthorityFailure,
    ) -> Result<(), NetworkError> {
        let paths = self.paths().clone();
        let local_node_id = self.local_node_id().clone();
        LocalClusterRaftCommandStorage::new(&paths, local_node_id)
            .record_cluster_raft_request_rejected_before_commit(request, failure)
    }

    fn record_cluster_raft_request_unknown(
        &mut self,
        request: &KvCommandRequest,
        detail: &str,
    ) -> Result<(), NetworkError> {
        let paths = self.paths().clone();
        let local_node_id = self.local_node_id().clone();
        LocalClusterRaftCommandStorage::new(&paths, local_node_id)
            .record_cluster_raft_request_unknown(request, detail)
    }

    fn discard_cluster_raft_uncommitted_tail_and_clear_leader(
        &mut self,
    ) -> Result<(), NetworkError> {
        self.discarded = true;
        let paths = self.paths().clone();
        let local_node_id = self.local_node_id().clone();
        LocalClusterRaftCommandStorage::new(&paths, local_node_id)
            .discard_cluster_raft_uncommitted_tail_and_clear_leader()
    }

    fn commit_cluster_raft_index_with_events(
        &mut self,
        index: u64,
    ) -> Result<sinomo_kv::ClusterKvRaftCommitResult, NetworkError> {
        self.committed_indices.push(index);
        let paths = self.paths().clone();
        let local_node_id = self.local_node_id().clone();
        LocalClusterRaftCommandStorage::new(&paths, local_node_id)
            .commit_cluster_raft_index_with_events(index)
    }
}

impl ClusterRaftQuorumTransportHost for RecordingQuorumCommitHost {
    fn replicate_cluster_raft_to_node(
        &mut self,
        _paths: &ClusterPaths,
        state: &ClusterBootstrapState,
        target_node_id: &NodeId,
        _timeout: Duration,
    ) -> Result<ClusterRaftAppendResponse, NetworkError> {
        self.replicated_nodes.push(target_node_id.clone());
        if self.failing_nodes.contains(target_node_id) {
            return Err(NetworkError::Io {
                operation: "cluster raft append".to_string(),
                detail: format!("scripted failure for {target_node_id}"),
            });
        }
        Ok(ClusterRaftAppendResponse {
            accepted: true,
            detail: "accepted".to_string(),
            state: state.clone(),
            append: sinomo_kv::RaftAppendEntriesResponse {
                term: 1,
                success: true,
                match_index: 1,
            },
        })
    }

    fn record_node_command_connectivity(
        &mut self,
        _paths: &ClusterPaths,
        _state: &ClusterBootstrapState,
        target_node_id: &NodeId,
        connectivity_state: ClusterConnectivityState,
        latency_ms: Option<u64>,
    ) {
        self.connectivity.push((
            target_node_id.clone(),
            connectivity_state,
            latency_ms.is_some(),
        ));
    }

    fn fan_out_committed_cluster_raft_command(
        &mut self,
        _paths: ClusterPaths,
        _state: ClusterBootstrapState,
        events: std::sync::Arc<Vec<KvEvent>>,
        targets: Vec<NodeId>,
    ) {
        self.fanout_events = events.len();
        self.fanout_targets = targets;
    }
}

#[derive(Default)]
struct RecordingCommittedFanoutHost {
    appended_nodes: Vec<NodeId>,
    appended_event_counts: Vec<usize>,
    append_timeouts: Vec<Duration>,
    watch_batches: Vec<RecordedWatchBatch>,
}

struct RecordedWatchBatch {
    node_id: NodeId,
    leader_id: NodeId,
    revisions: Vec<KvRevision>,
    timeout: Duration,
}

impl ClusterRaftCommittedFanoutAsyncHost for RecordingCommittedFanoutHost {
    fn replicate_cluster_raft_to_node_async<'a>(
        &'a mut self,
        _paths: &'a ClusterPaths,
        state: &'a ClusterBootstrapState,
        target_node_id: &'a NodeId,
        watch_events: &'a [KvEvent],
        timeout: Duration,
    ) -> ClusterMembershipRpcFuture<'a, ClusterKvRaftAppendReplicationOutcome> {
        self.appended_nodes.push(target_node_id.clone());
        self.appended_event_counts.push(watch_events.len());
        self.append_timeouts.push(timeout);
        let state = state.clone();
        Box::pin(async move {
            Ok(ClusterKvRaftAppendReplicationOutcome {
                response: ClusterRaftAppendResponse {
                    accepted: true,
                    detail: "accepted".to_string(),
                    state,
                    append: sinomo_kv::RaftAppendEntriesResponse {
                        term: 1,
                        success: true,
                        match_index: 1,
                    },
                },
                watch_event_fanout_needed: true,
            })
        })
    }

    fn send_cluster_kv_watch_events_to_node_async<'a>(
        &'a mut self,
        _state: &'a ClusterBootstrapState,
        target_node_id: &'a NodeId,
        request: &'a ClusterKvWatchEventsRequest,
        timeout: Duration,
    ) -> ClusterMembershipRpcFuture<'a, ClusterKvWatchEventsResponse> {
        self.watch_batches.push(RecordedWatchBatch {
            node_id: target_node_id.clone(),
            leader_id: request.leader_id.clone(),
            revisions: request.events.iter().map(|event| event.revision).collect(),
            timeout,
        });
        let stored_events = request.events.len();
        Box::pin(async move {
            Ok(ClusterKvWatchEventsResponse {
                accepted: true,
                detail: "accepted".to_string(),
                stored_events,
            })
        })
    }
}

#[derive(Default)]
struct RecordingStateAuthorityReachabilityHost {
    reachable: BTreeSet<NodeId>,
    probes: Vec<(NodeId, Duration)>,
}

impl ClusterStateAuthorityReachabilityHost for RecordingStateAuthorityReachabilityHost {
    fn probe_cluster_state_authority_node(
        &mut self,
        _state: &ClusterBootstrapState,
        target_node_id: &NodeId,
        timeout: Duration,
    ) -> bool {
        self.probes.push((target_node_id.clone(), timeout));
        self.reachable.contains(target_node_id)
    }
}

impl ClusterStateAuthorityReachabilityAsyncHost for RecordingStateAuthorityReachabilityHost {
    fn probe_cluster_state_authority_node_async<'a>(
        &'a mut self,
        _state: &'a ClusterBootstrapState,
        target_node_id: &'a NodeId,
        timeout: Duration,
    ) -> ClusterMembershipRpcFuture<'a, bool> {
        Box::pin(async move {
            self.probes.push((target_node_id.clone(), timeout));
            Ok(self.reachable.contains(target_node_id))
        })
    }
}

#[derive(Default)]
struct RecordingLeaderElectionHost {
    sent_votes: Vec<(NodeId, u64, Duration)>,
}

impl ClusterRaftVoteTransportHost for RecordingLeaderElectionHost {
    fn send_raft_vote(
        &mut self,
        _state: &ClusterBootstrapState,
        target_node_id: &NodeId,
        request: &ClusterRaftVoteRequest,
        timeout: Duration,
    ) -> Result<ClusterRaftVoteResponse, NetworkError> {
        self.sent_votes
            .push((target_node_id.clone(), request.vote.term, timeout));
        Ok(ClusterRaftVoteResponse {
            accepted: true,
            detail: "granted".to_string(),
            state: request.state.clone(),
            vote: sinomo_kv::RaftRequestVoteResponse {
                term: request.vote.term,
                vote_granted: true,
            },
        })
    }

    fn send_raft_votes(
        &mut self,
        state: &ClusterBootstrapState,
        targets: Vec<NodeId>,
        request: &ClusterRaftVoteRequest,
        timeout: Duration,
        required_grants: usize,
    ) -> Result<Vec<(NodeId, Result<ClusterRaftVoteResponse, NetworkError>)>, NetworkError> {
        Ok(targets
            .into_iter()
            .take(required_grants)
            .map(|target| {
                let response = self.send_raft_vote(state, &target, request, timeout);
                (target, response)
            })
            .collect())
    }
}

struct BlockingLeaderElectionHost {
    vote_calls: Arc<AtomicUsize>,
    started: Option<std::sync::mpsc::Sender<()>>,
    release: Option<std::sync::mpsc::Receiver<()>>,
}

impl ClusterRaftVoteTransportHost for BlockingLeaderElectionHost {
    fn send_raft_vote(
        &mut self,
        _state: &ClusterBootstrapState,
        _target_node_id: &NodeId,
        request: &ClusterRaftVoteRequest,
        _timeout: Duration,
    ) -> Result<ClusterRaftVoteResponse, NetworkError> {
        self.vote_calls.fetch_add(1, Ordering::SeqCst);
        if let Some(started) = self.started.take() {
            started.send(()).expect("report campaign start");
        }
        if let Some(release) = self.release.take() {
            release.recv().expect("release blocked campaign");
        }
        Ok(ClusterRaftVoteResponse {
            accepted: true,
            detail: "granted".to_string(),
            state: request.state.clone(),
            vote: sinomo_kv::RaftRequestVoteResponse {
                term: request.vote.term,
                vote_granted: true,
            },
        })
    }

    fn send_raft_votes(
        &mut self,
        state: &ClusterBootstrapState,
        targets: Vec<NodeId>,
        request: &ClusterRaftVoteRequest,
        timeout: Duration,
        required_grants: usize,
    ) -> Result<Vec<(NodeId, Result<ClusterRaftVoteResponse, NetworkError>)>, NetworkError> {
        Ok(targets
            .into_iter()
            .take(required_grants)
            .map(|target| {
                let response = self.send_raft_vote(state, &target, request, timeout);
                (target, response)
            })
            .collect())
    }
}

#[derive(Default)]
struct NodeSensitiveLeaderElectionHost {
    failing_nodes: BTreeSet<NodeId>,
    sent_votes: Vec<(NodeId, u64, Duration)>,
}

impl ClusterRaftVoteTransportHost for NodeSensitiveLeaderElectionHost {
    fn send_raft_vote(
        &mut self,
        _state: &ClusterBootstrapState,
        target_node_id: &NodeId,
        request: &ClusterRaftVoteRequest,
        timeout: Duration,
    ) -> Result<ClusterRaftVoteResponse, NetworkError> {
        self.sent_votes
            .push((target_node_id.clone(), request.vote.term, timeout));
        if self.failing_nodes.contains(target_node_id) {
            return Err(NetworkError::Io {
                operation: "cluster raft vote".to_string(),
                detail: format!("scripted failure for {target_node_id}"),
            });
        }
        Ok(ClusterRaftVoteResponse {
            accepted: true,
            detail: "granted".to_string(),
            state: request.state.clone(),
            vote: sinomo_kv::RaftRequestVoteResponse {
                term: request.vote.term,
                vote_granted: true,
            },
        })
    }

    fn send_raft_votes(
        &mut self,
        state: &ClusterBootstrapState,
        targets: Vec<NodeId>,
        request: &ClusterRaftVoteRequest,
        timeout: Duration,
        required_grants: usize,
    ) -> Result<Vec<(NodeId, Result<ClusterRaftVoteResponse, NetworkError>)>, NetworkError> {
        Ok(targets
            .into_iter()
            .map(|target| {
                let response = self.send_raft_vote(state, &target, request, timeout);
                (target, response)
            })
            .take(required_grants)
            .collect())
    }
}

struct RecordingKvTxnForwardHost {
    known_authority: Option<NodeId>,
    snapshot: KvSnapshot,
    txn_response: KvTxnResponse,
    rpcs: Vec<(NodeId, String)>,
}

impl ClusterKvTxnForwardHost for RecordingKvTxnForwardHost {
    fn known_kv_state_authority_id(
        &mut self,
        _paths: &ClusterPaths,
        _state: &ClusterBootstrapState,
    ) -> Result<Option<NodeId>, NetworkError> {
        Ok(self.known_authority.clone())
    }

    fn call_node_object_rpc(
        &mut self,
        state: &ClusterBootstrapState,
        target_node_id: &NodeId,
        request: &ObjectRpcRequest,
        _timeout: Duration,
    ) -> Result<ObjectRpcResponse, NetworkError> {
        self.rpcs
            .push((target_node_id.clone(), request.route.clone()));
        match request.route.as_str() {
            CLUSTER_KV_TXN_ROUTE => {
                let submitted = sinomo_kv::decode_cluster_kv_txn_rpc_request_body(&request.body)
                    .map_err(kv_err)?;
                let voter_count = state
                    .members
                    .iter()
                    .filter(|member| sinomo_kv::cluster_kv_member_has_raft_vote(member))
                    .count();
                let required_quorum = sinomo_kv::cluster_kv_raft_quorum_size(voter_count);
                let mut result = test_cluster_kv_txn_commit_result_for_request(
                    submitted.request_id,
                    self.snapshot.clone(),
                    Some(self.txn_response.clone()),
                );
                result.authority.term = result.authority.term.max(state.term);
                result.authority.basis = sinomo_kv::KvAuthorityBasis::CurrentTermQuorum {
                    voter_acks: required_quorum,
                    required_quorum,
                };
                let payload =
                    sinomo_kv::cluster_kv_txn_response_rpc_payload(&result).map_err(kv_err)?;
                Ok(object_rpc_response_from_kv_payload(payload))
            }
            sinomo_kv::CLUSTER_KV_AUTHORITATIVE_SNAPSHOT_ROUTE => {
                let voter_count = state
                    .members
                    .iter()
                    .filter(|member| sinomo_kv::cluster_kv_member_has_raft_vote(member))
                    .count();
                let required_quorum = sinomo_kv::cluster_kv_raft_quorum_size(voter_count);
                let mut authority = test_current_quorum_authority(&self.snapshot);
                authority.term = authority.term.max(state.term);
                authority.basis = sinomo_kv::KvAuthorityBasis::CurrentTermQuorum {
                    voter_acks: required_quorum,
                    required_quorum,
                };
                let response = sinomo_kv::KvAuthoritativeRead {
                    authority,
                    value: self.snapshot.clone(),
                };
                let payload =
                    sinomo_kv::cluster_kv_authoritative_snapshot_response_rpc_payload(&response)
                        .map_err(kv_err)?;
                Ok(object_rpc_response_from_kv_payload(payload))
            }
            route => ObjectRpcResponse::encode_error(route, "unexpected route"),
        }
    }
}

struct RecordingKvSnapshotRefreshHost {
    known_authority: Option<NodeId>,
    snapshots: BTreeMap<NodeId, KvSnapshot>,
    fetches: Vec<(NodeId, Duration)>,
    cache_change: Option<(NodeId, KvRevision)>,
}

impl ClusterKvSnapshotRefreshHost for RecordingKvSnapshotRefreshHost {
    fn known_kv_state_authority_id(
        &mut self,
        _paths: &ClusterPaths,
        _state: &ClusterBootstrapState,
    ) -> Result<Option<NodeId>, NetworkError> {
        Ok(self.known_authority.clone())
    }

    fn cache_cluster_kv_snapshot_if_newer_than_raft(
        &mut self,
        _paths: &ClusterPaths,
        local_node_id: &NodeId,
        snapshot: KvSnapshot,
    ) -> Result<bool, NetworkError> {
        self.cache_change = Some((local_node_id.clone(), snapshot.revision));
        Ok(true)
    }

    fn call_node_object_rpc(
        &mut self,
        _state: &ClusterBootstrapState,
        target_node_id: &NodeId,
        request: &ObjectRpcRequest,
        timeout: Duration,
    ) -> Result<ObjectRpcResponse, NetworkError> {
        self.fetches.push((target_node_id.clone(), timeout));
        assert_eq!(
            request.route,
            sinomo_kv::CLUSTER_KV_AUTHORITATIVE_SNAPSHOT_ROUTE
        );
        let snapshot =
            self.snapshots
                .get(target_node_id)
                .cloned()
                .ok_or_else(|| NetworkError::Io {
                    operation: "test snapshot refresh".to_string(),
                    detail: format!("no snapshot for {target_node_id}"),
                })?;
        let payload = sinomo_kv::cluster_kv_authoritative_snapshot_response_rpc_payload(
            &sinomo_kv::KvAuthoritativeRead {
                authority: test_current_quorum_authority(&snapshot),
                value: snapshot,
            },
        )
        .map_err(kv_err)?;
        Ok(object_rpc_response_from_kv_payload(payload))
    }
}

#[derive(Default)]
struct RecordingKvTxnQuorumHost {
    leader: bool,
    leader_checks: usize,
    elect_calls: usize,
    commit_calls: usize,
}

impl ClusterKvTxnQuorumHost for RecordingKvTxnQuorumHost {
    fn known_kv_state_authority_id(
        &mut self,
        _paths: &ClusterPaths,
        _state: &ClusterBootstrapState,
    ) -> Result<Option<NodeId>, NetworkError> {
        panic!("forwarded non-leader requests must not forward again")
    }

    fn call_node_object_rpc(
        &mut self,
        _state: &ClusterBootstrapState,
        _target_node_id: &NodeId,
        _request: &ObjectRpcRequest,
        _timeout: Duration,
    ) -> Result<ObjectRpcResponse, NetworkError> {
        panic!("forwarded non-leader requests must not forward again")
    }

    fn local_is_kv_state_authority(
        &mut self,
        _paths: &ClusterPaths,
        _state: &ClusterBootstrapState,
    ) -> Result<bool, NetworkError> {
        self.leader_checks += 1;
        Ok(self.leader)
    }

    fn request_kv_state_authority_vote(
        &mut self,
        _state: &ClusterBootstrapState,
        _target_node_id: &NodeId,
        _request: &sinomo_kv::ClusterKvStateAuthorityVoteRequest,
        _timeout: Duration,
    ) -> Result<sinomo_kv::ClusterKvStateAuthorityVoteResponse, NetworkError> {
        panic!("recording quorum host overrides election and must not send raft votes")
    }

    fn elect_kv_state_authority(
        &mut self,
        _paths: &ClusterPaths,
        _state: &ClusterBootstrapState,
        _options: ClusterKvTxnQuorumOptions,
    ) -> Result<bool, NetworkError> {
        self.elect_calls += 1;
        self.leader = true;
        Ok(true)
    }

    fn reachable_cluster_state_authority_count(
        &mut self,
        _paths: &ClusterPaths,
        _state: &ClusterBootstrapState,
        _options: ClusterStateAuthorityReachabilityOptions,
    ) -> usize {
        1
    }

    fn commit_cluster_kv_command_with_quorum(
        &mut self,
        _paths: &ClusterPaths,
        _state: &mut ClusterBootstrapState,
        request: KvCommandRequest,
        _options: ClusterKvRaftQuorumCommitOptions,
    ) -> Result<ClusterKvRaftQuorumCommitResult, NetworkError> {
        self.commit_calls += 1;
        let mut store = InProcessKvStore::new();
        let txn_response = match request.command {
            KvCommand::Txn(txn) => Some(store.txn(txn).expect("test txn commit")),
            KvCommand::Op(op) => Some(
                store
                    .txn(KvTxn {
                        compares: Vec::new(),
                        success: vec![op],
                        failure: Vec::new(),
                    })
                    .expect("test op commit"),
            ),
            KvCommand::Barrier => None,
        };
        let snapshot = store.snapshot().expect("test snapshot");
        Ok(ClusterKvRaftQuorumCommitResult {
            authority: test_current_quorum_authority(&snapshot),
            snapshot,
            txn_response,
            replayed_committed_request: false,
        })
    }
}

struct RetryableCommitFailureKvTxnQuorumHost {
    leader: bool,
    leader_checks: usize,
    elect_calls: usize,
    commit_calls: usize,
}

impl Default for RetryableCommitFailureKvTxnQuorumHost {
    fn default() -> Self {
        Self {
            leader: true,
            leader_checks: 0,
            elect_calls: 0,
            commit_calls: 0,
        }
    }
}

impl ClusterKvTxnQuorumHost for RetryableCommitFailureKvTxnQuorumHost {
    fn known_kv_state_authority_id(
        &mut self,
        _paths: &ClusterPaths,
        _state: &ClusterBootstrapState,
    ) -> Result<Option<NodeId>, NetworkError> {
        Ok(None)
    }

    fn call_node_object_rpc(
        &mut self,
        _state: &ClusterBootstrapState,
        _target_node_id: &NodeId,
        _request: &ObjectRpcRequest,
        _timeout: Duration,
    ) -> Result<ObjectRpcResponse, NetworkError> {
        panic!("retry test overrides forwarding and must not send object RPCs")
    }

    fn local_is_kv_state_authority(
        &mut self,
        _paths: &ClusterPaths,
        _state: &ClusterBootstrapState,
    ) -> Result<bool, NetworkError> {
        self.leader_checks += 1;
        Ok(self.leader)
    }

    fn request_kv_state_authority_vote(
        &mut self,
        _state: &ClusterBootstrapState,
        _target_node_id: &NodeId,
        _request: &sinomo_kv::ClusterKvStateAuthorityVoteRequest,
        _timeout: Duration,
    ) -> Result<sinomo_kv::ClusterKvStateAuthorityVoteResponse, NetworkError> {
        panic!("retry test overrides election and must not send raft votes")
    }

    fn forward_cluster_kv_txn_to_state_authority(
        &mut self,
        _paths: &ClusterPaths,
        _state: &ClusterBootstrapState,
        _request: &KvTxnRequest,
        _options: ClusterKvTxnQuorumOptions,
    ) -> Result<Option<ClusterKvTxnCommitResult>, NetworkError> {
        Ok(None)
    }

    fn elect_kv_state_authority(
        &mut self,
        _paths: &ClusterPaths,
        _state: &ClusterBootstrapState,
        _options: ClusterKvTxnQuorumOptions,
    ) -> Result<bool, NetworkError> {
        self.elect_calls += 1;
        self.leader = true;
        Ok(true)
    }

    fn reachable_cluster_state_authority_count(
        &mut self,
        _paths: &ClusterPaths,
        _state: &ClusterBootstrapState,
        _options: ClusterStateAuthorityReachabilityOptions,
    ) -> usize {
        2
    }

    fn commit_cluster_kv_command_with_quorum(
        &mut self,
        _paths: &ClusterPaths,
        _state: &mut ClusterBootstrapState,
        _request: KvCommandRequest,
        _options: ClusterKvRaftQuorumCommitOptions,
    ) -> Result<ClusterKvRaftQuorumCommitResult, NetworkError> {
        self.commit_calls += 1;
        if self.commit_calls == 1 {
            self.leader = false;
            return Err(NetworkError::ClusterReadOnly {
                detail: "raft append rejected by local log with higher term".to_string(),
            });
        }
        let snapshot = forward_test_snapshot("/test/retry-after-commit-failure", b"committed");
        Ok(ClusterKvRaftQuorumCommitResult {
            txn_response: Some(forward_test_txn_response(snapshot.revision)),
            authority: test_current_quorum_authority(&snapshot),
            snapshot,
            replayed_committed_request: false,
        })
    }
}

fn forward_test_snapshot(key: &str, value: &[u8]) -> KvSnapshot {
    let mut store = InProcessKvStore::new();
    store.put(key, value.to_vec(), None).expect("seed snapshot");
    store.snapshot().expect("snapshot")
}

fn forward_test_txn_response(revision: KvRevision) -> KvTxnResponse {
    KvTxnResponse {
        succeeded: true,
        revision,
        responses: Vec::new(),
    }
}

