#[test]
fn cluster_control_plane_driver_delegates_publish_cache_hooks_to_transport() {
    #[derive(Default)]
    struct RecordingPublishCacheTransport {
        network_match: bool,
        network_checks: usize,
        network_remembers: usize,
        node_match: bool,
        node_checks: usize,
        node_remembers: usize,
        connectivity_match: bool,
        connectivity_checks: usize,
        connectivity_remembers: usize,
    }

    impl ClusterControlPlaneTransport for RecordingPublishCacheTransport {
        fn send_kv_replication(
            &mut self,
            _endpoint: &ClusterEndpointRecord,
            _request: &sinomo_kv::ClusterKvReplicationRequest,
            _timeout: Duration,
        ) -> Result<sinomo_kv::ClusterKvReplicationResponse, NetworkError> {
            panic!("cache hook test should not send kv replication")
        }

        fn request_kv_state_authority_vote(
            &mut self,
            _endpoint: &ClusterEndpointRecord,
            _request: &sinomo_kv::ClusterKvStateAuthorityVoteRequest,
            _timeout: Duration,
        ) -> Result<sinomo_kv::ClusterKvStateAuthorityVoteResponse, NetworkError> {
            panic!("cache hook test should not send kv state authority vote")
        }

        fn probe_cluster_state_authority(
            &mut self,
            _endpoint: &ClusterEndpointRecord,
            _timeout: Duration,
        ) -> bool {
            panic!("cache hook test should not probe voters")
        }

        fn fetch_cluster_kv_snapshot(
            &mut self,
            _endpoint: &ClusterEndpointRecord,
            _timeout: Duration,
        ) -> Result<KvSnapshot, NetworkError> {
            panic!("cache hook test should not fetch kv snapshots")
        }

        fn call_endpoint_object_rpc(
            &mut self,
            _endpoint: &ClusterEndpointRecord,
            _request: &ObjectRpcRequest,
            _timeout: Duration,
        ) -> Result<ObjectRpcResponse, NetworkError> {
            panic!("cache hook test should not send membership rpc")
        }

        fn call_node_object_rpc(
            &mut self,
            _state: &ClusterBootstrapState,
            _target_node_id: &NodeId,
            _request: &ObjectRpcRequest,
            _timeout: Duration,
        ) -> Result<ObjectRpcResponse, NetworkError> {
            panic!("cache hook test should not send node rpc")
        }

        fn published_network_info_matches(
            &mut self,
            _paths: &ClusterPaths,
            _info: &ClusterNetworkInfoRecord,
        ) -> bool {
            self.network_checks += 1;
            self.network_match
        }

        fn remember_published_network_info(
            &mut self,
            _paths: &ClusterPaths,
            _info: &ClusterNetworkInfoRecord,
        ) {
            self.network_remembers += 1;
        }

        fn published_node_status_matches(
            &mut self,
            _paths: &ClusterPaths,
            _status: &ClusterNodeStatusRecord,
        ) -> bool {
            self.node_checks += 1;
            self.node_match
        }

        fn remember_published_node_status(
            &mut self,
            _paths: &ClusterPaths,
            _status: &ClusterNodeStatusRecord,
        ) {
            self.node_remembers += 1;
        }

        fn published_connectivity_record_set_matches(
            &mut self,
            _paths: &ClusterPaths,
            _source_node_id: &NodeId,
            _records: &[ClusterConnectivityRecord],
        ) -> bool {
            self.connectivity_checks += 1;
            self.connectivity_match
        }

        fn remember_published_connectivity_record_set(
            &mut self,
            _paths: &ClusterPaths,
            _source_node_id: &NodeId,
            _records: &[ClusterConnectivityRecord],
        ) {
            self.connectivity_remembers += 1;
        }
    }

    let now = OffsetDateTime::now_utc();
    let cluster_id =
        ClusterId::from_legacy_named("cluster_driver_publish_cache_hooks").expect("cluster");
    let node_id = NodeId::from_legacy_named("node_driver_publish_cache_hooks").expect("node");
    let target_node =
        NodeId::from_legacy_named("node_driver_publish_cache_hooks_target").expect("target");
    let root = sinomo_testdir::TestDir::new("sinomo-network-driver-publish-cache-hooks");
    let data_dir = SinomoDataDir::new(&root);
    let paths = ClusterPaths::new(&data_dir);
    let info = ClusterNetworkInfoRecord {
        cluster_id: cluster_id.clone(),
        node_id: node_id.clone(),
        environment_id: "env_driver_publish_cache_hooks".to_string(),
        observed_addresses: vec!["192.0.2.44".to_string()],
        endpoints: Vec::new(),
        observed_at: now,
        expires_at: now + time::Duration::seconds(600),
    };
    let status = ClusterNodeStatusRecord {
        cluster_id: cluster_id.clone(),
        node_id: node_id.clone(),
        process: sinomo_node::DAEMON_MAIN_CLUSTER_ROLE.to_string(),
        availability: ClusterNodeAvailability::Online,
        daemon_version: "0.1.0-test".to_string(),
        commit: None,
        target_os: Some("test-os".to_string()),
        target_arch: Some("test-arch".to_string()),
        hostname: None,
        pid: Some(42),
        address: Some("127.0.0.1:21353".to_string()),
        bind_address: None,
        executable: Some("sinomo".to_string()),
        rollout: None,
        daemon_started_at: Some("2026-06-08T00:00:00Z".to_string()),
        observed_at: now,
    };
    let connectivity = vec![ClusterConnectivityRecord {
        cluster_id,
        source_node_id: node_id.clone(),
        target_node_id: target_node,
        endpoint_id: ClusterEndpointId::from_legacy_named("endpoint_driver_publish_cache_hooks")
            .expect("endpoint"),
        transport: ClusterTransportKind::LanTcp,
        address: "192.0.2.45:21353".to_string(),
        state: ClusterConnectivityState::Healthy,
        latency_ms: Some(7),
        consecutive_failures: 0,
        last_success_at: Some("ok".to_string()),
        last_failure_at: None,
        failure_reason: None,
        observed_at: now,
        expires_at: now + time::Duration::seconds(600),
    }];
    let mut driver = ClusterControlPlaneDriver::new(RecordingPublishCacheTransport {
        network_match: true,
        node_match: true,
        connectivity_match: true,
        ..Default::default()
    });

    assert!(
        ClusterNetworkInfoPublishHost::published_network_info_matches(&mut driver, &paths, &info)
    );
    ClusterNetworkInfoPublishHost::remember_published_network_info(&mut driver, &paths, &info);
    assert!(ClusterNodeStatusPublishHost::published_node_status_matches(
        &mut driver,
        &paths,
        &status
    ));
    ClusterNodeStatusPublishHost::remember_published_node_status(&mut driver, &paths, &status);
    assert!(
        ClusterConnectivityPublishHost::published_connectivity_record_set_matches(
            &mut driver,
            &paths,
            &node_id,
            &connectivity
        )
    );
    ClusterConnectivityPublishHost::remember_published_connectivity_record_set(
        &mut driver,
        &paths,
        &node_id,
        &connectivity,
    );

    let transport = driver.into_transport();
    assert_eq!(transport.network_checks, 1);
    assert_eq!(transport.network_remembers, 1);
    assert_eq!(transport.node_checks, 1);
    assert_eq!(transport.node_remembers, 1);
    assert_eq!(transport.connectivity_checks, 1);
    assert_eq!(transport.connectivity_remembers, 1);
}

#[test]
fn cluster_kv_snapshot_refresh_driver_prefers_known_state_authority_and_imports_newest_snapshot() {
    let root = sinomo_testdir::TestDir::new("sinomo-network-kv-refresh-driver");
    let data_dir = SinomoDataDir::new(&root);
    let paths = ClusterPaths::new(&data_dir);
    paths.ensure().expect("cluster paths");
    let (mut state, local_node_id, first_peer_id) = cluster_raft_handler_test_state(
        "cluster_kv_snapshot_refresh_driver",
        "node_kv_refresh_local",
        "node_kv_refresh_first_peer",
    );
    state
        .members
        .iter_mut()
        .find(|member| member.node_id == first_peer_id)
        .expect("first peer")
        .endpoints
        .push(daemon_lan_endpoint(
            &first_peer_id,
            "10.0.0.91:21353".to_string(),
            20,
        ));
    let now = OffsetDateTime::now_utc();
    let authority_id =
        NodeId::from_legacy_named("node_kv_refresh_known_authority").expect("authority");
    let mut authority_member = state.members[0].clone();
    authority_member.node_id = authority_id.clone();
    authority_member.display_name = "authority".to_string();
    authority_member.node_public_key = "authority-public-key".to_string();
    authority_member.endpoints = vec![daemon_lan_endpoint(
        &authority_id,
        "10.0.0.90:21353".to_string(),
        10,
    )];
    authority_member.joined_at = now;
    authority_member.updated_at = now;
    mark_test_member_as_voter(&mut authority_member);
    state.members.push(authority_member);
    write_cluster_state(&paths, &state).expect("write state");
    let local_snapshot =
        sync_cluster_state_to_local_raft_unchecked(&paths, &state).expect("seed local snapshot");

    let mut first_store = InProcessKvStore::restore(local_snapshot.clone()).expect("restore");
    first_store
        .put("/refresh/first-peer", b"first".to_vec(), None)
        .expect("first peer snapshot put");
    let first_snapshot = first_store.snapshot().expect("snapshot");
    let mut authority_store = InProcessKvStore::restore(local_snapshot).expect("restore");
    authority_store
        .put("/refresh/authority/one", b"authority-one".to_vec(), None)
        .expect("authority snapshot put one");
    authority_store
        .put("/refresh/authority/two", b"authority-two".to_vec(), None)
        .expect("authority snapshot put two");
    let authority_snapshot = authority_store.snapshot().expect("snapshot");

    let mut host = RecordingKvSnapshotRefreshHost {
        known_authority: Some(authority_id.clone()),
        snapshots: BTreeMap::from([
            (first_peer_id.clone(), first_snapshot),
            (authority_id.clone(), authority_snapshot.clone()),
        ]),
        fetches: Vec::new(),
        cache_change: None,
    };

    let refreshed = refresh_current_cluster_kv_store_with_host(
        &paths,
        &state,
        kv_snapshot_refresh_test_options(),
        &mut host,
    )
    .expect("refresh snapshot");

    assert_eq!(
        host.fetches.first().map(|(node_id, _)| node_id),
        Some(&authority_id),
        "snapshot refresh should try the known state authority before other state authorities"
    );
    assert_eq!(
        host.cache_change,
        Some((local_node_id, authority_snapshot.revision)),
        "snapshot refresh should ask the host to cache the newest imported read model"
    );
    assert!(
        refreshed.get("/refresh/authority/two").is_some(),
        "the returned store should be restored from the newest fetched snapshot"
    );
    assert_eq!(
        read_cluster_kv_snapshot(&paths)
            .expect("materialized imported snapshot")
            .revision,
        authority_snapshot.revision
    );
}

#[test]
fn cluster_kv_snapshot_refresh_local_driver_owns_local_raft_storage() {
    let root = sinomo_testdir::TestDir::new("sinomo-network-kv-refresh-local-driver");
    let data_dir = SinomoDataDir::new(&root);
    let paths = ClusterPaths::new(&data_dir);
    paths.ensure().expect("cluster paths");
    let (mut state, _local_node_id, first_peer_id) = cluster_raft_handler_test_state(
        "cluster_kv_snapshot_refresh_local_driver",
        "node_kv_refresh_local_driver_local",
        "node_kv_refresh_local_driver_peer",
    );
    state
        .members
        .iter_mut()
        .find(|member| member.node_id == first_peer_id)
        .expect("first peer")
        .endpoints
        .push(daemon_lan_endpoint(
            &first_peer_id,
            "10.0.0.92:21353".to_string(),
            20,
        ));
    write_cluster_state(&paths, &state).expect("write state");
    let local_snapshot =
        sync_cluster_state_to_local_raft_unchecked(&paths, &state).expect("seed local snapshot");
    let mut remote_store = InProcessKvStore::restore(local_snapshot).expect("restore");
    remote_store
        .put("/refresh/local-driver", b"local-driver".to_vec(), None)
        .expect("remote snapshot put");
    let remote_snapshot = remote_store.snapshot().expect("snapshot");
    let mut fetches = Vec::new();

    let refreshed = refresh_current_cluster_kv_store_with_local_storage_and_transport(
        &paths,
        &state,
        kv_snapshot_refresh_test_options(),
        |target_node_id, timeout| {
            fetches.push((target_node_id.clone(), timeout));
            Ok(sinomo_kv::KvAuthoritativeRead {
                value: remote_snapshot.clone(),
                authority: sinomo_kv::KvAuthorityProof {
                    term: 1,
                    commit_index: 1,
                    revision: remote_snapshot.revision,
                    basis: sinomo_kv::KvAuthorityBasis::CurrentTermQuorum {
                        voter_acks: 1,
                        required_quorum: 1,
                    },
                },
            })
        },
    )
    .expect("refresh snapshot through local driver");

    assert_eq!(
        fetches.first().map(|(node_id, _)| node_id),
        Some(&first_peer_id)
    );
    assert!(
        refreshed.get("/refresh/local-driver").is_some(),
        "the local driver should return the newest fetched snapshot"
    );
    assert_eq!(
        read_cluster_kv_snapshot(&paths)
            .expect("materialized imported snapshot")
            .revision,
        remote_snapshot.revision
    );
}

#[test]
fn forwarded_cluster_kv_txn_driver_never_starts_election() {
    let root = sinomo_testdir::TestDir::new("sinomo-network-forwarded-kv-local-election");
    let data_dir = SinomoDataDir::new(&root);
    let paths = ClusterPaths::new(&data_dir);
    paths.ensure().expect("cluster paths");
    let now = OffsetDateTime::now_utc();
    let cluster_id = ClusterId::from_legacy_named("cluster_network_forwarded_kv_local_election")
        .expect("cluster");
    let local =
        NodeId::from_legacy_named("node_network_forwarded_kv_local_election").expect("local node");
    let mut state = ClusterBootstrapState::initialized_locally(
        cluster_id,
        "forwarded kv local election",
        local,
        "local",
        "pk-local",
        now,
    );
    mark_test_member_as_voter(&mut state.members[0]);
    let mut host = RecordingKvTxnQuorumHost::default();

    let error = commit_cluster_kv_txn_with_quorum_response_with_host(
        &paths,
        &mut state,
        KvTxnRequest::generated(KvTxn {
            compares: Vec::new(),
            success: vec![KvOp::Put {
                key: "/test/forwarded-local-election".to_string(),
                value: b"committed".to_vec(),
                lease_id: None,
            }],
            failure: Vec::new(),
        }),
        kv_txn_quorum_test_options(false),
        &mut host,
    )
    .expect_err("forwarded non-leader voter must not campaign");

    assert!(matches!(
        error,
        NetworkError::ClusterReadOnly { detail }
            if detail.contains("forwarded cluster KV transaction reached a non-leader voter")
    ));
    assert_eq!(host.leader_checks, 1);
    assert_eq!(host.elect_calls, 0);
    assert_eq!(host.commit_calls, 0);
}

