#[test]
fn cluster_raft_quorum_commit_succeeds_with_two_of_three_voters_online() {
    let root = sinomo_testdir::TestDir::new("sinomo-network-raft-quorum-two-of-three");
    let data_dir = SinomoDataDir::new(&root);
    let paths = ClusterPaths::new(&data_dir);
    paths.ensure().expect("cluster paths");
    let (mut state, local_node_id, peer_node_id) = cluster_raft_handler_test_state(
        "cluster_raft_quorum_two_of_three",
        "node_raft_quorum_two_of_three_local",
        "node_raft_quorum_two_of_three_peer",
    );
    let offline_node_id =
        NodeId::from_legacy_named("node_raft_quorum_two_of_three_offline").expect("offline");
    let cluster_id = state.cluster_id.clone();
    let now = OffsetDateTime::now_utc();
    let mut offline = ClusterMemberRecord::local_voter(
        cluster_id,
        offline_node_id.clone(),
        "offline",
        "pk-offline",
        now,
    );
    offline.capabilities = main_daemon_capabilities(&ClusterMemberRole::Voter);
    offline.allowed_capabilities = offline.capabilities.clone();
    offline.endpoints = vec![daemon_lan_endpoint(
        &offline_node_id,
        "192.0.2.94:21353".to_string(),
        20,
    )];
    state.members.push(offline);
    state
        .members
        .iter_mut()
        .find(|member| member.node_id == peer_node_id)
        .expect("peer member")
        .endpoints
        .push(daemon_lan_endpoint(
            &peer_node_id,
            "192.0.2.93:21353".to_string(),
            10,
        ));
    write_cluster_state(&paths, &state).expect("write state");
    sync_cluster_state_to_local_raft_unchecked(&paths, &state).expect("seed committed raft config");
    let mut host = RecordingQuorumCommitHost::new(paths.clone(), local_node_id);
    host.failing_nodes.insert(offline_node_id.clone());

    let result = commit_cluster_raft_command_with_quorum_driver(
        &paths,
        &mut state,
        KvCommandRequest::generated(KvCommand::Op(KvOp::Put {
            key: "/quorum/two-of-three".to_string(),
            value: b"committed".to_vec(),
            lease_id: None,
        })),
        ClusterKvRaftQuorumCommitOptions {
            timeout: Duration::from_secs(5),
        },
        &mut host,
    )
    .expect("two online voters should satisfy a three-voter quorum");

    assert_eq!(
        result
            .snapshot
            .get("/quorum/two-of-three")
            .expect("committed entry")
            .value,
        b"committed".to_vec()
    );
    assert!(host.replicated_nodes.contains(&peer_node_id));
    assert!(!host.discarded);
    assert_eq!(
        host.committed_indices,
        vec![2],
        "the fixture config occupies committed index 1"
    );
}

#[test]
fn intermittent_three_node_cluster_preserves_local_reads_and_converges_after_quorum_returns() {
    let leader_root = sinomo_testdir::TestDir::new("cluster-intermittent-leader");
    let peer_one_root = sinomo_testdir::TestDir::new("cluster-intermittent-peer-one");
    let peer_two_root = sinomo_testdir::TestDir::new("cluster-intermittent-peer-two");
    let leader_paths = ClusterPaths::new(&SinomoDataDir::new(&leader_root));
    let peer_one_paths = ClusterPaths::new(&SinomoDataDir::new(&peer_one_root));
    let peer_two_paths = ClusterPaths::new(&SinomoDataDir::new(&peer_two_root));
    for paths in [&leader_paths, &peer_one_paths, &peer_two_paths] {
        paths.ensure().expect("cluster paths");
    }

    let (mut state, leader_id, peer_one_id) = cluster_raft_handler_test_state(
        "cluster_intermittent_three_node",
        "node_intermittent_leader",
        "node_intermittent_peer_one",
    );
    let peer_two_id = NodeId::from_legacy_named("node_intermittent_peer_two").expect("peer two id");
    let mut peer_two = state.members[1].clone();
    peer_two.node_id = peer_two_id.clone();
    peer_two.display_name = "peer two".to_string();
    peer_two.node_public_key = "peer-two-public-key".to_string();
    peer_two.endpoints.clear();
    mark_test_member_as_voter(&mut peer_two);
    state.members.push(peer_two);
    state.members[1].endpoints = vec![daemon_lan_endpoint(
        &peer_one_id,
        "10.91.0.2:21353".to_string(),
        10,
    )];
    state.members[2].endpoints = vec![daemon_lan_endpoint(
        &peer_two_id,
        "10.91.0.3:21353".to_string(),
        10,
    )];
    write_cluster_state(&leader_paths, &state).expect("leader state");
    for (paths, node_id) in [
        (&peer_one_paths, &peer_one_id),
        (&peer_two_paths, &peer_two_id),
    ] {
        let mut peer_state = state.clone();
        peer_state.local_node_id = node_id.clone();
        peer_state.local_node_display_name = peer_state
            .members
            .iter()
            .find(|member| &member.node_id == node_id)
            .expect("peer member")
            .display_name
            .clone();
        write_cluster_state(paths, &peer_state).expect("peer state");
    }

    let seeded = append_cluster_raft_command(
        &leader_paths,
        &leader_id,
        KvCommand::Op(KvOp::Put {
            key: "/intermittent/already-committed".to_string(),
            value: b"available-offline".to_vec(),
            lease_id: None,
        }),
    )
    .expect("seed committed local history");
    locked_set_cluster_raft_leader(&leader_paths, &leader_id, 1)
        .expect("establish initial leader term");
    let local_read = read_cluster_kv_local_snapshot(&leader_paths, &state)
        .expect("local read remains available without quorum");
    assert_eq!(local_read.revision, seeded.revision);
    assert!(
        local_read
            .value
            .get("/intermittent/already-committed")
            .is_some()
    );
    let mut offline_peer_two_state = state.clone();
    offline_peer_two_state.local_node_id = peer_two_id.clone();
    assert!(
        read_cluster_kv_local_snapshot(&peer_two_paths, &offline_peer_two_state).is_ok(),
        "an offline follower must still serve its local (possibly stale) view"
    );

    let unavailable = commit_cluster_raft_command_with_local_storage_and_transport(
        &leader_paths,
        &mut state,
        KvCommandRequest::generated(KvCommand::Op(KvOp::Put {
            key: "/intermittent/must-not-commit".to_string(),
            value: b"no-quorum".to_vec(),
            lease_id: None,
        })),
        ClusterKvRaftQuorumCommitOptions {
            timeout: Duration::from_millis(100),
        },
        ClusterControlPlaneTimeouts::default_daemon_transport(),
        |_endpoint, _request, _timeout| {
            Err(NetworkError::delivery_failed(
                "intermittent peer append",
                NetworkDeliveryState::DefinitelyNotSent,
                "both peers are offline",
            ))
        },
        |_, _, _, _, _| {},
        |_, _, _, _| {},
        || {},
    )
    .expect_err("an authoritative write must fail while two of three voters are offline");
    assert!(matches!(unavailable, NetworkError::ClusterReadOnly { .. }));
    assert!(
        read_cluster_kv_local_snapshot(&leader_paths, &state)
            .expect("local view after failed write")
            .value
            .get("/intermittent/must-not-commit")
            .is_none()
    );

    let authenticated_leader = ClusterAuthenticatedPeer {
        node_id: leader_id.to_string(),
        public_key: "local-public-key".to_string(),
    };
    locked_set_cluster_raft_leader(&leader_paths, &leader_id, 2)
        .expect("restore leadership after the failed no-quorum attempt");
    let peer_one_for_commit = peer_one_id.clone();
    let committed = commit_cluster_raft_command_with_local_storage_and_transport(
        &leader_paths,
        &mut state,
        KvCommandRequest::generated(KvCommand::Op(KvOp::Put {
            key: "/intermittent/converged".to_string(),
            value: b"quorum-restored".to_vec(),
            lease_id: None,
        })),
        ClusterKvRaftQuorumCommitOptions {
            timeout: Duration::from_secs(2),
        },
        ClusterControlPlaneTimeouts::default_daemon_transport(),
        |endpoint, request, _timeout| {
            if endpoint.node_id != peer_one_for_commit {
                return Err(NetworkError::delivery_failed(
                    "intermittent peer append",
                    NetworkDeliveryState::DefinitelyNotSent,
                    "peer two remains offline",
                ));
            }
            handle_cluster_raft_append_request(
                &peer_one_paths,
                request.clone(),
                &authenticated_leader,
            )
        },
        |_, _, _, _, _| {},
        |_, _, _, _| {},
        || {},
    )
    .expect("one restored peer establishes a two-of-three quorum");
    assert!(committed.snapshot.get("/intermittent/converged").is_some());
    assert!(matches!(
        committed.authority.basis,
        sinomo_kv::KvAuthorityBasis::CurrentTermQuorum {
            voter_acks: 2,
            required_quorum: 2
        }
    ));

    let replication_options = ClusterRaftAppendReplicationOptions {
        max_attempts: 16,
        timeout: Duration::from_secs(2),
        tcp_command_timeout: Duration::from_secs(2),
        iroh_command_timeout: Duration::from_secs(2),
        tcp_foreground_attempt_timeout: Duration::from_secs(2),
        public_foreground_attempt_timeout: Duration::from_secs(2),
        iroh_foreground_attempt_timeout: Duration::from_secs(2),
    };
    for (endpoint, peer_paths) in [
        (state.members[1].endpoints[0].clone(), &peer_one_paths),
        (state.members[2].endpoints[0].clone(), &peer_two_paths),
    ] {
        let outcome = replicate_cluster_raft_to_endpoint_with_local_host(
            &leader_paths,
            &state,
            &endpoint,
            &[],
            replication_options,
            |_endpoint, request, _timeout| {
                handle_cluster_raft_append_request(
                    peer_paths,
                    request.clone(),
                    &authenticated_leader,
                )
            },
            || {},
        )
        .expect("restored peer catch-up");
        assert!(outcome.response.accepted);
    }

    for peer_paths in [&peer_one_paths, &peer_two_paths] {
        let peer_snapshot =
            read_cluster_kv_current_snapshot(peer_paths).expect("caught-up peer Raft view");
        assert_eq!(peer_snapshot.revision, committed.snapshot.revision);
        assert_eq!(peer_snapshot.entries, committed.snapshot.entries);
        assert!(peer_snapshot.get("/intermittent/converged").is_some());
    }
}

#[test]
fn cluster_raft_quorum_commit_observes_higher_rejected_append_term() {
    let root = sinomo_testdir::TestDir::new("sinomo-network-raft-quorum-observe-rejected-term");
    let data_dir = SinomoDataDir::new(&root);
    let paths = ClusterPaths::new(&data_dir);
    paths.ensure().expect("cluster paths");
    let (mut state, local_node_id, peer_node_id) = cluster_raft_handler_test_state(
        "cluster_raft_quorum_observe_rejected_term",
        "node_raft_quorum_observe_term_local",
        "node_raft_quorum_observe_term_peer",
    );
    let peer_endpoint = daemon_lan_endpoint(&peer_node_id, "10.0.0.85:21353".to_string(), 10);
    state
        .members
        .iter_mut()
        .find(|member| member.node_id == peer_node_id)
        .expect("peer member")
        .endpoints
        .push(peer_endpoint);
    write_cluster_state(&paths, &state).expect("write state");
    sync_cluster_state_to_local_raft_unchecked(&paths, &state).expect("seed committed raft config");
    let observed_term = 977;
    let response_state = state.clone();

    let error = commit_cluster_raft_command_with_local_storage_and_transport(
        &paths,
        &mut state,
        KvCommandRequest::generated(KvCommand::Op(KvOp::Put {
            key: "/quorum/rejected-term".to_string(),
            value: b"rejected".to_vec(),
            lease_id: None,
        })),
        ClusterKvRaftQuorumCommitOptions {
            timeout: Duration::from_secs(5),
        },
        ClusterControlPlaneTimeouts::default_daemon_transport(),
        move |_, _, _| {
            Ok(ClusterRaftAppendResponse {
                accepted: false,
                detail: "higher term".to_string(),
                state: response_state.clone(),
                append: sinomo_kv::RaftAppendEntriesResponse {
                    term: observed_term,
                    success: false,
                    match_index: 0,
                },
            })
        },
        |_, _, _, _, _| {},
        |_, _, _, _| {},
        || {},
    )
    .expect_err("commit must fail without remote ack");

    assert!(matches!(error, NetworkError::ClusterReadOnly { .. }));
    let node = open_cluster_raft_kv_node(&paths, &local_node_id).expect("open raft");
    assert_eq!(node.hard_state().current_term, observed_term);
    assert_eq!(node.hard_state().leader_id, None);
}

#[test]
fn blocked_quorum_transport_does_not_monopolize_local_raft_storage() {
    let root = sinomo_testdir::TestDir::new("sinomo-network-raft-blocked-quorum-storage");
    let data_dir = SinomoDataDir::new(&root);
    let paths = ClusterPaths::new(&data_dir);
    paths.ensure().expect("cluster paths");
    let (mut state, local_node_id, peer_node_id) = cluster_raft_handler_test_state(
        "cluster_raft_blocked_quorum_storage",
        "node_raft_blocked_quorum_local",
        "node_raft_blocked_quorum_peer",
    );
    state
        .members
        .iter_mut()
        .find(|member| member.node_id == peer_node_id)
        .expect("peer member")
        .endpoints
        .push(daemon_lan_endpoint(
            &peer_node_id,
            "10.0.0.184:21353".to_string(),
            10,
        ));
    write_cluster_state(&paths, &state).expect("write state");
    sync_cluster_state_to_local_raft_unchecked(&paths, &state).expect("seed committed raft config");

    let (send_started_tx, send_started_rx) = std::sync::mpsc::channel();
    let (release_send_tx, release_send_rx) = std::sync::mpsc::channel();
    let commit_paths = paths.clone();
    let commit = std::thread::spawn(move || {
        commit_cluster_raft_command_with_local_storage_and_transport(
            &commit_paths,
            &mut state,
            KvCommandRequest::generated(KvCommand::Op(KvOp::Put {
                key: "/quorum/blocked-transport".to_string(),
                value: b"committed".to_vec(),
                lease_id: None,
            })),
            ClusterKvRaftQuorumCommitOptions {
                timeout: Duration::from_secs(3),
            },
            ClusterControlPlaneTimeouts::default_daemon_transport(),
            move |_endpoint, request, _timeout| {
                send_started_tx.send(()).expect("report blocked send");
                release_send_rx.recv().expect("release blocked send");
                Ok(ClusterRaftAppendResponse {
                    accepted: true,
                    detail: "accepted after release".to_string(),
                    state: request.state.clone(),
                    append: sinomo_kv::RaftAppendEntriesResponse {
                        term: request.append.term,
                        success: true,
                        match_index: request
                            .append
                            .prev_log_index
                            .saturating_add(request.append.entries.len() as u64),
                    },
                })
            },
            |_, _, _, _, _| {},
            |_, _, _, _| {},
            || {},
        )
    });

    send_started_rx
        .recv_timeout(Duration::from_secs(2))
        .expect("quorum transport started");
    let diagnostic_paths = paths.clone();
    let (diagnostic_tx, diagnostic_rx) = std::sync::mpsc::channel();
    let diagnostic = std::thread::spawn(move || {
        let result = diagnostic_paths
            .kv_paths()
            .raft_store()
            .locked_last_log_index(&local_node_id)
            .map_err(kv_err);
        diagnostic_tx.send(result).expect("report diagnostic read");
    });
    let diagnostic_before_release = diagnostic_rx.recv_timeout(Duration::from_millis(500));
    release_send_tx.send(()).expect("release quorum transport");

    let last_log_index = diagnostic_before_release
        .expect("local Raft diagnostic must not wait for quorum transport")
        .expect("local Raft diagnostic succeeds");
    assert!(last_log_index > 0);
    commit
        .join()
        .expect("join quorum commit")
        .expect("quorum commit succeeds");
    diagnostic.join().expect("join diagnostic read");
}

#[test]
fn nonleader_quorum_retry_releases_local_raft_storage_for_reads() {
    let root = sinomo_testdir::TestDir::new("sinomo-network-raft-nonleader-storage-release");
    let data_dir = SinomoDataDir::new(&root);
    let paths = ClusterPaths::new(&data_dir);
    paths.ensure().expect("cluster paths");
    let (mut state, local_node_id, _peer_node_id) = cluster_raft_handler_test_state(
        "cluster_raft_nonleader_storage_release",
        "node_raft_nonleader_storage_local",
        "node_raft_nonleader_storage_peer",
    );
    write_cluster_state(&paths, &state).expect("write state");
    sync_cluster_state_to_local_raft_unchecked(&paths, &state).expect("seed committed raft config");
    let local_member = state
        .members
        .iter_mut()
        .find(|member| member.node_id == local_node_id)
        .expect("local member");
    local_member.role = ClusterMemberRole::NonVoting;
    local_member.state = ClusterMemberState::NonVoting;

    for attempt in 0..2 {
        let error = commit_cluster_raft_command_with_local_storage_and_transport(
            &paths,
            &mut state,
            KvCommandRequest::generated(KvCommand::Barrier),
            ClusterKvRaftQuorumCommitOptions {
                timeout: Duration::from_secs(1),
            },
            ClusterControlPlaneTimeouts::default_daemon_transport(),
            |_, _, _| panic!("nonleader must not send a Raft append"),
            |_, _, _, _, _| {},
            |_, _, _, _| {},
            || {},
        )
        .expect_err("non-voter cannot commit locally");
        assert!(matches!(error, NetworkError::ClusterReadOnly { .. }));

        let node = open_cluster_raft_kv_node(&paths, &local_node_id)
            .unwrap_or_else(|error| panic!("read after nonleader attempt {attempt}: {error}"));
        assert_eq!(node.hard_state().commit_index, node.applied_index());
    }
}

#[test]
fn cluster_raft_local_storage_quorum_helper_uses_callbacks_for_transport_and_fanout() {
    let root = sinomo_testdir::TestDir::new("sinomo-network-raft-local-quorum-helper");
    let data_dir = SinomoDataDir::new(&root);
    let paths = ClusterPaths::new(&data_dir);
    paths.ensure().expect("cluster paths");
    let (mut state, _local_node_id, peer_node_id) = cluster_raft_handler_test_state(
        "cluster_raft_local_quorum_helper",
        "node_raft_local_quorum_helper_local",
        "node_raft_local_quorum_helper_peer",
    );
    state
        .members
        .iter_mut()
        .find(|member| member.node_id == peer_node_id)
        .expect("peer member")
        .endpoints
        .push(daemon_lan_endpoint(
            &peer_node_id,
            "10.0.0.83:21353".to_string(),
            10,
        ));
    write_cluster_state(&paths, &state).expect("write state");
    sync_cluster_state_to_local_raft_unchecked(&paths, &state).expect("seed committed raft config");

    let append_calls = Arc::new(Mutex::new(Vec::new()));
    let connectivity = Arc::new(Mutex::new(Vec::new()));
    let fanout = Arc::new(Mutex::new(Vec::new()));
    let sent_count = Arc::new(Mutex::new(0usize));
    let append_calls_for_send = Arc::clone(&append_calls);
    let connectivity_for_record = Arc::clone(&connectivity);
    let fanout_for_callback = Arc::clone(&fanout);
    let sent_count_for_callback = Arc::clone(&sent_count);

    let result = commit_cluster_raft_command_with_local_storage_and_transport(
        &paths,
        &mut state,
        KvCommandRequest::generated(KvCommand::Op(KvOp::Put {
            key: "/quorum/local-helper".to_string(),
            value: b"committed".to_vec(),
            lease_id: None,
        })),
        ClusterKvRaftQuorumCommitOptions {
            timeout: Duration::from_secs(5),
        },
        ClusterControlPlaneTimeouts::default_daemon_transport(),
        move |endpoint, request, timeout| {
            append_calls_for_send
                .lock()
                .expect("append calls")
                .push((endpoint.node_id.clone(), timeout));
            Ok(ClusterRaftAppendResponse {
                accepted: true,
                detail: "accepted".to_string(),
                state: request.state.clone(),
                append: sinomo_kv::RaftAppendEntriesResponse {
                    term: request.append.term,
                    success: true,
                    match_index: request
                        .append
                        .prev_log_index
                        .saturating_add(request.append.entries.len() as u64),
                },
            })
        },
        move |_paths, _state, node_id, connectivity_state, latency_ms| {
            connectivity_for_record.lock().expect("connectivity").push((
                node_id.clone(),
                connectivity_state,
                latency_ms.is_some(),
            ));
        },
        move |_paths, _state, events, targets| {
            fanout_for_callback
                .lock()
                .expect("fanout")
                .push((events.len(), targets));
        },
        move || {
            *sent_count_for_callback.lock().expect("sent count") += 1;
        },
    )
    .expect("commit");

    assert_eq!(
        result
            .snapshot
            .get("/quorum/local-helper")
            .expect("committed entry")
            .value,
        b"committed".to_vec()
    );
    assert_eq!(
        append_calls
            .lock()
            .expect("append calls")
            .iter()
            .map(|(node_id, _)| node_id.clone())
            .collect::<Vec<_>>(),
        vec![peer_node_id.clone()]
    );
    assert_eq!(*sent_count.lock().expect("sent count"), 1);
    assert_eq!(
        connectivity.lock().expect("connectivity").as_slice(),
        &[(
            peer_node_id.clone(),
            ClusterConnectivityState::Healthy,
            true
        )]
    );
    assert_eq!(
        fanout.lock().expect("fanout").as_slice(),
        &[(1, vec![peer_node_id])]
    );
}

#[test]
fn cluster_raft_leader_election_driver_sets_leader_after_remote_voter_grants() {
    let root = sinomo_testdir::TestDir::new("sinomo-network-raft-leader-election");
    let data_dir = SinomoDataDir::new(&root);
    let paths = ClusterPaths::new(&data_dir);
    paths.ensure().expect("cluster paths");
    let (mut state, local_node_id, peer_node_id) = cluster_raft_handler_test_state(
        "cluster_raft_leader_election_driver",
        "node_raft_leader_election_local",
        "node_raft_leader_election_peer",
    );
    state
        .members
        .iter_mut()
        .find(|member| member.node_id == peer_node_id)
        .expect("peer member")
        .endpoints
        .push(daemon_lan_endpoint(
            &peer_node_id,
            "10.0.0.83:21353".to_string(),
            10,
        ));
    write_cluster_state(&paths, &state).expect("write state");
    let mut host = RecordingLeaderElectionHost::default();

    let elected = elect_cluster_raft_leader_with_host(
        &paths,
        &state,
        ClusterRaftLeaderElectionOptions {
            kv: ClusterKvRaftLeaderElectionOptions {
                max_attempts: sinomo_kv::CLUSTER_KV_RAFT_LEADER_ELECTION_ATTEMPTS,
            },
            timeout: Duration::from_secs(5),
            campaign_jitter_max: Duration::ZERO,
            tcp_command_timeout: Duration::from_secs(5),
            iroh_command_timeout: Duration::from_secs(3),
            tcp_foreground_attempt_timeout: Duration::from_secs(1),
            public_foreground_attempt_timeout: Duration::from_secs(4),
            iroh_foreground_attempt_timeout: Duration::from_millis(1500),
        },
        &mut host,
    )
    .expect("elect leader");

    assert!(elected);
    assert_eq!(
        paths
            .kv_paths()
            .known_raft_voter_leader_id(&state)
            .expect("known state authority"),
        Some(local_node_id)
    );
    let expected_term = sinomo_kv::CLUSTER_KV_RAFT_LEADER_ELECTION_TERM_BUMP + 1;
    assert_eq!(host.sent_votes.len(), 1);
    assert_eq!(host.sent_votes[0].0, peer_node_id);
    assert_eq!(host.sent_votes[0].1, expected_term);
    assert!(
        host.sent_votes[0].2 > Duration::from_secs(4),
        "node-targeted election should use the routed node budget, not a one-endpoint foreground slice"
    );
}

#[test]
fn cluster_raft_leader_election_fences_config_advanced_during_remote_vote() {
    struct ConfigAdvancingElectionHost {
        paths: ClusterPaths,
        config_advances: usize,
    }

    impl ClusterRaftVoteTransportHost for ConfigAdvancingElectionHost {
        fn send_raft_vote(
            &mut self,
            _state: &ClusterBootstrapState,
            _target_node_id: &NodeId,
            request: &ClusterRaftVoteRequest,
            _timeout: Duration,
        ) -> Result<ClusterRaftVoteResponse, NetworkError> {
            Ok(ClusterRaftVoteResponse {
                accepted: true,
                detail: "granted".to_string(),
                state: request.state.clone(),
                vote: sinomo_kv::RaftRequestVoteResponse {
                    term: request.vote.term,
                    vote_granted: true,
                },
            })
        }

        fn send_raft_votes(
            &mut self,
            state: &ClusterBootstrapState,
            targets: Vec<NodeId>,
            request: &ClusterRaftVoteRequest,
            timeout: Duration,
            required_grants: usize,
        ) -> Result<Vec<(NodeId, Result<ClusterRaftVoteResponse, NetworkError>)>, NetworkError>
        {
            // The durable self-vote has completed and released the campaign
            // lock before transport starts. Advance the exact committed
            // configuration entry in that gap; final leader publication must
            // reject the stale election fence even though the voter grants.
            sync_cluster_state_to_local_raft_unchecked(&self.paths, state)?;
            // The unchecked fixture sync bootstraps a local leader so it can
            // commit the config record. Clear that test-only side effect; the
            // election under test is the only path allowed to publish a
            // leader after the remote vote.
            self.paths
                .kv_paths()
                .raft_store()
                .locked_clear_leader_compact(&state.local_node_id)
                .expect("clear fixture-sync leader");
            self.config_advances += 1;
            Ok(targets
                .into_iter()
                .take(required_grants)
                .map(|target| {
                    let response = self.send_raft_vote(state, &target, request, timeout);
                    (target, response)
                })
                .collect())
        }
    }

    let root = sinomo_testdir::TestDir::new("sinomo-network-raft-election-config-fence");
    let data_dir = SinomoDataDir::new(&root);
    let paths = ClusterPaths::new(&data_dir);
    paths.ensure().expect("cluster paths");
    let (mut state, local_node_id, peer_node_id) = cluster_raft_handler_test_state(
        "cluster_raft_election_config_fence",
        "node_raft_election_config_fence_local",
        "node_raft_election_config_fence_peer",
    );
    state
        .members
        .iter_mut()
        .find(|member| member.node_id == peer_node_id)
        .expect("peer member")
        .endpoints
        .push(daemon_lan_endpoint(
            &peer_node_id,
            "10.0.0.183:21353".to_string(),
            10,
        ));
    write_cluster_state(&paths, &state).expect("write state");
    let mut host = ConfigAdvancingElectionHost {
        paths: paths.clone(),
        config_advances: 0,
    };

    let error = elect_cluster_raft_leader_with_host(
        &paths,
        &state,
        ClusterRaftLeaderElectionOptions {
            kv: ClusterKvRaftLeaderElectionOptions {
                max_attempts: sinomo_kv::CLUSTER_KV_RAFT_LEADER_ELECTION_ATTEMPTS,
            },
            timeout: Duration::from_secs(5),
            campaign_jitter_max: Duration::ZERO,
            tcp_command_timeout: Duration::from_secs(5),
            iroh_command_timeout: Duration::from_secs(3),
            tcp_foreground_attempt_timeout: Duration::from_secs(1),
            public_foreground_attempt_timeout: Duration::from_secs(4),
            iroh_foreground_attempt_timeout: Duration::from_millis(1500),
        },
        &mut host,
    )
    .expect_err("an advanced committed configuration must fence leader publication");

    assert!(matches!(
        error,
        NetworkError::ClusterReadOnly { detail }
            if detail.contains("configuration changed during leader election")
    ));
    assert_eq!(host.config_advances, 1);
    assert_eq!(
        paths
            .kv_paths()
            .known_raft_voter_leader_id(&state)
            .expect("known state authority"),
        None,
        "the stale campaign must not publish local leadership"
    );
    let node = open_cluster_raft_kv_node(&paths, &local_node_id).expect("open local raft node");
    assert_eq!(node.hard_state().leader_id, None);
}

#[test]
fn cluster_raft_leader_election_batch_does_not_wait_for_slow_first_voter() {
    #[derive(Default)]
    struct SlowFirstElectionBatchHost {
        batch_targets: Vec<NodeId>,
    }

    impl ClusterRaftVoteTransportHost for SlowFirstElectionBatchHost {
        fn send_raft_vote(
            &mut self,
            _state: &ClusterBootstrapState,
            _target_node_id: &NodeId,
            _request: &ClusterRaftVoteRequest,
            _timeout: Duration,
        ) -> Result<ClusterRaftVoteResponse, NetworkError> {
            panic!("the election regressed to serial per-voter dispatch")
        }

        fn send_raft_votes(
            &mut self,
            _state: &ClusterBootstrapState,
            targets: Vec<NodeId>,
            request: &ClusterRaftVoteRequest,
            _timeout: Duration,
            required_grants: usize,
        ) -> Result<Vec<(NodeId, Result<ClusterRaftVoteResponse, NetworkError>)>, NetworkError>
        {
            assert_eq!(required_grants, 1);
            assert_eq!(targets.len(), 2);
            self.batch_targets = targets.clone();
            // Model the first RPC as still pending. The concurrently completed
            // second voter is sufficient for quorum and must be consumable
            // without waiting for the first target in selection order.
            let fast_voter = targets.last().expect("second voter").clone();
            Ok(vec![(
                fast_voter,
                Ok(ClusterRaftVoteResponse {
                    accepted: true,
                    detail: "fast concurrent grant".to_string(),
                    state: request.state.clone(),
                    vote: sinomo_kv::RaftRequestVoteResponse {
                        term: request.vote.term,
                        vote_granted: true,
                    },
                }),
            )])
        }
    }

    let root = sinomo_testdir::TestDir::new("sinomo-network-raft-election-slow-first");
    let data_dir = SinomoDataDir::new(&root);
    let paths = ClusterPaths::new(&data_dir);
    paths.ensure().expect("cluster paths");
    let (mut state, local_node_id, first_peer_id) = cluster_raft_handler_test_state(
        "cluster_raft_election_slow_first",
        "node_raft_election_slow_first_local",
        "node_raft_election_slow_first_peer_one",
    );
    state.members[1].endpoints.push(daemon_lan_endpoint(
        &first_peer_id,
        "10.0.0.193:21353".to_string(),
        10,
    ));
    let second_peer_id =
        NodeId::from_legacy_named("node_raft_election_slow_first_peer_two").expect("second peer");
    let mut second_peer = state.members[1].clone();
    second_peer.node_id = second_peer_id.clone();
    second_peer.display_name = "second peer".to_string();
    second_peer.node_public_key = "second-peer-public-key".to_string();
    second_peer.endpoints = vec![daemon_lan_endpoint(
        &second_peer_id,
        "10.0.0.194:21353".to_string(),
        10,
    )];
    state.members.push(second_peer);
    write_cluster_state(&paths, &state).expect("write state");
    let mut host = SlowFirstElectionBatchHost::default();

    let elected = elect_cluster_raft_leader_with_host(
        &paths,
        &state,
        ClusterRaftLeaderElectionOptions {
            kv: ClusterKvRaftLeaderElectionOptions {
                max_attempts: sinomo_kv::CLUSTER_KV_RAFT_LEADER_ELECTION_ATTEMPTS,
            },
            timeout: Duration::from_secs(5),
            campaign_jitter_max: Duration::ZERO,
            tcp_command_timeout: Duration::from_secs(5),
            iroh_command_timeout: Duration::from_secs(3),
            tcp_foreground_attempt_timeout: Duration::from_secs(1),
            public_foreground_attempt_timeout: Duration::from_secs(4),
            iroh_foreground_attempt_timeout: Duration::from_millis(1500),
        },
        &mut host,
    )
    .expect("elect from the fast concurrent voter");

    assert!(elected);
    assert_eq!(host.batch_targets.len(), 2);
    assert_eq!(
        paths
            .kv_paths()
            .known_raft_voter_leader_id(&state)
            .expect("known state authority"),
        Some(local_node_id)
    );
}

#[test]
fn cluster_raft_leader_election_preserves_remote_leader_without_offline_evidence() {
    let root = sinomo_testdir::TestDir::new("sinomo-network-raft-live-remote-leader");
    let data_dir = SinomoDataDir::new(&root);
    let paths = ClusterPaths::new(&data_dir);
    paths.ensure().expect("cluster paths");
    let (mut state, local_node_id, peer_node_id) = cluster_raft_handler_test_state(
        "cluster_raft_live_remote_leader",
        "node_raft_live_remote_leader_local",
        "node_raft_live_remote_leader_peer",
    );
    let peer_endpoint = daemon_lan_endpoint(&peer_node_id, "10.0.0.84:21353".to_string(), 10);
    state
        .members
        .iter_mut()
        .find(|member| member.node_id == peer_node_id)
        .expect("peer member")
        .endpoints
        .push(peer_endpoint.clone());
    write_cluster_state(&paths, &state).expect("write state");
    let heartbeat = RaftAppendEntriesRequest {
        term: 1,
        leader_id: peer_node_id.clone(),
        prev_log_index: 0,
        prev_log_term: 0,
        entries: Vec::new(),
        leader_commit: 0,
    };
    assert!(
        apply_cluster_raft_append(&paths, &local_node_id, None, heartbeat)
            .expect("apply remote leader heartbeat")
            .success
    );
    let observed_at = OffsetDateTime::now_utc();
    let connectivity = cluster_connectivity_record(
        &state,
        &peer_endpoint,
        ClusterConnectivityState::Healthy,
        Some(1),
        0,
        Some("2026-07-16T23:00:00Z".to_string()),
        None,
        observed_at,
        CLUSTER_CONNECTIVITY_TTL_SECONDS,
    );
    write_local_cluster_connectivity_records(
        &paths,
        &local_node_id,
        std::slice::from_ref(&connectivity),
    )
    .expect("write healthy leader connectivity");
    assert!(!cluster_node_blocks_leader_preference(
        &paths,
        &state,
        &peer_node_id
    ));
    let mut host = RecordingLeaderElectionHost::default();

    let elected = elect_cluster_raft_leader_with_host(
        &paths,
        &state,
        ClusterRaftLeaderElectionOptions {
            kv: ClusterKvRaftLeaderElectionOptions {
                max_attempts: sinomo_kv::CLUSTER_KV_RAFT_LEADER_ELECTION_ATTEMPTS,
            },
            timeout: Duration::from_secs(5),
            campaign_jitter_max: Duration::ZERO,
            tcp_command_timeout: Duration::from_secs(5),
            iroh_command_timeout: Duration::from_secs(3),
            tcp_foreground_attempt_timeout: Duration::from_secs(1),
            public_foreground_attempt_timeout: Duration::from_secs(4),
            iroh_foreground_attempt_timeout: Duration::from_millis(1500),
        },
        &mut host,
    )
    .expect("preserve remote leader");

    assert!(!elected);
    assert!(host.sent_votes.is_empty());
    assert_eq!(
        paths
            .kv_paths()
            .known_raft_voter_leader_id(&state)
            .expect("known state authority"),
        Some(peer_node_id.clone())
    );
    let node = open_cluster_raft_kv_node(&paths, &local_node_id).expect("open local raft node");
    assert_eq!(node.hard_state().current_term, 1);
    assert_eq!(node.hard_state().leader_id.as_ref(), Some(&peer_node_id));
}

#[test]
fn cluster_raft_leader_election_replaces_unchanged_remote_leader() {
    let root = sinomo_testdir::TestDir::new("sinomo-network-raft-stale-remote-leader");
    let data_dir = SinomoDataDir::new(&root);
    let paths = ClusterPaths::new(&data_dir);
    paths.ensure().expect("cluster paths");
    let (mut state, local_node_id, peer_node_id) = cluster_raft_handler_test_state(
        "cluster_raft_stale_remote_leader",
        "node_raft_stale_remote_leader_local",
        "node_raft_stale_remote_leader_peer",
    );
    let peer_endpoint = daemon_lan_endpoint(&peer_node_id, "10.0.0.84:21353".to_string(), 10);
    let unobserved_peer_endpoint =
        daemon_lan_endpoint(&peer_node_id, "10.0.0.84:22353".to_string(), 20);
    state
        .members
        .iter_mut()
        .find(|member| member.node_id == peer_node_id)
        .expect("peer member")
        .endpoints
        .extend([peer_endpoint.clone(), unobserved_peer_endpoint]);
    write_cluster_state(&paths, &state).expect("write state");
    let heartbeat = RaftAppendEntriesRequest {
        term: 1,
        leader_id: peer_node_id.clone(),
        prev_log_index: 0,
        prev_log_term: 0,
        entries: Vec::new(),
        leader_commit: 0,
    };
    assert!(
        apply_cluster_raft_append(&paths, &local_node_id, None, heartbeat)
            .expect("apply stale remote leader heartbeat")
            .success
    );
    assert_eq!(
        paths
            .kv_paths()
            .known_raft_voter_leader_id(&state)
            .expect("known stale state authority"),
        Some(peer_node_id.clone())
    );
    let observed_at = OffsetDateTime::now_utc();
    let connectivity = cluster_connectivity_record(
        &state,
        &peer_endpoint,
        ClusterConnectivityState::Unreachable,
        None,
        CLUSTER_CONNECTIVITY_FAILURE_THRESHOLD,
        None,
        Some("2026-07-16T23:00:00Z".to_string()),
        observed_at,
        CLUSTER_CONNECTIVITY_UNREACHABLE_TTL_SECONDS,
    );
    write_local_cluster_connectivity_records(
        &paths,
        &local_node_id,
        std::slice::from_ref(&connectivity),
    )
    .expect("write unreachable leader connectivity");
    assert!(cluster_node_blocks_leader_preference(
        &paths,
        &state,
        &peer_node_id
    ));
    assert_eq!(
        sinomo_network::cluster_member_main_daemon_connectivity(
            &paths,
            &state,
            state
                .members
                .iter()
                .find(|member| member.node_id == peer_node_id)
                .expect("peer member"),
        ),
        sinomo_network::ClusterMemberMainDaemonConnectivity::Unknown,
        "the unobserved alternate keeps diagnostics unknown without preserving stale leadership"
    );
    let mut host = RecordingLeaderElectionHost::default();

    let elected = elect_cluster_raft_leader_with_host(
        &paths,
        &state,
        ClusterRaftLeaderElectionOptions {
            kv: ClusterKvRaftLeaderElectionOptions {
                max_attempts: sinomo_kv::CLUSTER_KV_RAFT_LEADER_ELECTION_ATTEMPTS,
            },
            timeout: Duration::from_secs(5),
            campaign_jitter_max: Duration::ZERO,
            tcp_command_timeout: Duration::from_secs(5),
            iroh_command_timeout: Duration::from_secs(3),
            tcp_foreground_attempt_timeout: Duration::from_secs(1),
            public_foreground_attempt_timeout: Duration::from_secs(4),
            iroh_foreground_attempt_timeout: Duration::from_millis(1500),
        },
        &mut host,
    )
    .expect("replace stale remote leader");

    assert!(elected);
    assert_eq!(
        paths
            .kv_paths()
            .known_raft_voter_leader_id(&state)
            .expect("known state authority"),
        Some(local_node_id)
    );
    assert_eq!(host.sent_votes.len(), 1);
    assert_eq!(host.sent_votes[0].0, peer_node_id);
    assert!(host.sent_votes[0].1 > 1);
}

#[test]
fn cluster_raft_leader_election_coalesces_rounds_without_holding_commit_lock_across_rpc() {
    let root = sinomo_testdir::TestDir::new("sinomo-network-raft-election-sequence");
    let data_dir = SinomoDataDir::new(&root);
    let paths = ClusterPaths::new(&data_dir);
    paths.ensure().expect("cluster paths");
    let (mut state, local_node_id, peer_node_id) = cluster_raft_handler_test_state(
        "cluster_raft_leader_election_sequence",
        "node_raft_election_sequence_local",
        "node_raft_election_sequence_peer",
    );
    state
        .members
        .iter_mut()
        .find(|member| member.node_id == peer_node_id)
        .expect("peer member")
        .endpoints
        .push(daemon_lan_endpoint(
            &peer_node_id,
            "10.0.0.83:21353".to_string(),
            10,
        ));
    write_cluster_state(&paths, &state).expect("write state");

    let options = ClusterRaftLeaderElectionOptions {
        kv: ClusterKvRaftLeaderElectionOptions {
            max_attempts: sinomo_kv::CLUSTER_KV_RAFT_LEADER_ELECTION_ATTEMPTS,
        },
        timeout: Duration::from_secs(5),
        campaign_jitter_max: Duration::ZERO,
        tcp_command_timeout: Duration::from_secs(5),
        iroh_command_timeout: Duration::from_secs(3),
        tcp_foreground_attempt_timeout: Duration::from_secs(1),
        public_foreground_attempt_timeout: Duration::from_secs(4),
        iroh_foreground_attempt_timeout: Duration::from_millis(1500),
    };
    let vote_calls = Arc::new(AtomicUsize::new(0));
    let (first_started_tx, first_started_rx) = std::sync::mpsc::channel();
    let (release_first_tx, release_first_rx) = std::sync::mpsc::channel();
    let first_paths = paths.clone();
    let first_state = state.clone();
    let first_vote_calls = Arc::clone(&vote_calls);
    let first = std::thread::spawn(move || {
        let mut host = BlockingLeaderElectionHost {
            vote_calls: first_vote_calls,
            started: Some(first_started_tx),
            release: Some(release_first_rx),
        };
        elect_cluster_raft_leader_with_host(&first_paths, &first_state, options, &mut host)
    });
    first_started_rx
        .recv_timeout(Duration::from_secs(2))
        .expect("first campaign reached remote vote");
    assert!(
        sinomo_kv::evict_resident_raft_node_for_test(
            &paths.kv_paths().raft_wal_paths(&local_node_id)
        ),
        "the first campaign should have released resident Raft storage before its vote RPC"
    );

    let (second_started_tx, second_started_rx) = std::sync::mpsc::channel();
    let second_paths = paths.clone();
    let second_state = state.clone();
    let second_vote_calls = Arc::clone(&vote_calls);
    let second = std::thread::spawn(move || {
        let mut host = BlockingLeaderElectionHost {
            vote_calls: second_vote_calls,
            started: Some(second_started_tx),
            release: None,
        };
        elect_cluster_raft_leader_with_host(&second_paths, &second_state, options, &mut host)
    });

    assert!(
        second_started_rx
            .recv_timeout(Duration::from_millis(150))
            .is_err(),
        "a second local election must coalesce behind the in-flight round"
    );
    let commit_lock =
        sinomo_kv::lock_cluster_kv_commit_sequence(&paths.kv_paths(), Duration::from_millis(150))
            .expect("vote RPC must not retain the global commit-sequence lock");
    drop(commit_lock);
    release_first_tx.send(()).expect("release first campaign");
    assert!(
        first
            .join()
            .expect("join first campaign")
            .expect("first campaign"),
        "the admitted campaign should publish leadership"
    );
    assert!(
        second
            .join()
            .expect("join second campaign")
            .expect("second campaign")
    );
    assert_eq!(
        vote_calls.load(Ordering::SeqCst),
        1,
        "the queued caller must reuse the durable predecessor outcome without another self-vote"
    );
    assert_eq!(
        paths
            .kv_paths()
            .known_raft_voter_leader_id(&state)
            .expect("known state authority"),
        Some(local_node_id)
    );
}

#[test]
fn simultaneous_reachable_candidates_with_third_voter_unavailable_stabilize_one_leader() {
    #[derive(Clone)]
    struct RoutedElectionHost {
        reachable_paths: Arc<BTreeMap<NodeId, ClusterPaths>>,
        vote_calls: Arc<AtomicUsize>,
        first_round_split: Arc<Barrier>,
        preferred_retry_candidate: NodeId,
        preferred_retry_completed: Arc<(Mutex<bool>, std::sync::Condvar)>,
    }

    impl ClusterRaftVoteTransportHost for RoutedElectionHost {
        fn send_raft_vote(
            &mut self,
            _state: &ClusterBootstrapState,
            target_node_id: &NodeId,
            request: &ClusterRaftVoteRequest,
            _timeout: Duration,
        ) -> Result<ClusterRaftVoteResponse, NetworkError> {
            self.vote_calls.fetch_add(1, Ordering::SeqCst);
            let target_paths =
                self.reachable_paths
                    .get(target_node_id)
                    .ok_or_else(|| NetworkError::Io {
                        operation: "test cluster raft vote".to_string(),
                        detail: format!("voter {target_node_id} is unavailable"),
                    })?;
            let candidate = request
                .state
                .members
                .iter()
                .find(|member| member.node_id == request.vote.candidate_id)
                .expect("candidate member");
            let runtime = tokio::runtime::Builder::new_current_thread()
                .enable_all()
                .build()
                .expect("vote RPC runtime");
            runtime.block_on(handle_cluster_raft_vote_request_async(
                runtime.handle(),
                target_paths,
                request.clone(),
                &ClusterAuthenticatedPeer {
                    node_id: candidate.node_id.to_string(),
                    public_key: candidate.node_public_key.clone(),
                },
            ))
        }

        fn send_raft_votes(
            &mut self,
            state: &ClusterBootstrapState,
            targets: Vec<NodeId>,
            request: &ClusterRaftVoteRequest,
            timeout: Duration,
            _required_grants: usize,
        ) -> Result<Vec<(NodeId, Result<ClusterRaftVoteResponse, NetworkError>)>, NetworkError>
        {
            let first_round_term = 1 + sinomo_kv::CLUSTER_KV_RAFT_LEADER_ELECTION_TERM_BUMP;
            let first_round = request.vote.term == first_round_term;
            if first_round {
                // Make the first generation a deterministic split vote: both
                // candidates must have persisted their self-vote before either
                // delivers RequestVote to the other.
                self.first_round_split.wait();
            }
            let outcomes = targets
                .into_iter()
                .map(|target| {
                    let response = self.send_raft_vote(state, &target, request, timeout);
                    (target, response)
                })
                .collect::<Vec<_>>();
            if first_round && request.vote.candidate_id != self.preferred_retry_candidate {
                // Do not depend on the process being scheduled within its
                // ranked wall-clock slot. Hold the lower-priority candidate in
                // its completed first round until the preferred retry has
                // delivered a higher-term vote. Its retry must then observe
                // that external durable advancement and stand down.
                let (completed, changed) = &*self.preferred_retry_completed;
                let mut completed = completed.lock().expect("retry completion lock");
                while !*completed {
                    completed = changed.wait(completed).expect("retry completion wait");
                }
            } else if !first_round && request.vote.candidate_id == self.preferred_retry_candidate {
                let (completed, changed) = &*self.preferred_retry_completed;
                *completed.lock().expect("retry completion lock") = true;
                changed.notify_all();
            }
            Ok(outcomes)
        }
    }

    let root_a = sinomo_testdir::TestDir::new("sinomo-raft-election-stable-candidate-a");
    let root_b = sinomo_testdir::TestDir::new("sinomo-raft-election-stable-candidate-b");
    let paths_a = ClusterPaths::new(&SinomoDataDir::new(&root_a));
    let paths_b = ClusterPaths::new(&SinomoDataDir::new(&root_b));
    paths_a.ensure().expect("candidate a paths");
    paths_b.ensure().expect("candidate b paths");
    let (mut state_a, node_a, node_b) = cluster_raft_handler_test_state(
        "cluster_raft_simultaneous_candidates",
        "node_raft_simultaneous_candidate_a",
        "node_raft_simultaneous_candidate_b",
    );
    let node_c =
        NodeId::from_legacy_named("node_raft_simultaneous_unavailable_c").expect("third voter");
    let mut member_c = state_a.members[1].clone();
    member_c.node_id = node_c.clone();
    member_c.display_name = "unavailable voter".to_string();
    member_c.node_public_key = "unavailable-voter-public-key".to_string();
    member_c.endpoints.clear();
    state_a.members.push(member_c);
    let mut state_b = state_a.clone();
    state_b.local_node_id = node_b.clone();
    write_cluster_state(&paths_a, &state_a).expect("candidate a state");
    write_cluster_state(&paths_b, &state_b).expect("candidate b state");

    let reachable_paths = Arc::new(BTreeMap::from([
        (node_a.clone(), paths_a.clone()),
        (node_b.clone(), paths_b.clone()),
    ]));
    let vote_calls = Arc::new(AtomicUsize::new(0));
    let first_round_split = Arc::new(Barrier::new(2));
    let preferred_retry_candidate = [node_a.clone(), node_b.clone()]
        .into_iter()
        .max()
        .expect("reachable retry candidate");
    let preferred_retry_completed = Arc::new((Mutex::new(false), std::sync::Condvar::new()));
    let start = Arc::new(Barrier::new(3));
    let options = ClusterRaftLeaderElectionOptions {
        kv: ClusterKvRaftLeaderElectionOptions {
            max_attempts: sinomo_kv::CLUSTER_KV_RAFT_LEADER_ELECTION_ATTEMPTS,
        },
        timeout: Duration::from_secs(8),
        // Three one-second ranked slots leave ample separation in the retry
        // generation after the deliberately forced split vote, without
        // changing any production timeout or stack setting.
        campaign_jitter_max: Duration::from_secs(3),
        tcp_command_timeout: Duration::from_secs(5),
        iroh_command_timeout: Duration::from_secs(3),
        tcp_foreground_attempt_timeout: Duration::from_secs(1),
        public_foreground_attempt_timeout: Duration::from_secs(4),
        iroh_foreground_attempt_timeout: Duration::from_millis(1500),
    };

    let thread_a = {
        let paths = paths_a.clone();
        let state = state_a.clone();
        let start = Arc::clone(&start);
        let mut host = RoutedElectionHost {
            reachable_paths: Arc::clone(&reachable_paths),
            vote_calls: Arc::clone(&vote_calls),
            first_round_split: Arc::clone(&first_round_split),
            preferred_retry_candidate: preferred_retry_candidate.clone(),
            preferred_retry_completed: Arc::clone(&preferred_retry_completed),
        };
        std::thread::spawn(move || {
            start.wait();
            elect_cluster_raft_leader_with_host(&paths, &state, options, &mut host)
        })
    };
    let thread_b = {
        let paths = paths_b.clone();
        let state = state_b.clone();
        let start = Arc::clone(&start);
        let mut host = RoutedElectionHost {
            reachable_paths: Arc::clone(&reachable_paths),
            vote_calls: Arc::clone(&vote_calls),
            first_round_split: Arc::clone(&first_round_split),
            preferred_retry_candidate: preferred_retry_candidate.clone(),
            preferred_retry_completed: Arc::clone(&preferred_retry_completed),
        };
        std::thread::spawn(move || {
            start.wait();
            elect_cluster_raft_leader_with_host(&paths, &state, options, &mut host)
        })
    };
    start.wait();
    let outcome_a = thread_a.join().expect("candidate a thread");
    let outcome_b = thread_b.join().expect("candidate b thread");
    let outcome_a = outcome_a.expect("candidate a election");
    let outcome_b = outcome_b.expect("candidate b election");
    assert_eq!(
        [outcome_a, outcome_b]
            .into_iter()
            .filter(|elected| *elected)
            .count(),
        1,
        "the preferred retry must win while the externally advanced candidate suppresses its stale campaign"
    );

    let hard_state_a = open_cluster_raft_kv_node(&paths_a, &node_a)
        .expect("candidate a raft")
        .hard_state()
        .clone();
    let hard_state_b = open_cluster_raft_kv_node(&paths_b, &node_b)
        .expect("candidate b raft")
        .hard_state()
        .clone();
    assert_eq!(hard_state_a.current_term, hard_state_b.current_term);
    assert!(
        hard_state_a.current_term > sinomo_kv::CLUSTER_KV_RAFT_LEADER_ELECTION_TERM_BUMP
            && hard_state_a.current_term
                <= 1 + 2 * sinomo_kv::CLUSTER_KV_RAFT_LEADER_ELECTION_TERM_BUMP,
        "two reachable simultaneous candidates should converge in at most two bounded rounds"
    );
    let local_leaders = [
        hard_state_a.leader_id.as_ref() == Some(&node_a),
        hard_state_b.leader_id.as_ref() == Some(&node_b),
    ];
    assert_eq!(
        local_leaders
            .into_iter()
            .filter(|is_leader| *is_leader)
            .count(),
        1,
        "exactly one candidate must retain leadership after the crossed votes"
    );
    let winner = if local_leaders[0] {
        node_a.clone()
    } else {
        node_b.clone()
    };
    let (loser_paths, loser_id) = if winner == node_a {
        (&paths_b, &node_b)
    } else {
        (&paths_a, &node_a)
    };
    assert!(
        apply_cluster_raft_append(
            loser_paths,
            loser_id,
            None,
            RaftAppendEntriesRequest {
                term: hard_state_a.current_term,
                leader_id: winner.clone(),
                prev_log_index: 0,
                prev_log_term: 0,
                entries: Vec::new(),
                leader_commit: 0,
            },
        )
        .expect("winning heartbeat")
        .success
    );

    let stable_term = hard_state_a.current_term;
    let mut no_vote_host_a = RecordingLeaderElectionHost::default();
    let mut no_vote_host_b = RecordingLeaderElectionHost::default();
    let stable_options = ClusterRaftLeaderElectionOptions {
        campaign_jitter_max: Duration::ZERO,
        ..options
    };
    let stable_a = elect_cluster_raft_leader_with_host(
        &paths_a,
        &state_a,
        stable_options,
        &mut no_vote_host_a,
    )
    .expect("stable candidate a observation");
    let stable_b = elect_cluster_raft_leader_with_host(
        &paths_b,
        &state_b,
        stable_options,
        &mut no_vote_host_b,
    )
    .expect("stable candidate b observation");
    assert_eq!(stable_a, winner == node_a);
    assert_eq!(stable_b, winner == node_b);
    assert!(no_vote_host_a.sent_votes.is_empty());
    assert!(no_vote_host_b.sent_votes.is_empty());
    assert_eq!(
        open_cluster_raft_kv_node(&paths_a, &node_a)
            .expect("stable candidate a raft")
            .hard_state()
            .current_term,
        stable_term
    );
    assert_eq!(
        open_cluster_raft_kv_node(&paths_b, &node_b)
            .expect("stable candidate b raft")
            .hard_state()
            .current_term,
        stable_term
    );
    assert!(vote_calls.load(Ordering::SeqCst) >= 2);
}

#[test]
fn cluster_raft_leader_election_targets_same_remote_voter_once_by_node() {
    let root = sinomo_testdir::TestDir::new("sinomo-network-raft-leader-same-voter-node");
    let data_dir = SinomoDataDir::new(&root);
    let paths = ClusterPaths::new(&data_dir);
    paths.ensure().expect("cluster paths");
    let (mut state, local_node_id, peer_node_id) = cluster_raft_handler_test_state(
        "cluster_raft_leader_same_voter_node",
        "node_raft_leader_same_voter_node_local",
        "node_raft_leader_same_voter_node_peer",
    );
    let private_endpoint = daemon_lan_endpoint(&peer_node_id, "10.0.0.41:21353".to_string(), 10);
    let mut public_endpoint =
        daemon_lan_endpoint(&peer_node_id, "198.51.100.76:21353".to_string(), 20);
    public_endpoint.privacy = ClusterEndpointPrivacy::InternetDirect;
    state
        .members
        .iter_mut()
        .find(|member| member.node_id == peer_node_id)
        .expect("peer member")
        .endpoints
        .extend([private_endpoint.clone(), public_endpoint.clone()]);
    write_cluster_state(&paths, &state).expect("write state");
    let mut host = NodeSensitiveLeaderElectionHost::default();

    let elected = elect_cluster_raft_leader_with_host(
        &paths,
        &state,
        ClusterRaftLeaderElectionOptions {
            kv: ClusterKvRaftLeaderElectionOptions {
                max_attempts: sinomo_kv::CLUSTER_KV_RAFT_LEADER_ELECTION_ATTEMPTS,
            },
            timeout: Duration::from_secs(5),
            campaign_jitter_max: Duration::ZERO,
            tcp_command_timeout: Duration::from_secs(5),
            iroh_command_timeout: Duration::from_secs(3),
            tcp_foreground_attempt_timeout: Duration::from_secs(1),
            public_foreground_attempt_timeout: Duration::from_secs(4),
            iroh_foreground_attempt_timeout: Duration::from_millis(1500),
        },
        &mut host,
    )
    .expect("elect leader");

    assert!(elected);
    assert_eq!(
        paths
            .kv_paths()
            .known_raft_voter_leader_id(&state)
            .expect("known state authority"),
        Some(local_node_id)
    );
    let expected_term = sinomo_kv::CLUSTER_KV_RAFT_LEADER_ELECTION_TERM_BUMP + 1;
    assert_eq!(host.sent_votes.len(), 1);
    assert_eq!(host.sent_votes[0].0, peer_node_id);
    assert_eq!(host.sent_votes[0].1, expected_term);
    assert!(
        host.sent_votes[0].2 > Duration::from_secs(4),
        "node-targeted election should use the routed node budget, not a one-endpoint foreground slice"
    );
}

