#[test]
fn join_introducer_reads_newer_invite_cache_only_for_non_voter_bridge() {
    let root = sinomo_testdir::TestDir::new("sinomo-network-join-bridge-invite-cache");
    let data_dir = SinomoDataDir::new(&root);
    let paths = ClusterPaths::new(&data_dir);
    paths.ensure().expect("cluster paths");
    let now = OffsetDateTime::now_utc();
    let cluster_id =
        ClusterId::from_legacy_named("cluster_join_bridge_invite_cache").expect("cluster");
    let issuer_node_id =
        NodeId::from_legacy_named("node_join_bridge_invite_cache_issuer").expect("issuer");
    let bridge_node_id =
        NodeId::from_legacy_named("node_join_bridge_invite_cache_bridge").expect("bridge");
    let joined_node_id =
        NodeId::from_legacy_named("node_join_bridge_invite_cache_joined").expect("joined");
    let issuer_identity =
        sinomo_node::load_or_create_main_node_identity(&root).expect("issuer identity");
    let mut state = ClusterBootstrapState::initialized_locally(
        cluster_id.clone(),
        "join bridge invite cache",
        issuer_node_id.clone(),
        "issuer",
        issuer_identity.public_key.clone(),
        now,
    );
    state.members[0].capabilities = sinomo_node::main_daemon_capabilities(&state.members[0].role);
    state.members[0].allowed_capabilities = state.members[0].capabilities.clone();
    state.members[0].endpoints = vec![daemon_lan_endpoint(
        &issuer_node_id,
        "authority:21353".to_string(),
        0,
    )];
    let mut bridge = ClusterMemberRecord::pending_learner(
        cluster_id.clone(),
        bridge_node_id.clone(),
        "bridge",
        "pk-bridge",
        now,
    );
    bridge.state = ClusterMemberState::Learner;
    bridge.capabilities = sinomo_node::main_daemon_capabilities(&bridge.role);
    bridge.allowed_capabilities = bridge.capabilities.clone();
    state.members.push(bridge);

    let mut invite = ClusterJoinInvite {
        invite_id: ClusterInviteId::from_legacy_named("invite_join_bridge_cache").expect("invite"),
        cluster_id: cluster_id.clone(),
        cluster_name: Some("join bridge invite cache".to_string()),
        cluster_public_key: issuer_identity.public_key.clone(),
        invitation_secret: "secret-join-bridge-cache".to_string(),
        communication_channels: Vec::new(),
        introducers: Vec::new(),
        token_id: "token-join-bridge-cache".to_string(),
        expires_at: now + time::Duration::hours(1),
        trust_domain: TrustDomain::new("trust.local").expect("trust domain"),
        allowed_member_roles: vec![ClusterMemberRole::Learner],
        issuer_node_id: issuer_node_id.clone(),
        issuer_public_key: issuer_identity.public_key.clone(),
        signature: String::new(),
    };
    invite.signature = sign_cluster_join_invite(&invite, &issuer_identity).expect("sign invite");

    state.local_node_id = bridge_node_id;
    state.local_node_display_name = "bridge".to_string();
    write_cluster_state(&paths, &state).expect("write bridge state");

    let current_snapshot = append_cluster_raft_command(
        &paths,
        &state.local_node_id,
        KvCommand::Op(KvOp::Put {
            key: "/test/join-bridge-applied-baseline".to_string(),
            value: b"baseline".to_vec(),
            lease_id: None,
        }),
    )
    .expect("seed applied learner view");
    let mut cached_store =
        InProcessKvStore::restore(current_snapshot).expect("restore applied learner view");
    cached_store
        .put_serde(
            sinomo_node::cluster_invitation_key(&invite.invite_id),
            &invite,
            None,
        )
        .expect("cache invitation");
    write_cluster_kv_snapshot(&paths, &cached_store.snapshot().expect("cached snapshot"))
        .expect("write newer read cache");

    assert!(
        read_cluster_invitation_from_kv(&paths, &invite.invite_id).is_err(),
        "the applied learner Raft view intentionally remains behind the imported cache"
    );
    assert_eq!(
        read_cluster_invitation_for_join_introducer(&paths, &state, &invite.invite_id)
            .expect("bridge invite read"),
        invite
    );

    let registration_request = ClusterJoinRegistrationRequest {
        invite: invite.clone(),
        invitation_secret: invite.invitation_secret.clone(),
        members: vec![ClusterMemberRecord::pending_learner(
            cluster_id,
            joined_node_id,
            "joined",
            "pk-joined",
            now,
        )],
    };
    let accepted = prepare_cluster_join_registration_response(
        &paths,
        state.clone(),
        registration_request.clone(),
        now,
    )
    .expect("bridge join preflight");
    assert!(accepted.accepted);

    let mut authority_view = state.clone();
    authority_view.local_node_id = issuer_node_id.clone();
    assert!(
        read_cluster_invitation_for_join_introducer(&paths, &authority_view, &invite.invite_id,)
            .is_err(),
        "a voter must not authorize from a materialized snapshot ahead of applied Raft"
    );
}

#[test]
fn cluster_join_registration_prepare_accepts_signed_learner_and_rejects_role_escalation() {
    let root = sinomo_testdir::TestDir::new("sinomo-network-join-prepare");
    let data_dir = SinomoDataDir::new(&root);
    let paths = ClusterPaths::new(&data_dir);
    paths.ensure().expect("cluster paths");
    let now = OffsetDateTime::now_utc();
    let cluster_id = ClusterId::from_legacy_named("cluster_join_prepare").expect("cluster");
    let issuer_node_id = NodeId::from_legacy_named("node_join_prepare_issuer").expect("issuer");
    let joined_node_id = NodeId::from_legacy_named("node_join_prepare_joined").expect("joined");
    let issuer_identity =
        sinomo_node::load_or_create_main_node_identity(&root).expect("issuer identity");
    let state = ClusterBootstrapState::initialized_locally(
        cluster_id.clone(),
        "join prepare",
        issuer_node_id.clone(),
        "issuer",
        issuer_identity.public_key.clone(),
        now,
    );
    write_cluster_state(&paths, &state).expect("write state");
    let mut invite = ClusterJoinInvite {
        invite_id: ClusterInviteId::from_legacy_named("invite_join_prepare").expect("invite"),
        cluster_id: cluster_id.clone(),
        cluster_name: Some("join prepare".to_string()),
        cluster_public_key: issuer_identity.public_key.clone(),
        invitation_secret: "secret-join-prepare".to_string(),
        communication_channels: Vec::new(),
        introducers: Vec::new(),
        token_id: "token-join-prepare".to_string(),
        expires_at: now + time::Duration::hours(1),
        trust_domain: TrustDomain::new("trust.local").expect("trust domain"),
        allowed_member_roles: vec![ClusterMemberRole::Learner],
        issuer_node_id: issuer_node_id.clone(),
        issuer_public_key: issuer_identity.public_key.clone(),
        signature: String::new(),
    };
    invite.signature = sign_cluster_join_invite(&invite, &issuer_identity).expect("sign invite");
    sync_cluster_invitation_to_local_raft_unchecked(&paths, &invite).expect("sync invitation");
    let learner_member = ClusterMemberRecord::pending_learner(
        cluster_id.clone(),
        joined_node_id.clone(),
        "joined",
        "pk-joined",
        now,
    );

    let accepted = prepare_cluster_join_registration_response(
        &paths,
        state.clone(),
        ClusterJoinRegistrationRequest {
            invite: invite.clone(),
            invitation_secret: invite.invitation_secret.clone(),
            members: vec![learner_member],
        },
        now,
    )
    .expect("prepare join registration");

    assert!(accepted.accepted);
    assert!(accepted.kv_snapshot.is_none());
    assert!(accepted.state.members.iter().any(|member| {
        member.node_id == joined_node_id && member.state == ClusterMemberState::Learner
    }));

    let mut voter_member = ClusterMemberRecord::pending_learner(
        cluster_id,
        joined_node_id,
        "joined",
        "pk-joined",
        now,
    );
    voter_member.role = ClusterMemberRole::Voter;
    let rejected = prepare_cluster_join_registration_response(
        &paths,
        state,
        ClusterJoinRegistrationRequest {
            invite: invite.clone(),
            invitation_secret: invite.invitation_secret,
            members: vec![voter_member],
        },
        now,
    )
    .expect("reject role escalation");

    assert!(!rejected.accepted);
    assert!(rejected.detail.contains("role not allowed"));
}

#[test]
fn cluster_join_registration_state_preparation_applies_local_daemon_member_facts() {
    let now = OffsetDateTime::now_utc();
    let cluster_id =
        ClusterId::from_legacy_named("cluster_join_prepare_local_members").expect("cluster");
    let local_node_id =
        NodeId::from_legacy_named("node_join_prepare_local_members").expect("local node");
    let mut state = ClusterBootstrapState::pending_join(
        cluster_id,
        "join prepare local members",
        local_node_id.clone(),
        "local",
        "old-main-pk",
        now,
    );
    let shadow_node_id = sinomo_node::shadow_daemon_node_id(&local_node_id);
    let main_endpoint = daemon_lan_endpoint(&local_node_id, "10.40.0.1:21353".to_string(), 0);
    let shadow_endpoint = daemon_lan_endpoint(&shadow_node_id, "10.40.0.1:21354".to_string(), 10);

    state = prepare_cluster_join_registration_state_with_local_daemon_members(
        state,
        vec![main_endpoint.clone()],
        vec![shadow_endpoint.clone()],
        "main-pk".to_string(),
        "shadow-pk".to_string(),
        now,
    );

    let main = state
        .members
        .iter()
        .find(|member| member.node_id == local_node_id)
        .expect("main daemon member");
    assert_eq!(main.node_public_key, "main-pk");
    assert_eq!(main.state, ClusterMemberState::Pending);
    assert!(main.endpoints.contains(&main_endpoint));
    assert_eq!(main.role, ClusterMemberRole::Learner);
    assert!(
        main.endpoints
            .iter()
            .any(|endpoint| endpoint.address == shadow_endpoint.address)
    );
}

#[derive(Default)]
struct RecordingJoinRegistrationHost {
    observations: usize,
    observation: Option<ClusterLocalDaemonMembershipObservation>,
    authoritative_reads: usize,
    quorum_commits: usize,
    admission_commit_attempts: usize,
    committed: Vec<ClusterBootstrapState>,
    remembered_targets: usize,
    force_compare_failure: bool,
    compare_failures_remaining: usize,
    compare_failure_on_commit: Option<usize>,
    compare_failures_starting_at_commit: Option<usize>,
    authoritative_read_basis: Option<sinomo_kv::KvAuthorityBasis>,
    authoritative_read_basis_after_first: Option<sinomo_kv::KvAuthorityBasis>,
    compare_failure_basis: Option<sinomo_kv::KvAuthorityBasis>,
    replay_failed_compare: bool,
    successful_commit_basis: Option<sinomo_kv::KvAuthorityBasis>,
    first_commit_barrier: Option<Arc<Barrier>>,
    commit_attempt_barriers: Vec<Arc<Barrier>>,
    waited_on_first_commit: bool,
    async_first_commit_delay: Duration,
}

impl RecordingJoinRegistrationHost {
    fn is_join_lifecycle_completion(request: &KvTxnRequest) -> bool {
        let [KvOp::Put { key, value, .. }] = request.txn.success.as_slice() else {
            return false;
        };
        key.starts_with("/cluster/raft/config-changes/")
            && sinomo_kv::decode_kv_value::<sinomo_kv::ClusterKvRaftConfigChange>(value).is_ok_and(
                |change| change.phase == sinomo_kv::ClusterKvRaftConfigChangePhase::Committed,
            )
    }

    fn ensure_authoritative_test_state(
        paths: &ClusterPaths,
        state: &ClusterBootstrapState,
    ) -> Result<(), NetworkError> {
        let needs_bootstrap = read_cluster_kv_current_snapshot(paths)
            .ok()
            .is_none_or(|snapshot| {
                snapshot
                    .get(&sinomo_kv::cluster_kv_raft_config_key())
                    .is_none()
            });
        if needs_bootstrap {
            sync_cluster_state_to_local_raft_unchecked(paths, state)?;
        }
        Ok(())
    }

    fn commit_test_join_txn(
        &mut self,
        paths: &ClusterPaths,
        state: &mut ClusterBootstrapState,
        request: KvTxnRequest,
    ) -> Result<ClusterKvTxnCommitResult, NetworkError> {
        Self::ensure_authoritative_test_state(paths, state)?;
        let lifecycle_completion = Self::is_join_lifecycle_completion(&request);
        if !lifecycle_completion
            && !self.waited_on_first_commit
            && let Some(barrier) = self.first_commit_barrier.clone()
        {
            self.waited_on_first_commit = true;
            barrier.wait();
        }
        if !lifecycle_completion
            && let Some(barrier) = self
                .commit_attempt_barriers
                .get(self.admission_commit_attempts)
                .cloned()
        {
            barrier.wait();
        }
        self.quorum_commits += 1;
        if !lifecycle_completion {
            self.admission_commit_attempts += 1;
        }
        let request_id = request.request_id;
        let compare_failure_for_commit = self.compare_failure_on_commit
            == Some(self.admission_commit_attempts)
            || self
                .compare_failures_starting_at_commit
                .is_some_and(|first| self.admission_commit_attempts >= first);
        if !lifecycle_completion
            && (self.force_compare_failure
                || self.compare_failures_remaining > 0
                || compare_failure_for_commit)
        {
            self.force_compare_failure = false;
            self.compare_failures_remaining = self.compare_failures_remaining.saturating_sub(1);
            let snapshot = read_cluster_kv_current_snapshot(paths)?;
            let revision = snapshot.revision;
            let mut result = test_cluster_kv_txn_commit_result_for_request(
                request_id,
                snapshot,
                Some(KvTxnResponse {
                    succeeded: false,
                    revision,
                    responses: Vec::new(),
                }),
            );
            if let Some(basis) = self.compare_failure_basis {
                result.authority.basis = basis;
            }
            if self.replay_failed_compare {
                result.authority.basis = sinomo_kv::KvAuthorityBasis::ExactCommittedRequest;
                result.replayed_committed_request = true;
            }
            return Ok(result);
        }
        if self.committed.is_empty() && !request.txn.success.is_empty() {
            self.committed.push(state.clone());
        }
        let (snapshot, response) = append_cluster_raft_command_with_response(
            paths,
            &state.local_node_id,
            KvCommand::Txn(request.txn),
        )?;
        let mut result =
            test_cluster_kv_txn_commit_result_for_request(request_id, snapshot, response);
        if self.replay_failed_compare
            && result
                .txn_response
                .as_ref()
                .is_some_and(|response| !response.succeeded)
        {
            result.authority.basis = sinomo_kv::KvAuthorityBasis::ExactCommittedRequest;
            result.replayed_committed_request = true;
        }
        if let Some(basis) = self.successful_commit_basis {
            result.authority.basis = basis;
        }
        Ok(result)
    }
}

impl ClusterJoinRegistrationHost for RecordingJoinRegistrationHost {
    fn local_daemon_membership_observation(
        &mut self,
        _paths: &ClusterPaths,
        _state: &ClusterBootstrapState,
    ) -> Result<Option<ClusterLocalDaemonMembershipObservation>, NetworkError> {
        self.observations += 1;
        Ok(self.observation.clone())
    }

    fn call_node_object_rpc(
        &mut self,
        _state: &ClusterBootstrapState,
        _target_node_id: &NodeId,
        _request: &ObjectRpcRequest,
    ) -> Result<ObjectRpcResponse, NetworkError> {
        panic!("voter-local join registration should not forward membership node RPCs")
    }

    fn authoritative_cluster_kv_snapshot(
        &mut self,
        paths: &ClusterPaths,
        state: &mut ClusterBootstrapState,
    ) -> Result<sinomo_kv::KvAuthoritativeRead<KvSnapshot>, NetworkError> {
        self.authoritative_reads += 1;
        Self::ensure_authoritative_test_state(paths, state)?;
        let mut authoritative = test_authoritative_cluster_kv_snapshot(paths)?;
        let basis = if self.authoritative_reads > 1 {
            self.authoritative_read_basis_after_first
                .or(self.authoritative_read_basis)
        } else {
            self.authoritative_read_basis
        };
        if let Some(basis) = basis {
            authoritative.authority.basis = basis;
        }
        Ok(authoritative)
    }

    fn commit_join_registration_txn(
        &mut self,
        paths: &ClusterPaths,
        state: &mut ClusterBootstrapState,
        request: KvTxnRequest,
    ) -> Result<ClusterKvTxnCommitResult, NetworkError> {
        self.commit_test_join_txn(paths, state, request)
    }

    fn admit_cluster_raft_learner(
        &mut self,
        paths: &ClusterPaths,
        state: &mut ClusterBootstrapState,
        node_id: &NodeId,
        now: OffsetDateTime,
    ) -> Result<KvSnapshot, NetworkError> {
        update_cluster_state_authority_with_host(
            paths,
            state.clone(),
            node_id.clone(),
            ClusterMemberRole::Learner,
            now,
            self,
        )?;
        ClusterMemberMutationHost::authoritative_cluster_kv_snapshot(self, paths, state)
            .map(|read| read.value)
    }

    fn remember_successful_join_endpoint(
        &mut self,
        _paths: &ClusterPaths,
        _state: &ClusterBootstrapState,
        _endpoint: &ClusterEndpointRecord,
    ) -> Result<(), NetworkError> {
        self.remembered_targets += 1;
        Ok(())
    }
}

impl ClusterMemberMutationHost for RecordingJoinRegistrationHost {
    fn authoritative_cluster_kv_snapshot(
        &mut self,
        paths: &ClusterPaths,
        state: &mut ClusterBootstrapState,
    ) -> Result<sinomo_kv::KvAuthoritativeRead<KvSnapshot>, NetworkError> {
        RecordingJoinRegistrationHost::ensure_authoritative_test_state(paths, state)?;
        test_authoritative_cluster_kv_snapshot(paths)
    }

    fn commit_cluster_kv_txn_with_quorum(
        &mut self,
        paths: &ClusterPaths,
        state: &mut ClusterBootstrapState,
        request: KvTxnRequest,
    ) -> Result<ClusterKvTxnCommitResult, NetworkError> {
        self.commit_test_join_txn(paths, state, request)
    }
}

impl ClusterMemberMutationAsyncHost for RecordingJoinRegistrationHost {
    fn authoritative_cluster_kv_snapshot_async<'a>(
        &'a mut self,
        paths: &'a ClusterPaths,
        state: &'a mut ClusterBootstrapState,
    ) -> ClusterMembershipRpcFuture<'a, sinomo_kv::KvAuthoritativeRead<KvSnapshot>> {
        Box::pin(async move {
            ClusterMemberMutationHost::authoritative_cluster_kv_snapshot(self, paths, state)
        })
    }

    fn commit_cluster_kv_txn_with_quorum_async<'a>(
        &'a mut self,
        paths: &'a ClusterPaths,
        state: &'a mut ClusterBootstrapState,
        request: KvTxnRequest,
    ) -> ClusterMembershipRpcFuture<'a, ClusterKvTxnCommitResult> {
        Box::pin(async move { self.commit_test_join_txn(paths, state, request) })
    }
}

impl ClusterObjectRpcAsyncHost for RecordingJoinRegistrationHost {}

impl ClusterJoinRegistrationAsyncHost for RecordingJoinRegistrationHost {
    fn local_daemon_membership_observation_async<'a>(
        &'a mut self,
        _paths: &'a ClusterPaths,
        _state: &'a ClusterBootstrapState,
    ) -> ClusterMembershipRpcFuture<'a, Option<ClusterLocalDaemonMembershipObservation>> {
        Box::pin(async move {
            self.observations += 1;
            Ok(self.observation.clone())
        })
    }

    fn authoritative_cluster_kv_snapshot_async<'a>(
        &'a mut self,
        paths: &'a ClusterPaths,
        state: &'a mut ClusterBootstrapState,
    ) -> ClusterMembershipRpcFuture<'a, sinomo_kv::KvAuthoritativeRead<KvSnapshot>> {
        Box::pin(async move {
            ClusterJoinRegistrationHost::authoritative_cluster_kv_snapshot(self, paths, state)
        })
    }

    fn commit_join_registration_txn_async<'a>(
        &'a mut self,
        paths: &'a ClusterPaths,
        state: &'a mut ClusterBootstrapState,
        request: KvTxnRequest,
    ) -> ClusterMembershipRpcFuture<'a, ClusterKvTxnCommitResult> {
        Box::pin(async move {
            if self.quorum_commits == 0 && !self.async_first_commit_delay.is_zero() {
                tokio::time::sleep(self.async_first_commit_delay).await;
            }
            self.commit_test_join_txn(paths, state, request)
        })
    }

    fn admit_cluster_raft_learner_async<'a>(
        &'a mut self,
        paths: &'a ClusterPaths,
        state: &'a mut ClusterBootstrapState,
        node_id: &'a NodeId,
        now: OffsetDateTime,
    ) -> ClusterMembershipRpcFuture<'a, KvSnapshot> {
        Box::pin(async move {
            add_cluster_raft_learner_async_with_host(paths, state, node_id, now, self).await
        })
    }

    fn remember_successful_join_endpoint_async<'a>(
        &'a mut self,
        _paths: &'a ClusterPaths,
        _state: &'a ClusterBootstrapState,
        _endpoint: &'a ClusterEndpointRecord,
    ) -> ClusterMembershipRpcFuture<'a, ()> {
        Box::pin(async move {
            self.remembered_targets += 1;
            Ok(())
        })
    }
}

#[derive(Default)]
struct RecordingJoinEndpointHost {
    remembered: Vec<ClusterEndpointRecord>,
}

impl ClusterJoinRegistrationHost for RecordingJoinEndpointHost {
    fn call_node_object_rpc(
        &mut self,
        _state: &ClusterBootstrapState,
        _target_node_id: &NodeId,
        _request: &ObjectRpcRequest,
    ) -> Result<ObjectRpcResponse, NetworkError> {
        panic!("default target remembering should not send membership node RPCs")
    }

    fn remember_successful_join_endpoint(
        &mut self,
        _paths: &ClusterPaths,
        _state: &ClusterBootstrapState,
        endpoint: &ClusterEndpointRecord,
    ) -> Result<(), NetworkError> {
        self.remembered.push(endpoint.clone());
        Ok(())
    }
}

#[test]
fn join_registration_host_default_remembers_remote_nonlocal_endpoints() {
    let root = sinomo_testdir::TestDir::new("sinomo-network-join-remember-targets");
    let data_dir = SinomoDataDir::new(&root);
    let paths = ClusterPaths::new(&data_dir);
    paths.ensure().expect("cluster paths");
    let now = OffsetDateTime::now_utc();
    let cluster_id =
        ClusterId::from_legacy_named("cluster_join_remember_targets").expect("cluster");
    let local = NodeId::from_legacy_named("node_join_remember_local").expect("local");
    let remote = NodeId::from_legacy_named("node_join_remember_remote").expect("remote");
    let mut state = ClusterBootstrapState::initialized_locally(
        cluster_id.clone(),
        "join remember targets",
        local.clone(),
        "local",
        "pk-local",
        now,
    );
    state.members[0].endpoints = vec![daemon_lan_endpoint(
        &local,
        "127.0.0.1:21353".to_string(),
        0,
    )];
    let local_member = state.members[0].clone();
    let mut local_only = daemon_lan_endpoint(&remote, "127.0.0.1:21353".to_string(), 0);
    local_only.privacy = ClusterEndpointPrivacy::LocalOnly;
    let remote_endpoint = daemon_lan_endpoint(&remote, "10.20.0.8:21353".to_string(), 10);
    let mut remote_member =
        ClusterMemberRecord::pending_learner(cluster_id, remote, "remote", "pk-remote", now);
    remote_member.endpoints = vec![local_only, remote_endpoint.clone()];
    let mut host = RecordingJoinEndpointHost::default();

    ClusterJoinRegistrationHost::remember_successful_join_targets(
        &mut host,
        &paths,
        &state,
        &[local_member, remote_member],
    )
    .expect("remember targets");

    assert_eq!(host.remembered, vec![remote_endpoint]);
}

#[test]
fn cluster_join_registration_handler_voter_commits_through_host() {
    let root = sinomo_testdir::TestDir::new("sinomo-network-join-handler-voter");
    let data_dir = SinomoDataDir::new(&root);
    let paths = ClusterPaths::new(&data_dir);
    paths.ensure().expect("cluster paths");
    let now = OffsetDateTime::now_utc();
    let cluster_id = ClusterId::from_legacy_named("cluster_join_handler_voter").expect("cluster");
    let issuer_node_id =
        NodeId::from_legacy_named("node_join_handler_voter_issuer").expect("issuer");
    let joined_node_id =
        NodeId::from_legacy_named("node_join_handler_voter_joined").expect("joined");
    let issuer_identity =
        sinomo_node::load_or_create_main_node_identity(&root).expect("issuer identity");
    let mut state = ClusterBootstrapState::initialized_locally(
        cluster_id.clone(),
        "join handler voter",
        issuer_node_id.clone(),
        "issuer",
        issuer_identity.public_key.clone(),
        now,
    );
    let capabilities = sinomo_node::main_daemon_capabilities(&ClusterMemberRole::Voter);
    state.members[0].capabilities = capabilities.clone();
    state.members[0].allowed_capabilities = capabilities;
    write_cluster_state(&paths, &state).expect("write state");
    let mut invite = ClusterJoinInvite {
        invite_id: ClusterInviteId::from_legacy_named("invite_join_handler_voter").expect("invite"),
        cluster_id: cluster_id.clone(),
        cluster_name: Some("join handler voter".to_string()),
        cluster_public_key: issuer_identity.public_key.clone(),
        invitation_secret: "secret-join-handler-voter".to_string(),
        communication_channels: Vec::new(),
        introducers: Vec::new(),
        token_id: "token-join-handler-voter".to_string(),
        expires_at: now + time::Duration::hours(1),
        trust_domain: TrustDomain::new("trust.local").expect("trust domain"),
        allowed_member_roles: vec![ClusterMemberRole::Learner],
        issuer_node_id: issuer_node_id.clone(),
        issuer_public_key: issuer_identity.public_key.clone(),
        signature: String::new(),
    };
    invite.signature = sign_cluster_join_invite(&invite, &issuer_identity).expect("sign invite");
    sync_cluster_invitation_to_local_raft_unchecked(&paths, &invite).expect("sync invitation");
    let mut learner_member = ClusterMemberRecord::pending_learner(
        cluster_id,
        joined_node_id.clone(),
        "joined",
        "pk-joined",
        now,
    );
    learner_member.endpoints = vec![daemon_lan_endpoint(
        &joined_node_id,
        "10.42.0.11:21353".to_string(),
        10,
    )];
    let observed_main_endpoint =
        daemon_lan_endpoint(&issuer_node_id, "10.42.0.10:21353".to_string(), 10);
    let observed_shadow_endpoint = daemon_lan_endpoint(
        &sinomo_node::shadow_daemon_node_id(&issuer_node_id),
        "10.42.0.10:21354".to_string(),
        10,
    );
    let mut host = RecordingJoinRegistrationHost {
        observation: Some(ClusterLocalDaemonMembershipObservation {
            main_endpoints: vec![observed_main_endpoint.clone()],
            shadow_endpoints: vec![observed_shadow_endpoint],
            main_public_key: issuer_identity.public_key.clone(),
            shadow_public_key: "observed-shadow-public-key".to_string(),
            timestamp: now,
        }),
        ..Default::default()
    };

    let response = handle_cluster_join_registration_request_with_host(
        &paths,
        ClusterJoinRegistrationRequest {
            invite: invite.clone(),
            invitation_secret: invite.invitation_secret,
            members: vec![learner_member],
        },
        now,
        &mut host,
    )
    .expect("handle join registration");

    assert!(response.accepted, "join should be accepted");
    assert_eq!(host.observations, 1);
    assert_eq!(host.authoritative_reads, 1);
    assert_eq!(
        host.quorum_commits, 2,
        "join admission should atomically apply the learner, then record exact commit evidence"
    );
    assert_eq!(host.committed.len(), 1);
    assert_eq!(host.remembered_targets, 1);
    let committed = &response.state;
    assert!(committed.members.iter().any(|member| {
        member.node_id == joined_node_id && member.state == ClusterMemberState::Learner
    }));
    let local_member = committed
        .members
        .iter()
        .find(|member| member.node_id == issuer_node_id)
        .expect("observed local member");
    assert!(local_member.endpoints.contains(&observed_main_endpoint));
    let snapshot = response
        .kv_snapshot
        .as_ref()
        .expect("voter commit should attach kv snapshot");
    let joined_from_snapshot: ClusterMemberRecord = snapshot
        .get(&cluster_member_key(&joined_node_id))
        .expect("joined member in committed snapshot")
        .decode()
        .expect("decode joined member");
    assert_eq!(joined_from_snapshot.state, ClusterMemberState::Learner);
    let stored = read_cluster_state_without_kv(&paths).expect("read stored state");
    assert!(stored.members.iter().any(|member| {
        member.node_id == joined_node_id && member.state == ClusterMemberState::Learner
    }));
}

#[test]
fn cluster_join_registration_handler_voter_skips_bridge_channel_target_connectivity() {
    let root = sinomo_testdir::TestDir::new("sinomo-network-join-handler-bridge-channel");
    let data_dir = SinomoDataDir::new(&root);
    let paths = ClusterPaths::new(&data_dir);
    paths.ensure().expect("cluster paths");
    let now = OffsetDateTime::now_utc();
    let cluster_id =
        ClusterId::from_legacy_named("cluster_join_handler_bridge_channel").expect("cluster");
    let issuer_node_id =
        NodeId::from_legacy_named("node_join_handler_bridge_channel_issuer").expect("issuer");
    let bridge_node_id =
        NodeId::from_legacy_named("node_join_handler_bridge_channel_bridge").expect("bridge");
    let joined_node_id =
        NodeId::from_legacy_named("node_join_handler_bridge_channel_joined").expect("joined");
    let issuer_identity =
        sinomo_node::load_or_create_main_node_identity(&root).expect("issuer identity");
    let mut state = ClusterBootstrapState::initialized_locally(
        cluster_id.clone(),
        "join handler bridge channel",
        issuer_node_id.clone(),
        "issuer",
        issuer_identity.public_key.clone(),
        now,
    );
    let capabilities = sinomo_node::main_daemon_capabilities(&ClusterMemberRole::Voter);
    state.members[0].capabilities = capabilities.clone();
    state.members[0].allowed_capabilities = capabilities;
    let mut bridge_member = ClusterMemberRecord::local_voter(
        cluster_id.clone(),
        bridge_node_id.clone(),
        "bridge",
        "pk-bridge",
        now,
    );
    apply_cluster_raft_role(&mut bridge_member, ClusterMemberRole::Learner, now);
    bridge_member.endpoints = vec![daemon_lan_endpoint(
        &bridge_node_id,
        "bridge:21353".to_string(),
        0,
    )];
    upsert_member_record(&mut state, bridge_member);
    write_cluster_state(&paths, &state).expect("write state");
    let bridge_channel_endpoint =
        daemon_lan_endpoint(&issuer_node_id, "bridge:21353".to_string(), 0);
    let mut invite = ClusterJoinInvite {
        invite_id: ClusterInviteId::from_legacy_named("invite_join_handler_bridge_channel")
            .expect("invite"),
        cluster_id: cluster_id.clone(),
        cluster_name: Some("join handler bridge channel".to_string()),
        cluster_public_key: issuer_identity.public_key.clone(),
        invitation_secret: "secret-join-handler-bridge-channel".to_string(),
        communication_channels: vec![ClusterInvitationChannel {
            endpoint: bridge_channel_endpoint,
            node_public_key: issuer_identity.public_key.clone(),
        }],
        introducers: Vec::new(),
        token_id: "token-join-handler-bridge-channel".to_string(),
        expires_at: now + time::Duration::hours(1),
        trust_domain: TrustDomain::new("trust.local").expect("trust domain"),
        allowed_member_roles: vec![ClusterMemberRole::Learner],
        issuer_node_id: issuer_node_id.clone(),
        issuer_public_key: issuer_identity.public_key.clone(),
        signature: String::new(),
    };
    invite.signature = sign_cluster_join_invite(&invite, &issuer_identity).expect("sign invite");
    sync_cluster_invitation_to_local_raft_unchecked(&paths, &invite).expect("sync invitation");
    let mut learner_member = ClusterMemberRecord::pending_learner(
        cluster_id,
        joined_node_id.clone(),
        "joined",
        "pk-joined",
        now,
    );
    learner_member.endpoints = vec![daemon_lan_endpoint(
        &joined_node_id,
        "leaf:21353".to_string(),
        10,
    )];
    let mut host = RecordingJoinRegistrationHost::default();

    let response = handle_cluster_join_registration_request_with_host(
        &paths,
        ClusterJoinRegistrationRequest {
            invite: invite.clone(),
            invitation_secret: invite.invitation_secret,
            members: vec![learner_member],
        },
        now,
        &mut host,
    )
    .expect("handle join registration");

    assert!(response.accepted, "join should be accepted");
    assert_eq!(host.committed.len(), 1);
    assert_eq!(
        host.remembered_targets, 0,
        "the voter did not observe a direct response path to the bridge-channel joiner"
    );
    let stored = read_cluster_state_without_kv(&paths).expect("read stored state");
    assert!(stored.members.iter().any(|member| {
        member.node_id == joined_node_id && member.state == ClusterMemberState::Learner
    }));
}

