#[test]
fn cluster_join_registration_async_coalesces_waiting_admission_authority() {
    let fixture = join_authority_fixture("join_async_coalesced_admission");
    let first_request = join_authority_fixture_request(&fixture);
    let mut second_request = first_request.clone();
    let second_node_id = NodeId::from_legacy_named("node_join_async_coalesced_admission_second")
        .expect("second joiner id");
    second_request.members[0].node_id = second_node_id.clone();
    second_request.members[0].display_name = "second joined".to_string();
    second_request.members[0].node_public_key = format!("pk-{second_node_id}");
    let mut first_host = RecordingJoinRegistrationHost {
        async_first_commit_delay: Duration::from_millis(25),
        ..Default::default()
    };
    let mut second_host = RecordingJoinRegistrationHost {
        async_first_commit_delay: Duration::from_millis(25),
        ..Default::default()
    };
    let runtime = tokio::runtime::Builder::new_current_thread()
        .enable_all()
        .build()
        .expect("runtime");
    let handle = runtime.handle().clone();

    let (first_response, second_response) = runtime.block_on(async {
        tokio::join!(
            handle_cluster_join_registration_request_async_with_host(
                &handle,
                &fixture.paths,
                first_request,
                fixture.now,
                &mut first_host,
            ),
            handle_cluster_join_registration_request_async_with_host(
                &handle,
                &fixture.paths,
                second_request,
                fixture.now + time::Duration::milliseconds(1),
                &mut second_host,
            )
        )
    });
    let first_response = first_response.expect("first coalesced join");
    let second_response = second_response.expect("second coalesced join");

    assert!(first_response.accepted, "{}", first_response.detail);
    assert!(second_response.accepted, "{}", second_response.detail);
    assert_eq!(
        first_host.authoritative_reads + second_host.authoritative_reads,
        1,
        "the waiter should reuse the preceding admission's current-term quorum result"
    );
    assert_eq!(first_host.quorum_commits, 2);
    assert_eq!(second_host.quorum_commits, 2);
    let snapshot = read_cluster_kv_current_snapshot(&fixture.paths).expect("coalesced snapshot");
    assert!(
        snapshot
            .get(&cluster_member_key(&fixture.joined_node_id))
            .is_some()
    );
    assert!(snapshot.get(&cluster_member_key(&second_node_id)).is_some());
}

#[test]
fn cluster_join_registration_async_reuses_authority_between_sequential_join_waves() {
    let fixture = join_authority_fixture("join_async_sequential_admission");
    let first_request = join_authority_fixture_request(&fixture);
    let mut second_request = first_request.clone();
    let second_node_id = NodeId::from_legacy_named("node_join_async_sequential_admission_second")
        .expect("second joiner id");
    second_request.members[0].node_id = second_node_id.clone();
    second_request.members[0].display_name = "second joined".to_string();
    second_request.members[0].node_public_key = format!("pk-{second_node_id}");
    let mut first_host = RecordingJoinRegistrationHost::default();
    let mut second_host = RecordingJoinRegistrationHost::default();
    let runtime = tokio::runtime::Builder::new_current_thread()
        .enable_all()
        .build()
        .expect("runtime");

    let first_response = runtime
        .block_on(handle_cluster_join_registration_request_async_with_host(
            runtime.handle(),
            &fixture.paths,
            first_request,
            fixture.now,
            &mut first_host,
        ))
        .expect("first sequential join");
    let second_response = runtime
        .block_on(handle_cluster_join_registration_request_async_with_host(
            runtime.handle(),
            &fixture.paths,
            second_request,
            fixture.now + time::Duration::milliseconds(1),
            &mut second_host,
        ))
        .expect("second sequential join");

    assert!(first_response.accepted, "{}", first_response.detail);
    assert!(second_response.accepted, "{}", second_response.detail);
    assert_eq!(first_host.authoritative_reads, 1);
    assert_eq!(
        second_host.authoritative_reads, 0,
        "the completed admission must retain its current-term quorum snapshot for the next join wave"
    );
    assert_eq!(first_host.quorum_commits, 2);
    assert_eq!(second_host.quorum_commits, 2);
    let snapshot = read_cluster_kv_current_snapshot(&fixture.paths).expect("sequential snapshot");
    assert!(
        snapshot
            .get(&cluster_member_key(&fixture.joined_node_id))
            .is_some()
    );
    assert!(snapshot.get(&cluster_member_key(&second_node_id)).is_some());
}

#[test]
fn cluster_join_registration_async_does_not_coalesce_exact_request_proof() {
    let fixture = join_authority_fixture("join_async_exact_proof_admission");
    let first_request = join_authority_fixture_request(&fixture);
    let mut second_request = first_request.clone();
    let second_node_id = NodeId::from_legacy_named("node_join_async_exact_proof_admission_second")
        .expect("second joiner id");
    second_request.members[0].node_id = second_node_id.clone();
    second_request.members[0].display_name = "second joined".to_string();
    second_request.members[0].node_public_key = format!("pk-{second_node_id}");
    let exact_basis = sinomo_kv::KvAuthorityBasis::ExactCommittedRequest;
    let mut first_host = RecordingJoinRegistrationHost {
        successful_commit_basis: Some(exact_basis),
        async_first_commit_delay: Duration::from_millis(25),
        ..Default::default()
    };
    let mut second_host = RecordingJoinRegistrationHost {
        successful_commit_basis: Some(exact_basis),
        async_first_commit_delay: Duration::from_millis(25),
        ..Default::default()
    };
    let runtime = tokio::runtime::Builder::new_current_thread()
        .enable_all()
        .build()
        .expect("runtime");
    let handle = runtime.handle().clone();

    let (first_response, second_response) = runtime.block_on(async {
        tokio::join!(
            handle_cluster_join_registration_request_async_with_host(
                &handle,
                &fixture.paths,
                first_request,
                fixture.now,
                &mut first_host,
            ),
            handle_cluster_join_registration_request_async_with_host(
                &handle,
                &fixture.paths,
                second_request,
                fixture.now + time::Duration::milliseconds(1),
                &mut second_host,
            )
        )
    });
    let first_response = first_response.expect("first exact-proof join");
    let second_response = second_response.expect("second exact-proof join");

    assert!(first_response.accepted, "{}", first_response.detail);
    assert!(second_response.accepted, "{}", second_response.detail);
    assert_eq!(
        first_host.authoritative_reads + second_host.authoritative_reads,
        2,
        "an exact-request replay proof cannot stand in for the waiter's fresh quorum read"
    );
    assert_eq!(first_host.quorum_commits, 2);
    assert_eq!(second_host.quorum_commits, 2);
}

#[test]
fn cluster_join_registration_retries_benign_atomic_admission_compare_race() {
    let fixture = join_authority_fixture("join_learner_apply_losing_cas");
    let mut host = RecordingJoinRegistrationHost {
        compare_failure_on_commit: Some(1),
        ..Default::default()
    };

    let response = handle_cluster_join_registration_request_with_host(
        &fixture.paths,
        join_authority_fixture_request(&fixture),
        fixture.now,
        &mut host,
    )
    .expect("retry losing atomic admission CAS");

    assert!(response.accepted, "{}", response.detail);
    assert_eq!(host.authoritative_reads, 1);
    assert_eq!(
        host.quorum_commits, 3,
        "the failed atomic admission should reprepare, commit, and record exact lifecycle evidence"
    );
    let snapshot = response.kv_snapshot.expect("accepted join snapshot");
    assert_eq!(
        snapshot
            .range_prefix_limited("/cluster/raft/config-changes/", 8)
            .expect("learner admission changes")
            .len(),
        1,
        "the failed attempt must not leave a partial or duplicate plan"
    );
}

fn exercise_join_exact_failed_compare_replay(asynchronous: bool, invalid_refresh: bool) {
    let fixture = join_authority_fixture(&format!(
        "join_exact_failed_compare_{asynchronous}_{invalid_refresh}"
    ));
    let mut host = RecordingJoinRegistrationHost {
        compare_failure_on_commit: Some(1),
        replay_failed_compare: true,
        authoritative_read_basis_after_first: invalid_refresh
            .then_some(sinomo_kv::KvAuthorityBasis::ExactCommittedRequest),
        ..Default::default()
    };
    let request = join_authority_fixture_request(&fixture);
    let result = if asynchronous {
        let runtime = tokio::runtime::Builder::new_current_thread()
            .enable_all()
            .build()
            .unwrap();
        runtime.block_on(handle_cluster_join_registration_request_async_with_host(
            runtime.handle(),
            &fixture.paths,
            request,
            fixture.now,
            &mut host,
        ))
    } else {
        handle_cluster_join_registration_request_with_host(
            &fixture.paths,
            request,
            fixture.now,
            &mut host,
        )
    };
    assert_eq!(
        host.authoritative_reads, 2,
        "an exact failed-request replay requires a distinct current-term read before re-preparation"
    );
    if invalid_refresh {
        assert!(
            matches!(result, Err(NetworkError::ClusterReadOnly { detail })
            if detail.contains("current-term quorum authority proof"))
        );
        assert_eq!(
            host.quorum_commits, 1,
            "an invalid refresh cannot authorize another admission attempt"
        );
        assert!(
            read_cluster_kv_current_snapshot(&fixture.paths)
                .unwrap()
                .get(&cluster_member_key(&fixture.joined_node_id))
                .is_none()
        );
    } else {
        let response = result.expect("fresh authority permits the bounded admission retry");
        assert!(response.accepted, "{}", response.detail);
        assert_eq!(host.quorum_commits, 3);
        let snapshot = response.kv_snapshot.unwrap();
        assert_eq!(
            snapshot
                .range_prefix_limited("/cluster/raft/config-changes/", 8)
                .unwrap()
                .len(),
            1
        );
        let member: ClusterMemberRecord = snapshot
            .get(&cluster_member_key(&fixture.joined_node_id))
            .unwrap()
            .decode()
            .unwrap();
        assert_eq!(member.state, ClusterMemberState::Learner);
        assert_eq!(member.role, ClusterMemberRole::Learner);
    }
}

#[test]
fn cluster_join_registration_refreshes_exact_failed_compare_replay() {
    exercise_join_exact_failed_compare_replay(false, false);
}

#[test]
fn cluster_join_registration_async_refreshes_exact_failed_compare_replay() {
    exercise_join_exact_failed_compare_replay(true, false);
}

#[test]
fn cluster_join_registration_exact_failed_compare_replay_rejects_invalid_refresh() {
    exercise_join_exact_failed_compare_replay(true, true);
}

#[test]
fn cluster_join_registration_exact_failed_compare_replay_keeps_attempt_limit() {
    for asynchronous in [false, true] {
        let fixture = join_authority_fixture(&format!("join_exact_replay_cap_{asynchronous}"));
        let mut host = RecordingJoinRegistrationHost {
            compare_failures_starting_at_commit: Some(1),
            replay_failed_compare: true,
            ..Default::default()
        };
        let request = join_authority_fixture_request(&fixture);
        let response = if asynchronous {
            let runtime = tokio::runtime::Builder::new_current_thread()
                .enable_all()
                .build()
                .unwrap();
            runtime.block_on(handle_cluster_join_registration_request_async_with_host(
                runtime.handle(),
                &fixture.paths,
                request,
                fixture.now,
                &mut host,
            ))
        } else {
            handle_cluster_join_registration_request_with_host(
                &fixture.paths,
                request,
                fixture.now,
                &mut host,
            )
        }
        .unwrap();
        assert!(!response.accepted);
        assert!(response.detail.contains("changed during join admission"));
        assert_eq!(
            host.quorum_commits, 16,
            "the existing admission-attempt cap is unchanged"
        );
        assert_eq!(
            host.authoritative_reads, 16,
            "one initial cut plus one fresh cut per remaining retry; no read after exhaustion"
        );
        let snapshot = read_cluster_kv_current_snapshot(&fixture.paths).unwrap();
        assert!(
            snapshot
                .get(&cluster_member_key(&fixture.joined_node_id))
                .is_none()
        );
        assert!(
            snapshot
                .range_prefix_limited("/cluster/raft/config-changes/", 8)
                .unwrap()
                .is_empty()
        );
    }
}

#[test]
