#[test]
fn cluster_join_reconciliation_polls_after_ambiguous_committed_registration() {
    let root = sinomo_testdir::TestDir::new("sinomo-network-join-reconcile-ambiguous-commit");
    let data_dir = SinomoDataDir::new(&root);
    let paths = ClusterPaths::new(&data_dir);
    paths.ensure().expect("cluster paths");
    let now = OffsetDateTime::now_utc();
    let cluster_id =
        ClusterId::from_legacy_named("cluster_network_join_reconcile_ambiguous_commit")
            .expect("cluster");
    let joined = NodeId::from_legacy_named("node_network_join_reconcile_ambiguous_commit_joined")
        .expect("joined");
    let issuer = NodeId::from_legacy_named("node_network_join_reconcile_ambiguous_commit_issuer")
        .expect("issuer");
    let endpoint = daemon_lan_endpoint(&issuer, "node5:21353".to_string(), 0);
    let mut pending = ClusterBootstrapState::pending_join(
        cluster_id.clone(),
        "join reconcile ambiguous commit",
        joined.clone(),
        "joined",
        "pk-joined",
        now,
    );
    let original_local_node_id = pending.local_node_id.clone();
    let original_local_public_key = pending
        .members
        .iter()
        .find(|member| member.node_id == joined)
        .expect("pending local member")
        .node_public_key
        .clone();
    let mut committed = ClusterBootstrapState::initialized_locally(
        cluster_id.clone(),
        "join reconcile ambiguous commit",
        issuer.clone(),
        "issuer",
        "pk-issuer",
        now,
    );
    let mut joined_member = ClusterMemberRecord::local_voter(
        cluster_id.clone(),
        joined.clone(),
        "joined",
        original_local_public_key.clone(),
        now,
    );
    apply_cluster_raft_role(&mut joined_member, ClusterMemberRole::Learner, now);
    upsert_member_record(&mut committed, joined_member);
    let snapshot =
        sync_cluster_state_to_local_raft_unchecked(&paths, &committed).expect("committed snapshot");
    let invite = ClusterJoinInvite {
        invite_id: ClusterInviteId::from_legacy_named(
            "invite_network_join_reconcile_ambiguous_commit",
        )
        .expect("invite"),
        cluster_id,
        cluster_name: Some("join reconcile ambiguous commit".to_string()),
        cluster_public_key: "pk-issuer".to_string(),
        invitation_secret: "secret".to_string(),
        communication_channels: vec![ClusterInvitationChannel {
            endpoint: endpoint.clone(),
            node_public_key: "pk-issuer".to_string(),
        }],
        introducers: Vec::new(),
        token_id: "token".to_string(),
        expires_at: now + time::Duration::hours(1),
        trust_domain: TrustDomain::new("trust.local").expect("trust"),
        allowed_member_roles: vec![ClusterMemberRole::Learner],
        issuer_node_id: issuer,
        issuer_public_key: "pk-issuer".to_string(),
        signature: String::new(),
    };
    let mut host = RecordingJoinReconciliationHost {
        snapshot: Some(snapshot),
        send_fails: true,
        snapshot_failures_before_success: 1,
        ..Default::default()
    };

    let reconciliation = reconcile_cluster_join_with_introducers_with_host(
        &mut pending,
        &invite,
        Duration::from_millis(100),
        Duration::from_millis(100),
        Some(&paths),
        &mut host,
    )
    .expect("reconcile ambiguous committed join");

    assert_eq!(
        host.sends,
        vec![endpoint.clone()],
        "snapshot polling must not resend the registration"
    );
    assert_eq!(
        host.snapshots,
        vec![endpoint.clone(), endpoint.clone()],
        "reconciliation should poll until the committed snapshot becomes visible"
    );
    assert_eq!(host.retry_waits.len(), 1);
    assert_eq!(host.observed, vec![endpoint.clone()]);
    assert_eq!(reconciliation.accepted_endpoint, Some(endpoint));
    assert_eq!(pending.local_node_id, original_local_node_id);
    let accepted_local_members = pending
        .members
        .iter()
        .filter(|member| member.node_id == joined)
        .collect::<Vec<_>>();
    assert_eq!(
        accepted_local_members.len(),
        1,
        "the committed identity must be accepted exactly once"
    );
    assert_eq!(
        accepted_local_members[0].node_public_key,
        original_local_public_key
    );
    assert_eq!(accepted_local_members[0].state, ClusterMemberState::Learner);
}

#[test]
fn cluster_control_plane_driver_owns_join_reconciliation_transport() {
    #[derive(Clone)]
    struct RecordingJoinReconciliationTransport {
        paths: ClusterPaths,
        identity: sinomo_node::NodeIdentity,
        accepted_state: ClusterBootstrapState,
        sent_routes: Vec<String>,
        connectivity: Vec<ClusterEndpointRecord>,
        snapshot_fetches: usize,
    }

    impl ClusterControlPlaneTransport for RecordingJoinReconciliationTransport {
        fn send_kv_replication(
            &mut self,
            _endpoint: &ClusterEndpointRecord,
            _request: &sinomo_kv::ClusterKvReplicationRequest,
            _timeout: Duration,
        ) -> Result<sinomo_kv::ClusterKvReplicationResponse, NetworkError> {
            panic!("join reconciliation should not send kv replication")
        }

        fn request_kv_state_authority_vote(
            &mut self,
            _endpoint: &ClusterEndpointRecord,
            _request: &sinomo_kv::ClusterKvStateAuthorityVoteRequest,
            _timeout: Duration,
        ) -> Result<sinomo_kv::ClusterKvStateAuthorityVoteResponse, NetworkError> {
            panic!("join reconciliation should not send kv state authority vote")
        }

        fn probe_cluster_state_authority(
            &mut self,
            _endpoint: &ClusterEndpointRecord,
            _timeout: Duration,
        ) -> bool {
            panic!("join reconciliation should not probe voters")
        }

        fn fetch_cluster_kv_snapshot(
            &mut self,
            _endpoint: &ClusterEndpointRecord,
            _timeout: Duration,
        ) -> Result<KvSnapshot, NetworkError> {
            self.snapshot_fetches += 1;
            Err(NetworkError::Io {
                operation: "test snapshot fetch".to_string(),
                detail: "accepted response should not need snapshot fallback".to_string(),
            })
        }

        fn call_endpoint_object_rpc(
            &mut self,
            _endpoint: &ClusterEndpointRecord,
            request: &ObjectRpcRequest,
            _timeout: Duration,
        ) -> Result<ObjectRpcResponse, NetworkError> {
            self.sent_routes.push(request.route.clone());
            match request.route.as_str() {
                CLUSTER_JOIN_CHALLENGE_ROUTE => {
                    let challenge: ClusterInviteChallengeRequest = request.decode_body()?;
                    let proof = native_test_invite_challenge_proof(
                        &self.paths,
                        &self.identity,
                        &challenge,
                    )?;
                    ObjectRpcResponse::encode_body(CLUSTER_JOIN_CHALLENGE_ROUTE, &proof)
                }
                CLUSTER_JOIN_REGISTER_ROUTE => {
                    assert!(
                        request.is_response_retry_safe(),
                        "idempotent join registration must permit a fresh-auth redispatch after an ambiguous pooled-connection failure"
                    );
                    let registration: ClusterJoinRegistrationRequest = request.decode_body()?;
                    ObjectRpcResponse::encode_body(
                        CLUSTER_JOIN_REGISTER_ROUTE,
                        &ClusterJoinRegistrationResponse {
                            accepted: true,
                            detail: format!("accepted {}", registration.invite.invite_id.as_str()),
                            state: self.accepted_state.clone(),
                            kv_snapshot: None,
                            responder_node_id: None,
                        },
                    )
                }
                route => Err(NetworkError::Io {
                    operation: "test membership rpc".to_string(),
                    detail: format!("unexpected route {route}"),
                }),
            }
        }

        fn call_node_object_rpc(
            &mut self,
            _state: &ClusterBootstrapState,
            _target_node_id: &NodeId,
            _request: &ObjectRpcRequest,
            _timeout: Duration,
        ) -> Result<ObjectRpcResponse, NetworkError> {
            panic!("join reconciliation should not send node rpc")
        }

        fn record_endpoint_command_connectivity(
            &mut self,
            _paths: &ClusterPaths,
            _state: &ClusterBootstrapState,
            endpoint: &ClusterEndpointRecord,
            connectivity_state: ClusterConnectivityState,
            latency_ms: Option<u64>,
        ) {
            assert_eq!(connectivity_state, ClusterConnectivityState::Healthy);
            assert_eq!(latency_ms, None);
            self.connectivity.push(endpoint.clone());
        }
    }

    let root = sinomo_testdir::TestDir::new("sinomo-network-driver-join-reconcile");
    let data_dir = SinomoDataDir::new(&root);
    let paths = ClusterPaths::new(&data_dir);
    paths.ensure().expect("cluster paths");
    let now = OffsetDateTime::now_utc();
    let cluster_id =
        ClusterId::from_legacy_named("cluster_driver_join_reconcile").expect("cluster");
    let issuer = NodeId::from_legacy_named("node_driver_join_reconcile_issuer").expect("issuer");
    let joined = NodeId::from_legacy_named("node_driver_join_reconcile_joined").expect("joined");
    let issuer_identity =
        sinomo_node::load_or_create_main_node_identity(&root).expect("issuer identity");
    let endpoint = daemon_lan_endpoint(&issuer, "10.34.0.2:21353".to_string(), 0);
    let mut issuer_state = ClusterBootstrapState::initialized_locally(
        cluster_id.clone(),
        "driver join reconcile",
        issuer.clone(),
        "issuer",
        issuer_identity.public_key.clone(),
        now,
    );
    ensure_main_daemon_cluster_member(&mut issuer_state, vec![endpoint.clone()], now);
    write_cluster_state(&paths, &issuer_state).expect("write issuer state");
    sync_cluster_state_to_local_raft_unchecked(&paths, &issuer_state).expect("sync state");

    let mut invite = ClusterJoinInvite {
        invite_id: ClusterInviteId::from_legacy_named("invite_driver_join_reconcile")
            .expect("invite"),
        cluster_id: cluster_id.clone(),
        cluster_name: Some("driver join reconcile".to_string()),
        cluster_public_key: issuer_identity.public_key.clone(),
        invitation_secret: "secret-driver-join-reconcile".to_string(),
        communication_channels: vec![ClusterInvitationChannel {
            endpoint: endpoint.clone(),
            node_public_key: issuer_identity.public_key.clone(),
        }],
        introducers: Vec::new(),
        token_id: "token-driver-join-reconcile".to_string(),
        expires_at: now + time::Duration::hours(1),
        trust_domain: TrustDomain::new("trust.local").expect("trust"),
        allowed_member_roles: vec![ClusterMemberRole::Learner],
        issuer_node_id: issuer.clone(),
        issuer_public_key: issuer_identity.public_key.clone(),
        signature: String::new(),
    };
    invite.signature = sign_cluster_join_invite(&invite, &issuer_identity).expect("sign invite");
    sync_cluster_invitation_to_local_raft_unchecked(&paths, &invite).expect("sync invite");

    let mut pending = ClusterBootstrapState::pending_join(
        cluster_id.clone(),
        "driver join reconcile",
        joined.clone(),
        "joined",
        "pk-joined",
        now,
    );
    let mut accepted_state = issuer_state.clone();
    let mut joined_member =
        ClusterMemberRecord::local_voter(cluster_id, joined.clone(), "joined", "pk-joined", now);
    apply_cluster_raft_role(&mut joined_member, ClusterMemberRole::Learner, now);
    upsert_member_record(&mut accepted_state, joined_member);
    let mut driver = ClusterControlPlaneDriver::new(RecordingJoinReconciliationTransport {
        paths: paths.clone(),
        identity: issuer_identity,
        accepted_state,
        sent_routes: Vec::new(),
        connectivity: Vec::new(),
        snapshot_fetches: 0,
    });

    let reconciliation = reconcile_cluster_join_with_introducers_with_host(
        &mut pending,
        &invite,
        Duration::from_secs(2),
        Duration::from_secs(2),
        Some(&paths),
        &mut driver,
    )
    .expect("reconcile join through driver");

    let transport = driver.into_transport();
    assert_eq!(
        transport.sent_routes,
        vec![
            CLUSTER_JOIN_CHALLENGE_ROUTE.to_string(),
            CLUSTER_JOIN_REGISTER_ROUTE.to_string(),
        ]
    );
    assert_eq!(transport.snapshot_fetches, 0);
    assert_eq!(transport.connectivity, vec![endpoint.clone()]);
    assert_eq!(reconciliation.accepted_endpoint, Some(endpoint));
    assert!(
        !cluster_state_needs_join_registration(&pending),
        "driver-owned reconciliation should merge accepted state"
    );
}

#[test]
fn join_state_authority_targets_do_not_filter_offline_status_during_bootstrap() {
    install_kv_directory_for_tests();
    let root = sinomo_testdir::TestDir::new("sinomo-network-join-targets-ignore-offline-status");
    let data_dir = SinomoDataDir::new(&root);
    let paths = ClusterPaths::new(&data_dir);
    paths.ensure().expect("cluster paths");

    let now = OffsetDateTime::now_utc();
    let cluster_id =
        ClusterId::from_legacy_named("cluster_network_join_targets_bootstrap").expect("cluster");
    let local_node =
        NodeId::from_legacy_named("node_network_join_targets_bootstrap_local").expect("node");
    let voter_node =
        NodeId::from_legacy_named("node_network_join_targets_bootstrap_voter").expect("node");
    let mut state = ClusterBootstrapState::initialized_locally(
        cluster_id.clone(),
        "join targets bootstrap",
        local_node,
        "local",
        "pk-local",
        now,
    );
    let voter_endpoint = daemon_lan_endpoint(&voter_node, "node1:21353".to_string(), 0);
    let mut voter_member = ClusterMemberRecord::local_voter(
        cluster_id.clone(),
        voter_node.clone(),
        "voter",
        "pk-voter",
        now,
    );
    voter_member.capabilities = sinomo_node::main_daemon_capabilities(&voter_member.role);
    voter_member.allowed_capabilities = voter_member.capabilities.clone();
    voter_member.endpoints = vec![voter_endpoint.clone()];
    state.members.push(voter_member);

    write_cluster_state(&paths, &state).expect("write cluster state");
    sync_cluster_state_to_local_raft_unchecked(&paths, &state).expect("sync cluster state");
    sync_cluster_node_status_to_kv(
        &paths,
        ClusterNodeStatusRecord {
            cluster_id,
            node_id: voter_node,
            process: sinomo_node::DAEMON_MAIN_CLUSTER_ROLE.to_string(),
            availability: ClusterNodeAvailability::Offline,
            daemon_version: "0.1.0-test".to_string(),
            commit: None,
            target_os: Some("test-os".to_string()),
            target_arch: Some("test-arch".to_string()),
            hostname: None,
            pid: Some(42),
            address: Some("node1:21353".to_string()),
            bind_address: Some("0.0.0.0:21353".to_string()),
            executable: Some("sinomo".to_string()),
            rollout: None,
            daemon_started_at: Some("2026-05-04T00:00:00Z".to_string()),
            observed_at: now,
        },
    )
    .expect("sync offline node status");

    assert!(
        ClusterEndpointSelector::new(&paths, &state)
            .select_internal(
                ClusterEndpointInternalSelectionPurpose::LiveClusterStateAuthorityCommand
            )
            .is_empty(),
        "ordinary live-voter routing should honor explicit offline status"
    );
    assert_eq!(
        ClusterEndpointSelector::new(&paths, &state)
            .select_internal(ClusterEndpointInternalSelectionPurpose::VoterCommand)
            .first()
            .map(|endpoint| &endpoint.endpoint_id),
        Some(&voter_endpoint.endpoint_id),
        "join bootstrap must still try voter command targets even when local health is stale/offline"
    );
}

