#[test]
fn cluster_invitation_sync_batches_invite_and_state_in_one_revision() {
    let root = sinomo_testdir::TestDir::new("sinomo-network-invite-sync-batched");
    let data_dir = SinomoDataDir::new(&root);
    let paths = ClusterPaths::new(&data_dir);
    paths.ensure().expect("cluster paths");
    let now = OffsetDateTime::now_utc();
    let cluster_id = ClusterId::from_legacy_named("cluster_invite_sync_batched").expect("cluster");
    let node_id = NodeId::from_legacy_named("node_invite_sync_batched").expect("node");
    let state = ClusterBootstrapState::initialized_locally(
        cluster_id.clone(),
        "invite sync batched",
        node_id.clone(),
        "node",
        "public-key",
        now,
    );
    write_cluster_state(&paths, &state).expect("write state");
    let invite = ClusterJoinInvite {
        invite_id: ClusterInviteId::from_legacy_named("invite_sync_batched").expect("invite"),
        cluster_id,
        cluster_name: Some("invite sync batched".to_string()),
        cluster_public_key: "cluster-pk".to_string(),
        invitation_secret: "secret".to_string(),
        communication_channels: Vec::new(),
        introducers: Vec::new(),
        token_id: "token".to_string(),
        expires_at: now + time::Duration::hours(1),
        trust_domain: TrustDomain::new("trust.local").expect("trust domain"),
        allowed_member_roles: vec![ClusterMemberRole::Learner],
        issuer_node_id: node_id,
        issuer_public_key: "issuer-pk".to_string(),
        signature: String::new(),
    };

    let snapshot =
        sync_cluster_invitation_to_local_raft_unchecked(&paths, &invite).expect("sync invitation");

    assert_eq!(
        snapshot.revision,
        KvRevision(2),
        "the batched transaction still records both KV mutations"
    );
    let node =
        open_cluster_raft_kv_node(&paths, &state.local_node_id).expect("open raft after invite");
    assert_eq!(
        node.last_log_index(),
        1,
        "invite and state publication should use one raft log entry"
    );
    assert_eq!(
        node.hard_state().commit_index,
        1,
        "the single invitation publish entry should be committed"
    );
    let invite_entry = snapshot
        .get(&cluster_invitation_key(&invite.invite_id))
        .expect("invite entry");
    let state_entry = snapshot
        .get(&cluster_invitation_state_key(&invite.invite_id))
        .expect("invite state entry");
    assert_eq!(invite_entry.modify_revision, KvRevision(1));
    assert_eq!(state_entry.modify_revision, KvRevision(2));
    assert_eq!(
        invite_entry.decode::<ClusterJoinInvite>().expect("invite"),
        invite
    );
    let state = state_entry
        .decode::<ClusterInvitationStateRecord>()
        .expect("invite state");
    assert_eq!(state.invite_id, invite.invite_id);
    assert_eq!(state.state, "active");
}

#[derive(Default)]
struct RecordingClusterInvitePublishHost {
    commits: usize,
    last_txn: Option<KvTxn>,
    authoritative_snapshot: Option<KvSnapshot>,
    force_compare_failure: bool,
    compare_failures_remaining: usize,
}

impl ClusterInvitePublishHost for RecordingClusterInvitePublishHost {
    type Error = NetworkError;

    fn authoritative_cluster_kv_snapshot(
        &mut self,
        paths: &ClusterPaths,
        _state: &mut ClusterBootstrapState,
    ) -> Result<sinomo_kv::KvAuthoritativeRead<KvSnapshot>, Self::Error> {
        if let Some(snapshot) = self.authoritative_snapshot.clone() {
            return Ok(sinomo_kv::KvAuthoritativeRead {
                authority: test_current_quorum_authority(&snapshot),
                value: snapshot,
            });
        }
        test_authoritative_cluster_kv_snapshot(paths)
    }

    fn commit_cluster_kv_txn_with_quorum(
        &mut self,
        paths: &ClusterPaths,
        state: &mut ClusterBootstrapState,
        request: KvTxnRequest,
    ) -> Result<ClusterKvTxnCommitResult, Self::Error> {
        self.commits += 1;
        self.last_txn = Some(request.txn.clone());
        let request_id = request.request_id;
        if self.force_compare_failure || self.compare_failures_remaining > 0 {
            self.compare_failures_remaining = self.compare_failures_remaining.saturating_sub(1);
            let snapshot = read_cluster_kv_current_snapshot(paths)?;
            let revision = snapshot.revision;
            return Ok(test_cluster_kv_txn_commit_result_for_request(
                request_id,
                snapshot,
                Some(KvTxnResponse {
                    succeeded: false,
                    revision,
                    responses: Vec::new(),
                }),
            ));
        }
        let (snapshot, response) = append_cluster_raft_command_with_response(
            paths,
            &state.local_node_id,
            KvCommand::Txn(request.txn),
        )?;
        Ok(test_cluster_kv_txn_commit_result_for_request(
            request_id, snapshot, response,
        ))
    }
}

impl ClusterMemberMutationAsyncHost for RecordingClusterInvitePublishHost {
    fn prepare_cluster_state_for_kv_sync_async<'a>(
        &'a mut self,
        _paths: &'a ClusterPaths,
        _state: &'a mut ClusterBootstrapState,
    ) -> ClusterMembershipRpcFuture<'a, ()> {
        Box::pin(async { Ok(()) })
    }

    fn authoritative_cluster_kv_snapshot_async<'a>(
        &'a mut self,
        paths: &'a ClusterPaths,
        _state: &'a mut ClusterBootstrapState,
    ) -> ClusterMembershipRpcFuture<'a, sinomo_kv::KvAuthoritativeRead<KvSnapshot>> {
        Box::pin(async move {
            ClusterInvitePublishHost::authoritative_cluster_kv_snapshot(self, paths, _state)
        })
    }

    fn commit_cluster_kv_txn_with_quorum_async<'a>(
        &'a mut self,
        paths: &'a ClusterPaths,
        state: &'a mut ClusterBootstrapState,
        request: KvTxnRequest,
    ) -> ClusterMembershipRpcFuture<'a, ClusterKvTxnCommitResult> {
        Box::pin(async move {
            self.commits += 1;
            self.last_txn = Some(request.txn.clone());
            let request_id = request.request_id;
            if self.force_compare_failure || self.compare_failures_remaining > 0 {
                self.compare_failures_remaining = self.compare_failures_remaining.saturating_sub(1);
                let snapshot = read_cluster_kv_current_snapshot(paths)?;
                let revision = snapshot.revision;
                return Ok(test_cluster_kv_txn_commit_result_for_request(
                    request_id,
                    snapshot,
                    Some(KvTxnResponse {
                        succeeded: false,
                        revision,
                        responses: Vec::new(),
                    }),
                ));
            }
            let (snapshot, response) = append_cluster_raft_command_with_response(
                paths,
                &state.local_node_id,
                KvCommand::Txn(request.txn),
            )?;
            Ok(test_cluster_kv_txn_commit_result_for_request(
                request_id, snapshot, response,
            ))
        })
    }
}

#[test]
fn cluster_invite_publish_request_with_host_validates_and_delegates_commit() {
    let root = sinomo_testdir::TestDir::new("sinomo-network-invite-publish-request-host");
    let data_dir = SinomoDataDir::new(&root);
    let paths = ClusterPaths::new(&data_dir);
    paths.ensure().expect("cluster paths");
    let now = OffsetDateTime::now_utc();
    let cluster_id =
        ClusterId::from_legacy_named("cluster_invite_publish_request_host").expect("cluster");
    let issuer_node =
        NodeId::from_legacy_named("node_invite_publish_request_host_issuer").expect("issuer");
    let issuer_identity =
        sinomo_node::load_or_create_main_node_identity(&root).expect("issuer identity");
    let state = ClusterBootstrapState::initialized_locally(
        cluster_id.clone(),
        "invite publish request host",
        issuer_node.clone(),
        "issuer",
        issuer_identity.public_key.clone(),
        now,
    );
    write_cluster_state(&paths, &state).expect("write state");
    sync_cluster_state_to_local_raft_unchecked(&paths, &state).expect("sync state to kv");

    let mut invite = ClusterJoinInvite {
        invite_id: ClusterInviteId::from_legacy_named("invite_publish_request_host")
            .expect("invite"),
        cluster_id,
        cluster_name: Some("invite publish request host".to_string()),
        cluster_public_key: issuer_identity.public_key.clone(),
        invitation_secret: "secret-invite-publish-request-host".to_string(),
        communication_channels: Vec::new(),
        introducers: Vec::new(),
        token_id: "token-invite-publish-request-host".to_string(),
        expires_at: now + time::Duration::hours(1),
        trust_domain: TrustDomain::new("trust.local").expect("trust domain"),
        allowed_member_roles: vec![ClusterMemberRole::Learner],
        issuer_node_id: issuer_node.clone(),
        issuer_public_key: issuer_identity.public_key.clone(),
        signature: String::new(),
    };
    invite.signature = sign_cluster_join_invite(&invite, &issuer_identity).expect("sign invite");

    let mut host = RecordingClusterInvitePublishHost::default();
    let response = handle_cluster_invite_publish_request_with_host(
        &paths,
        ClusterInvitePublishRequest {
            invite: invite.clone(),
        },
        issuer_node.as_str(),
        &issuer_identity.public_key,
        now,
        &mut host,
    )
    .expect("invite publish response");

    assert!(response.accepted);
    assert_eq!(response.detail, "invite published");
    assert!(response.kv_snapshot.is_some());
    assert_eq!(host.commits, 1);
    let txn = host.last_txn.expect("committed txn");
    let invite_key = cluster_invitation_key(&invite.invite_id);
    assert!(
        txn.success
            .iter()
            .any(|op| matches!(op, KvOp::Put { key, .. } if key == &invite_key)),
        "network handler should plan invitation publication"
    );
    assert_eq!(
        read_cluster_invitation_from_kv(&paths, &invite.invite_id).expect("published invite"),
        invite
    );

    let mut retried_invite = invite.clone();
    retried_invite.invite_id =
        ClusterInviteId::from_legacy_named("invite_publish_request_host_retry").expect("invite");
    retried_invite.invitation_secret = "secret-invite-publish-request-host-retry".to_string();
    retried_invite.token_id = "token-invite-publish-request-host-retry".to_string();
    retried_invite.signature.clear();
    retried_invite.signature =
        sign_cluster_join_invite(&retried_invite, &issuer_identity).expect("sign retry invite");
    let mut retry_host = RecordingClusterInvitePublishHost {
        compare_failures_remaining: 1,
        ..Default::default()
    };
    let retry_snapshot = publish_cluster_invitation_to_quorum_with_host(
        &paths,
        &state,
        &retried_invite,
        &mut retry_host,
    )
    .expect("retry invite publication after one benign compare conflict");
    assert_eq!(retry_host.commits, 2);
    assert!(
        retry_snapshot
            .get(&cluster_invitation_key(&retried_invite.invite_id))
            .is_some()
    );

    let mut async_invite = invite.clone();
    async_invite.invite_id =
        ClusterInviteId::from_legacy_named("invite_publish_request_host_async").expect("invite");
    async_invite.invitation_secret = "secret-invite-publish-request-host-async".to_string();
    async_invite.token_id = "token-invite-publish-request-host-async".to_string();
    async_invite.signature = String::new();
    async_invite.signature =
        sign_cluster_join_invite(&async_invite, &issuer_identity).expect("sign async invite");
    let async_invite_key = cluster_invitation_key(&async_invite.invite_id);
    let runtime = tokio::runtime::Builder::new_current_thread()
        .enable_all()
        .build()
        .expect("runtime");
    let mut async_host = RecordingClusterInvitePublishHost::default();
    let async_response = runtime
        .block_on(handle_cluster_invite_publish_request_async_with_host(
            runtime.handle(),
            &paths,
            ClusterInvitePublishRequest {
                invite: async_invite.clone(),
            },
            issuer_node.as_str(),
            &issuer_identity.public_key,
            now,
            &mut async_host,
        ))
        .expect("async invite publish response");
    assert!(async_response.accepted);
    assert_eq!(async_response.detail, "invite published");
    assert!(async_response.kv_snapshot.is_some());
    assert_eq!(async_host.commits, 1);
    assert!(
        async_host
            .last_txn
            .expect("async committed txn")
            .success
            .iter()
            .any(|op| matches!(op, KvOp::Put { key, .. } if key == &async_invite_key)),
        "async network handler should plan invitation publication"
    );
    assert_eq!(
        read_cluster_invitation_from_kv(&paths, &async_invite.invite_id)
            .expect("async published invite"),
        async_invite
    );

    let mut unauthorized_host = RecordingClusterInvitePublishHost::default();
    let rejected = handle_cluster_invite_publish_request_with_host(
        &paths,
        ClusterInvitePublishRequest {
            invite: invite.clone(),
        },
        "node_invite_publish_request_host_other",
        &issuer_identity.public_key,
        now,
        &mut unauthorized_host,
    )
    .expect("unauthorized invite publish response");
    assert!(!rejected.accepted);
    assert_eq!(unauthorized_host.commits, 0);

    let mut stale_authorization_host = RecordingClusterInvitePublishHost {
        authoritative_snapshot: Some(
            InProcessKvStore::new()
                .snapshot()
                .expect("empty authoritative snapshot"),
        ),
        ..Default::default()
    };
    let stale_authorization = handle_cluster_invite_publish_request_with_host(
        &paths,
        ClusterInvitePublishRequest {
            invite: invite.clone(),
        },
        issuer_node.as_str(),
        &issuer_identity.public_key,
        now,
        &mut stale_authorization_host,
    )
    .expect("stale local issuer authorization response");
    assert!(!stale_authorization.accepted);
    assert!(
        stale_authorization
            .detail
            .contains("not an authorized cluster member")
    );
    assert_eq!(stale_authorization_host.commits, 0);

    let mut cas_failure_host = RecordingClusterInvitePublishHost {
        force_compare_failure: true,
        ..Default::default()
    };
    let cas_rejected = handle_cluster_invite_publish_request_with_host(
        &paths,
        ClusterInvitePublishRequest { invite },
        issuer_node.as_str(),
        &issuer_identity.public_key,
        now,
        &mut cas_failure_host,
    )
    .expect("CAS conflict response");
    assert!(!cas_rejected.accepted);
    assert_eq!(
        cas_rejected.detail,
        "cluster membership changed while publishing invitation"
    );
    assert_eq!(cas_failure_host.commits, 1);
}

#[test]
fn stable_cluster_invitation_sync_does_not_append_raft_log_entries() {
    let root = sinomo_testdir::TestDir::new("sinomo-network-invite-sync-noop");
    let data_dir = SinomoDataDir::new(&root);
    let paths = ClusterPaths::new(&data_dir);
    paths.ensure().expect("cluster paths");
    let now = OffsetDateTime::now_utc();
    let cluster_id = ClusterId::from_legacy_named("cluster_invite_sync_noop").expect("cluster");
    let node_id = NodeId::from_legacy_named("node_invite_sync_noop").expect("node");
    let state = ClusterBootstrapState::initialized_locally(
        cluster_id.clone(),
        "invite sync noop",
        node_id.clone(),
        "node",
        "public-key",
        now,
    );
    write_cluster_state(&paths, &state).expect("write state");
    let invite = ClusterJoinInvite {
        invite_id: ClusterInviteId::from_legacy_named("invite_sync_noop").expect("invite"),
        cluster_id,
        cluster_name: Some("invite sync noop".to_string()),
        cluster_public_key: "cluster-pk".to_string(),
        invitation_secret: "secret".to_string(),
        communication_channels: Vec::new(),
        introducers: Vec::new(),
        token_id: "token".to_string(),
        expires_at: now + time::Duration::hours(1),
        trust_domain: TrustDomain::new("trust.local").expect("trust domain"),
        allowed_member_roles: vec![ClusterMemberRole::Learner],
        issuer_node_id: node_id.clone(),
        issuer_public_key: "issuer-pk".to_string(),
        signature: String::new(),
    };

    let first =
        sync_cluster_invitation_to_local_raft_unchecked(&paths, &invite).expect("sync invitation");
    let wal_path = cluster_raft_wal_paths(&paths, &state.local_node_id).wal;
    let wal_len_after_first = std::fs::metadata(&wal_path)
        .expect("wal after first invite")
        .len();
    write_cluster_kv_snapshot(
        &paths,
        &InProcessKvStore::new().snapshot().expect("snapshot"),
    )
    .expect("overwrite stale materialized snapshot");

    thread::sleep(Duration::from_millis(5));
    let txn = cluster_invitation_publish_txn_from_kv(&paths, &invite).expect("invite txn");
    assert!(
        txn.success.is_empty(),
        "stable invite publish should ignore invitation-state updated_at"
    );
    let repeat = sync_cluster_invitation_to_local_raft_unchecked(&paths, &invite)
        .expect("repeat invitation");

    assert_eq!(repeat.revision, first.revision);
    assert_eq!(
        repeat
            .get(&cluster_invitation_key(&invite.invite_id))
            .expect("current invite entry")
            .decode::<ClusterJoinInvite>()
            .expect("invite"),
        invite,
        "stable no-op sync should return the current raft-backed snapshot, not a stale materialized snapshot"
    );
    assert_eq!(
        wal_len_after_first,
        std::fs::metadata(&wal_path)
            .expect("wal after stable repeat")
            .len(),
        "stable invite syncs should not append no-op raft entries"
    );
    let node =
        open_cluster_raft_kv_node(&paths, &state.local_node_id).expect("open raft after repeat");
    assert_eq!(
        node.last_log_index(),
        1,
        "repeat invite sync should not create another raft log entry"
    );
}

#[test]
fn stale_cluster_kv_cache_refreshes_materialized_cache_from_raft() {
    let root = sinomo_testdir::TestDir::new("sinomo-network-kv-stale-cache-refresh");
    let data_dir = SinomoDataDir::new(&root);
    let paths = ClusterPaths::new(&data_dir);
    paths.ensure().expect("cluster paths");
    let node_id = NodeId::from_legacy_named("node_stale_cache_refresh").expect("node");

    append_cluster_raft_command(
        &paths,
        &node_id,
        KvCommand::Op(KvOp::Put {
            key: "/current".to_string(),
            value: b"current".to_vec(),
            lease_id: None,
        }),
    )
    .expect("seed raft");
    let current = read_cluster_kv_snapshot(&paths).expect("current snapshot");

    let stale = InProcessKvStore::new().snapshot().expect("snapshot");
    write_cluster_kv_snapshot(&paths, &stale).expect("write stale cache");
    assert_eq!(
        read_cluster_kv_snapshot(&paths)
            .expect("stale cache")
            .revision,
        stale.revision
    );

    assert!(
        cache_cluster_kv_snapshot_if_newer_than_raft(&paths, &node_id, stale)
            .expect("reconcile stale materialized cache")
    );
    let refreshed = read_cluster_kv_snapshot(&paths).expect("refreshed cache");
    assert_eq!(refreshed.revision, current.revision);
    assert!(
        InProcessKvStore::restore(refreshed)
            .expect("restore")
            .get("/current")
            .is_some()
    );
}

#[test]
fn raft_append_request_omits_snapshot_for_up_to_date_compacted_follower() {
    let root = sinomo_testdir::TestDir::new("sinomo-network-raft-append-compacted");
    let data_dir = SinomoDataDir::new(&root);
    let paths = ClusterPaths::new(&data_dir);
    paths.ensure().expect("cluster paths");
    let cluster_id =
        ClusterId::from_legacy_named("cluster_raft_append_compacted").expect("cluster");
    let node_id = NodeId::from_legacy_named("node_raft_append_compacted").expect("node");
    let state = ClusterBootstrapState::initialized_locally(
        cluster_id,
        "raft append compacted",
        node_id.clone(),
        "raft node",
        "public-key",
        OffsetDateTime::now_utc(),
    );

    // Commit well beyond the retained-tail bound (256) so compaction keeps only a
    // recent tail and earlier entries are reachable solely via a snapshot.
    for index in 0..400 {
        append_cluster_raft_command(
            &paths,
            &node_id,
            KvCommand::Op(KvOp::Put {
                key: format!("/raft/compacted/{index:03}"),
                value: index.to_string().into_bytes(),
                lease_id: None,
            }),
        )
        .expect("append command");
    }
    let mut node = open_cluster_raft_kv_node(&paths, &node_id).expect("open raft node");
    node.save_snapshot().expect("compact raft node");
    assert!(node.snapshot_index() > 0);
    // The log is no longer truncated to empty: a bounded committed tail is kept for
    // incremental replication.
    let log = node.log();
    assert!(!log.is_empty(), "compaction should retain a log tail");
    assert!(log.len() <= 256, "retained tail must be bounded");
    let snapshot_index = node.snapshot_index();
    let earliest_retained = log.first().map(|entry| entry.index).expect("tail");
    let last_log_index = node.last_log_index();
    drop(node);

    // A caught-up follower (prev == snapshot index) gets a heartbeat, no snapshot.
    let heartbeat = paths
        .kv_paths()
        .build_raft_append_request_from_next_index(&state, last_log_index.saturating_add(1))
        .expect("build heartbeat");
    assert!(heartbeat.snapshot.is_none());
    assert!(heartbeat.append.entries.is_empty());
    assert_eq!(heartbeat.append.prev_log_index, snapshot_index);

    // A follower a few entries behind, but still within the retained tail, is caught
    // up with incremental entries — no snapshot install.
    let near = paths
        .kv_paths()
        .build_raft_append_request_from_next_index(&state, earliest_retained + 1)
        .expect("build near catchup");
    assert!(
        near.snapshot.is_none(),
        "follower within the retained tail must be served incrementally"
    );
    assert!(!near.append.entries.is_empty());

    // A follower behind the retained tail still requires a full snapshot install.
    let far = paths
        .kv_paths()
        .build_raft_append_request_from_next_index(
            &state,
            earliest_retained.saturating_sub(1).max(1),
        )
        .expect("build far catchup");
    assert!(
        far.snapshot.is_some(),
        "follower behind the retained tail must receive a snapshot"
    );
}

#[test]
fn connectivity_sort_prefers_unknown_private_tcp_over_unknown_iroh() {
    let root = sinomo_testdir::TestDir::new("sinomo-network-unknown-iroh-sort");
    let data_dir = SinomoDataDir::new(&root);
    let paths = ClusterPaths::new(&data_dir);
    paths.ensure().expect("paths");
    let now = OffsetDateTime::now_utc();
    let cluster_id = ClusterId::from_legacy_named("cluster_unknown_iroh_sort").expect("cluster");
    let node_a = NodeId::from_legacy_named("node_unknown_iroh_sort_a").expect("node a");
    let node_b = NodeId::from_legacy_named("node_unknown_iroh_sort_b").expect("node b");
    let mut state = ClusterBootstrapState::initialized_locally(
        cluster_id.clone(),
        "unknown iroh sort",
        node_a,
        "node a",
        "pk-a",
        now,
    );
    let private = daemon_lan_endpoint(&node_b, "10.0.0.41:21353".to_string(), 10);
    let iroh = ClusterEndpointRecord {
        endpoint_id: stable_iroh_endpoint_id(&node_b, "iroh_public_key_unknown_sort"),
        node_id: node_b.clone(),
        transport: ClusterTransportKind::Iroh,
        address: "iroh://iroh_public_key_unknown_sort?relay=https://relay.example./".to_string(),
        source: ClusterEndpointSource::Rendezvous,
        privacy: ClusterEndpointPrivacy::Relayed,
        priority: 90,
        last_observed_latency_ms: None,
    };
    let mut member_b = ClusterMemberRecord::local_voter(cluster_id, node_b, "node b", "pk-b", now);
    member_b.capabilities = main_daemon_capabilities(&member_b.role);
    member_b.allowed_capabilities = member_b.capabilities.clone();
    member_b.endpoints = vec![private.clone(), iroh.clone()];
    state.members.push(member_b);

    let targets = cluster_sync_targets_with_connectivity(&paths, &state);

    assert_eq!(
        targets.first().map(|endpoint| &endpoint.endpoint_id),
        Some(&private.endpoint_id)
    );
    assert!(
        targets
            .iter()
            .any(|endpoint| endpoint.endpoint_id == iroh.endpoint_id)
    );
}

