#[test]
fn member_daemon_status_targets_use_connectivity_before_static_transport_rank() {
    let root = sinomo_testdir::TestDir::new("sinomo-network-status-route-connectivity");
    let data_dir = SinomoDataDir::new(&root);
    let paths = ClusterPaths::new(&data_dir);
    paths.ensure().expect("paths");
    let now = OffsetDateTime::now_utc();
    let cluster_id =
        ClusterId::from_legacy_named("cluster_status_route_connectivity").expect("cluster");
    let local = NodeId::from_legacy_named("node_status_route_local").expect("local");
    let remote = NodeId::from_legacy_named("node_status_route_remote").expect("remote");
    let mut state = ClusterBootstrapState::initialized_locally(
        cluster_id.clone(),
        "status route connectivity",
        local.clone(),
        "local",
        "pk-local",
        now,
    );
    let lan = daemon_lan_endpoint(&remote, "10.0.0.41:21353".to_string(), 10);
    let public = ClusterEndpointRecord {
        endpoint_id: ClusterEndpointId::from_legacy_named("endpoint_status_route_public")
            .expect("endpoint"),
        node_id: remote.clone(),
        transport: ClusterTransportKind::LanTcp,
        address: "203.0.113.41:21353".to_string(),
        source: ClusterEndpointSource::Observed,
        privacy: ClusterEndpointPrivacy::InternetDirect,
        priority: 10,
        last_observed_latency_ms: None,
    };
    let iroh = ClusterEndpointRecord {
        endpoint_id: stable_iroh_endpoint_id(&remote, "iroh_public_key_status_route"),
        node_id: remote.clone(),
        transport: ClusterTransportKind::Iroh,
        address: "iroh://iroh_public_key_status_route?relay=https://relay.example./".to_string(),
        source: ClusterEndpointSource::Rendezvous,
        privacy: ClusterEndpointPrivacy::Relayed,
        priority: 90,
        last_observed_latency_ms: None,
    };
    let mut member =
        ClusterMemberRecord::local_voter(cluster_id, remote, "remote", "pk-remote", now);
    member.capabilities = main_daemon_capabilities(&member.role);
    member.allowed_capabilities = member.capabilities.clone();
    member.endpoints = vec![iroh.clone(), public.clone(), lan.clone()];
    state.members.push(member.clone());
    write_cluster_state(&paths, &state).expect("write state");
    sync_cluster_state_to_local_raft_unchecked(&paths, &state).expect("sync state");

    sync_cluster_connectivity_records_to_kv(
        &paths,
        &local,
        vec![
            cluster_connectivity_record(
                &state,
                &lan,
                ClusterConnectivityState::Degraded,
                Some(80),
                1,
                Some("slow".to_string()),
                None,
                now,
                60,
            ),
            cluster_connectivity_record(
                &state,
                &public,
                ClusterConnectivityState::Healthy,
                Some(20),
                0,
                Some("ok".to_string()),
                None,
                now,
                60,
            ),
            cluster_connectivity_record(
                &state,
                &iroh,
                ClusterConnectivityState::Healthy,
                Some(10),
                0,
                Some("ok".to_string()),
                None,
                now,
                60,
            ),
        ],
    )
    .expect("connectivity records");
    let selector = ClusterEndpointSelector::new(&paths, &state);
    let targets = selector
        .select(ClusterEndpointSelectionPurpose::MemberDaemonStatus)
        .into_iter()
        .filter(|endpoint| endpoint.node_id == member.node_id)
        .collect::<Vec<_>>();
    assert_eq!(
        targets
            .iter()
            .take(3)
            .map(|endpoint| endpoint.endpoint_id.clone())
            .collect::<Vec<_>>(),
        vec![
            public.endpoint_id.clone(),
            iroh.endpoint_id.clone(),
            lan.endpoint_id.clone(),
        ]
    );

    sync_cluster_connectivity_records_to_kv(
        &paths,
        &local,
        vec![
            cluster_connectivity_record(
                &state,
                &lan,
                ClusterConnectivityState::Unreachable,
                None,
                3,
                None,
                Some("failed".to_string()),
                now,
                60,
            ),
            cluster_connectivity_record(
                &state,
                &public,
                ClusterConnectivityState::Healthy,
                Some(20),
                0,
                Some("ok".to_string()),
                None,
                now,
                60,
            ),
            cluster_connectivity_record(
                &state,
                &iroh,
                ClusterConnectivityState::Healthy,
                Some(10),
                0,
                Some("ok".to_string()),
                None,
                now,
                60,
            ),
        ],
    )
    .expect("connectivity records");
    let targets = selector
        .select(ClusterEndpointSelectionPurpose::MemberDaemonStatus)
        .into_iter()
        .filter(|endpoint| endpoint.node_id == member.node_id)
        .collect::<Vec<_>>();
    assert_eq!(targets[0].endpoint_id, public.endpoint_id);
    assert_eq!(targets[1].endpoint_id, iroh.endpoint_id);

    sync_cluster_connectivity_records_to_kv(
        &paths,
        &local,
        vec![
            cluster_connectivity_record(
                &state,
                &lan,
                ClusterConnectivityState::Unreachable,
                None,
                3,
                None,
                Some("failed".to_string()),
                now,
                60,
            ),
            cluster_connectivity_record(
                &state,
                &public,
                ClusterConnectivityState::Unreachable,
                None,
                3,
                None,
                Some("failed".to_string()),
                now,
                60,
            ),
            cluster_connectivity_record(
                &state,
                &iroh,
                ClusterConnectivityState::Healthy,
                Some(10),
                0,
                Some("ok".to_string()),
                None,
                now,
                60,
            ),
        ],
    )
    .expect("connectivity records");
    let targets = selector
        .select(ClusterEndpointSelectionPurpose::MemberDaemonStatus)
        .into_iter()
        .filter(|endpoint| endpoint.node_id == member.node_id)
        .collect::<Vec<_>>();
    assert_eq!(targets[0].endpoint_id, iroh.endpoint_id);
}

#[test]
fn member_daemon_status_targets_filter_shadow_endpoints_before_ordering() {
    let root = sinomo_testdir::TestDir::new("sinomo-network-status-filters-shadow-first");
    let data_dir = SinomoDataDir::new(&root);
    let paths = ClusterPaths::new(&data_dir);
    paths.ensure().expect("paths");
    let now = OffsetDateTime::now_utc();
    let cluster_id =
        ClusterId::from_legacy_named("cluster_status_filters_shadow_first").expect("cluster");
    let local = NodeId::from_legacy_named("node_status_filters_shadow_local").expect("local");
    let remote = NodeId::from_legacy_named("node_status_filters_shadow_remote").expect("remote");
    let mut state = ClusterBootstrapState::initialized_locally(
        cluster_id.clone(),
        "status filters shadow first",
        local.clone(),
        "local",
        "pk-local",
        now,
    );
    let shadow = shadow_daemon_node_id(&remote);
    let mut stale_shadow_endpoints = (17..=31)
        .map(|octet| daemon_lan_endpoint(&shadow, format!("172.{octet}.0.1:21354"), 30))
        .map(|mut endpoint| {
            endpoint.node_id = remote.clone();
            endpoint
        })
        .collect::<Vec<_>>();
    let iroh = ClusterEndpointRecord {
        endpoint_id: stable_iroh_endpoint_id(&remote, "iroh_public_key_status_filters_shadow"),
        node_id: remote.clone(),
        transport: ClusterTransportKind::Iroh,
        address: "iroh://iroh_public_key_status_filters_shadow?relay=https://relay.example./"
            .to_string(),
        source: ClusterEndpointSource::Rendezvous,
        privacy: ClusterEndpointPrivacy::Relayed,
        priority: 90,
        last_observed_latency_ms: None,
    };
    let mut member =
        ClusterMemberRecord::local_voter(cluster_id, remote, "remote", "pk-remote", now);
    member.capabilities = main_daemon_capabilities(&member.role);
    member.allowed_capabilities = member.capabilities.clone();
    stale_shadow_endpoints.push(iroh.clone());
    member.endpoints = stale_shadow_endpoints;
    state.members.push(member.clone());
    write_cluster_state(&paths, &state).expect("write state");
    sync_cluster_state_to_local_raft_unchecked(&paths, &state).expect("sync state");

    let targets = ClusterEndpointSelector::new(&paths, &state)
        .select(ClusterEndpointSelectionPurpose::MemberDaemonStatus)
        .into_iter()
        .filter(|endpoint| endpoint.node_id == member.node_id)
        .collect::<Vec<_>>();

    assert_eq!(targets, vec![iroh]);
}

#[test]
fn member_daemon_status_targets_include_fresh_kv_iroh_endpoint() {
    install_kv_directory_for_tests();
    let root = sinomo_testdir::TestDir::new("sinomo-network-status-kv-iroh");
    let data_dir = SinomoDataDir::new(&root);
    let paths = ClusterPaths::new(&data_dir);
    paths.ensure().expect("paths");
    let now = OffsetDateTime::now_utc();
    let cluster_id = ClusterId::from_legacy_named("cluster_status_kv_iroh").expect("cluster");
    let local = NodeId::from_legacy_named("node_status_kv_iroh_local").expect("local");
    let remote = NodeId::from_legacy_named("node_status_kv_iroh_remote").expect("remote");
    let mut state = ClusterBootstrapState::initialized_locally(
        cluster_id.clone(),
        "status kv iroh",
        local.clone(),
        "local",
        "pk-local",
        now,
    );
    let stale_lan = daemon_lan_endpoint(&remote, "10.14.1.11:21353".to_string(), 10);
    let stale_bridge = daemon_lan_endpoint(&remote, "172.17.0.1:21353".to_string(), 20);
    let fresh_iroh = ClusterEndpointRecord {
        endpoint_id: stable_iroh_endpoint_id(&remote, "iroh_public_key_status_kv_iroh"),
        node_id: remote.clone(),
        transport: ClusterTransportKind::Iroh,
        address: "iroh://iroh_public_key_status_kv_iroh?relay=https://relay.example./".to_string(),
        source: ClusterEndpointSource::Rendezvous,
        privacy: ClusterEndpointPrivacy::Relayed,
        priority: 90,
        last_observed_latency_ms: None,
    };
    let mut member =
        ClusterMemberRecord::local_voter(cluster_id, remote.clone(), "remote", "pk-remote", now);
    member.capabilities = main_daemon_capabilities(&member.role);
    member.allowed_capabilities = member.capabilities.clone();
    member.endpoints = vec![stale_lan.clone(), stale_bridge.clone()];
    state.members.push(member.clone());
    write_cluster_state(&paths, &state).expect("write state");
    sync_cluster_state_to_local_raft_unchecked(&paths, &state).expect("sync state");
    append_cluster_raft_command(
        &paths,
        &local,
        KvCommand::Op(
            KvOp::put_serde(
                cluster_endpoint_key(&remote, &fresh_iroh),
                &fresh_iroh,
                None,
            )
            .expect("fresh iroh endpoint op"),
        ),
    )
    .expect("publish fresh iroh endpoint");

    sync_cluster_connectivity_records_to_kv(
        &paths,
        &local,
        vec![
            cluster_connectivity_record(
                &state,
                &stale_lan,
                ClusterConnectivityState::Unreachable,
                None,
                3,
                None,
                Some("timed out".to_string()),
                now,
                60,
            ),
            cluster_connectivity_record(
                &state,
                &stale_bridge,
                ClusterConnectivityState::Unreachable,
                None,
                3,
                None,
                Some("timed out".to_string()),
                now,
                60,
            ),
            cluster_connectivity_record(
                &state,
                &fresh_iroh,
                ClusterConnectivityState::Healthy,
                Some(25),
                0,
                Some("ok".to_string()),
                None,
                now,
                60,
            ),
        ],
    )
    .expect("connectivity records");

    let targets = ClusterEndpointSelector::new(&paths, &state)
        .select(ClusterEndpointSelectionPurpose::MemberDaemonStatus)
        .into_iter()
        .filter(|endpoint| endpoint.node_id == member.node_id)
        .collect::<Vec<_>>();

    assert_eq!(targets[0].endpoint_id, fresh_iroh.endpoint_id);
    assert!(
        targets
            .iter()
            .any(|endpoint| endpoint.endpoint_id == stale_lan.endpoint_id),
        "stale LAN endpoints should remain as fallbacks after the healthy KV Iroh endpoint"
    );
}

