#[test]
fn cluster_state_sync_txn_is_empty_when_kv_already_matches() {
    let root = sinomo_testdir::TestDir::new("sinomo-network-sync-idempotent");
    let data_dir = SinomoDataDir::new(&root);
    let paths = ClusterPaths::new(&data_dir);
    paths.ensure().expect("cluster paths");

    let now = OffsetDateTime::now_utc();
    let cluster_id = ClusterId::from_legacy_named("cluster_sync_idem").expect("cluster");
    let node_id = NodeId::from_legacy_named("node_sync_idem").expect("node");
    let mut state = ClusterBootstrapState::initialized_locally(
        cluster_id.clone(),
        "sync idem",
        node_id.clone(),
        "node",
        "pk",
        now,
    );
    let member = state
        .members
        .iter_mut()
        .find(|member| member.node_id == node_id)
        .expect("local member");
    member.capabilities = vec![CapabilityName::new("daemon.main.run").expect("capability")];
    member.allowed_capabilities = member.capabilities.clone();
    member.endpoints = vec![ClusterEndpointRecord {
        endpoint_id: ClusterEndpointId::from_legacy_named("endpoint_sync_idem").expect("endpoint"),
        node_id: node_id.clone(),
        transport: ClusterTransportKind::LanTcp,
        address: "127.0.0.1:21353".to_string(),
        source: ClusterEndpointSource::Static,
        privacy: ClusterEndpointPrivacy::Lan,
        priority: 0,
        last_observed_latency_ms: None,
    }];
    write_cluster_state(&paths, &state).expect("write state");

    // First sync against an empty KV emits the full state.
    let first = cluster_state_sync_txn(&paths, &state).expect("first sync txn");
    assert!(!first.success.is_empty(), "first sync should publish state");
    append_cluster_raft_command(&paths, &node_id, KvCommand::Txn(first)).expect("apply first sync");

    // Re-syncing identical state is a no-op even though the in-memory state's
    // updated_at would advance on a real publish.
    let mut bumped = state.clone();
    bumped.updated_at = now + time::Duration::seconds(120);
    bumped.kv_revision = state.kv_revision + 5;
    let second = cluster_state_sync_txn(&paths, &bumped).expect("second sync txn");
    assert!(
        second.success.is_empty(),
        "re-syncing semantically identical state must be a no-op, got ops: {:?}",
        second.success
    );

    // A real change (cluster display name -> identity record) must still publish.
    bumped.local_node_display_name = "renamed node".to_string();
    let third = cluster_state_sync_txn(&paths, &bumped).expect("third sync txn");
    assert!(
        !third.success.is_empty(),
        "a real config change must publish"
    );
}

#[test]
fn sync_cluster_state_to_kv_with_host_prepares_commits_and_skips_noop() {
    let root = sinomo_testdir::TestDir::new("sinomo-network-sync-host");
    let data_dir = SinomoDataDir::new(&root);
    let paths = ClusterPaths::new(&data_dir);
    paths.ensure().expect("cluster paths");

    let now = OffsetDateTime::now_utc();
    let cluster_id = ClusterId::from_legacy_named("cluster_sync_host").expect("cluster");
    let node_id = NodeId::from_legacy_named("node_sync_host").expect("node");
    let state = ClusterBootstrapState::initialized_locally(
        cluster_id,
        "sync host",
        node_id.clone(),
        "node",
        "pk",
        now,
    );
    write_cluster_state(&paths, &state).expect("write state");
    write_cluster_kv_snapshot(
        &paths,
        &InProcessKvStore::new().snapshot().expect("empty snapshot"),
    )
    .expect("seed empty snapshot");

    struct RecordingSyncHost {
        prepares: usize,
        commits: usize,
    }

    impl ClusterMemberMutationHost for RecordingSyncHost {
        fn prepare_cluster_state_for_kv_sync(
            &mut self,
            _paths: &ClusterPaths,
            state: &mut ClusterBootstrapState,
        ) -> Result<(), NetworkError> {
            self.prepares += 1;
            state.local_node_display_name = "prepared node".to_string();
            Ok(())
        }

        fn authoritative_cluster_kv_snapshot(
            &mut self,
            paths: &ClusterPaths,
            _state: &mut ClusterBootstrapState,
        ) -> Result<sinomo_kv::KvAuthoritativeRead<KvSnapshot>, NetworkError> {
            let snapshot = read_cluster_kv_snapshot(paths)?;
            Ok(sinomo_kv::KvAuthoritativeRead {
                authority: test_current_quorum_authority(&snapshot),
                value: snapshot,
            })
        }

        fn commit_cluster_kv_txn_with_quorum(
            &mut self,
            paths: &ClusterPaths,
            state: &mut ClusterBootstrapState,
            request: KvTxnRequest,
        ) -> Result<ClusterKvTxnCommitResult, NetworkError> {
            self.commits += 1;
            let request_id = request.request_id;
            let (snapshot, response) = append_cluster_raft_command_with_response(
                paths,
                &state.local_node_id,
                KvCommand::Txn(request.txn),
            )?;
            Ok(test_cluster_kv_txn_commit_result_for_request(
                request_id, snapshot, response,
            ))
        }
    }

    let mut host = RecordingSyncHost {
        prepares: 0,
        commits: 0,
    };
    let first = sync_cluster_state_to_kv_with_host(&paths, &state, &mut host).expect("first sync");
    assert_eq!(host.prepares, 1);
    assert_eq!(host.commits, 1);
    let identity: ClusterIdentityRecord = first
        .get(&cluster_identity_key())
        .expect("identity entry")
        .decode()
        .expect("identity");
    assert_eq!(identity.local_node_display_name, "prepared node");

    let second =
        sync_cluster_state_to_kv_with_host(&paths, &state, &mut host).expect("second sync");
    assert_eq!(host.prepares, 2);
    assert_eq!(
        host.commits, 1,
        "an authoritative matching state must not append an empty Raft transaction"
    );
    assert_eq!(second.revision, first.revision);
}

#[test]
fn cluster_state_sync_txn_diffs_member_endpoint_records() {
    let root = sinomo_testdir::TestDir::new("sinomo-network-cluster-sync-endpoint-diff");
    let data_dir = SinomoDataDir::new(&root);
    let paths = ClusterPaths::new(&data_dir);
    paths.ensure().expect("cluster paths");

    let now = OffsetDateTime::now_utc();
    let cluster_id = ClusterId::from_legacy_named("cluster_endpoint_diff").expect("cluster");
    let node_id = NodeId::from_legacy_named("node_endpoint_diff").expect("node");
    let mut state = ClusterBootstrapState::initialized_locally(
        cluster_id,
        "endpoint diff",
        node_id.clone(),
        "node",
        "pk",
        now,
    );
    let unchanged = ClusterEndpointRecord {
        endpoint_id: ClusterEndpointId::from_legacy_named("endpoint_diff_unchanged")
            .expect("endpoint"),
        node_id: node_id.clone(),
        transport: ClusterTransportKind::LanTcp,
        address: "127.0.0.1:21353".to_string(),
        source: ClusterEndpointSource::Static,
        privacy: ClusterEndpointPrivacy::Lan,
        priority: 0,
        last_observed_latency_ms: None,
    };
    let stale = ClusterEndpointRecord {
        endpoint_id: ClusterEndpointId::from_legacy_named("endpoint_diff_stale").expect("endpoint"),
        node_id: node_id.clone(),
        transport: ClusterTransportKind::LanTcp,
        address: "127.0.0.2:21353".to_string(),
        source: ClusterEndpointSource::Static,
        privacy: ClusterEndpointPrivacy::Lan,
        priority: 1,
        last_observed_latency_ms: None,
    };
    let added = ClusterEndpointRecord {
        endpoint_id: ClusterEndpointId::from_legacy_named("endpoint_diff_added").expect("endpoint"),
        node_id: node_id.clone(),
        transport: ClusterTransportKind::LanTcp,
        address: "127.0.0.3:21353".to_string(),
        source: ClusterEndpointSource::Static,
        privacy: ClusterEndpointPrivacy::Lan,
        priority: 2,
        last_observed_latency_ms: None,
    };
    state.members[0].endpoints = vec![unchanged.clone(), added.clone()];

    let unchanged_key = cluster_endpoint_key(&node_id, &unchanged);
    let stale_key = cluster_endpoint_key(&node_id, &stale);
    let added_key = cluster_endpoint_key(&node_id, &added);
    let mut store = InProcessKvStore::new();
    store
        .put_serde(unchanged_key.clone(), &unchanged, None)
        .expect("unchanged endpoint");
    store
        .put_serde(stale_key.clone(), &stale, None)
        .expect("stale endpoint");
    write_cluster_kv_snapshot(&paths, &store.snapshot().expect("snapshot"))
        .expect("seed endpoint snapshot");

    let txn = cluster_state_sync_txn(&paths, &state).expect("cluster state sync txn");
    assert!(
        txn.success.iter().all(|op| !matches!(
            op,
            KvOp::DeletePrefix { prefix } if prefix == &cluster_endpoint_prefix(&node_id)
        )),
        "endpoint sync should avoid broad prefix deletes"
    );
    assert!(
        txn.success
            .iter()
            .any(|op| matches!(op, KvOp::Delete { key } if key == &stale_key)),
        "stale endpoint should be deleted explicitly"
    );
    assert!(
        txn.success
            .iter()
            .any(|op| matches!(op, KvOp::Put { key, .. } if key == &added_key)),
        "missing endpoint should be put"
    );
    assert!(
        txn.success
            .iter()
            .all(|op| !matches!(op, KvOp::Put { key, .. } if key == &unchanged_key)),
        "unchanged endpoint should not be re-put"
    );
}

#[test]
fn merge_cluster_join_registration_preserves_locally_learned_remote_route_endpoints() {
    let now = OffsetDateTime::now_utc();
    let cluster_id =
        ClusterId::from_legacy_named("cluster_merge_preserve_routes").expect("cluster id");
    let local_node =
        NodeId::from_legacy_named("node_merge_preserve_routes_bridge").expect("local node");
    let voter_node =
        NodeId::from_legacy_named("node_merge_preserve_routes_voter").expect("voter node");

    let mut local = ClusterBootstrapState::initialized_locally(
        cluster_id.clone(),
        "merge preserve routes",
        local_node.clone(),
        "bridge",
        "pk-bridge",
        now,
    );
    let learned_voter_endpoint = daemon_lan_endpoint(&voter_node, "node1:21353".to_string(), 0);
    let mut local_voter = ClusterMemberRecord::local_voter(
        cluster_id.clone(),
        voter_node.clone(),
        "voter",
        "pk-voter",
        now,
    );
    local_voter.capabilities = vec![CapabilityName::new("daemon.main.run").expect("capability")];
    local_voter.allowed_capabilities = local_voter.capabilities.clone();
    local_voter.endpoints = vec![learned_voter_endpoint.clone()];
    local.members.push(local_voter);

    let mut accepted = ClusterBootstrapState::initialized_locally(
        cluster_id.clone(),
        "merge preserve routes",
        voter_node.clone(),
        "voter",
        "pk-voter",
        now + time::Duration::seconds(1),
    );
    accepted.members[0].capabilities =
        vec![CapabilityName::new("daemon.main.run").expect("capability")];
    accepted.members[0].allowed_capabilities = accepted.members[0].capabilities.clone();
    accepted.members[0].endpoints = vec![daemon_lan_endpoint(
        &voter_node,
        "10.0.0.10:21353".to_string(),
        20,
    )];
    let mut bridge_member = ClusterMemberRecord::local_non_voting(
        cluster_id,
        local_node.clone(),
        "bridge",
        "pk-bridge",
        now,
    );
    bridge_member.capabilities = vec![CapabilityName::new("daemon.main.run").expect("capability")];
    bridge_member.allowed_capabilities = bridge_member.capabilities.clone();
    accepted.members.push(bridge_member);

    merge_cluster_join_registration(&mut local, accepted);

    assert_eq!(local.local_node_id, local_node);
    let voter = local
        .members
        .iter()
        .find(|member| member.node_id == voter_node)
        .expect("voter member");
    assert!(
        voter.endpoints.iter().any(|endpoint| endpoint.endpoint_id
            == learned_voter_endpoint.endpoint_id
            && endpoint.address == "node1:21353"),
        "accepted voter state imports must preserve local join-channel routes"
    );
}

#[test]
fn cluster_state_sync_txn_deletes_replaced_member_identity_records() {
    let root = sinomo_testdir::TestDir::new("sinomo-network-cluster-sync-identity-replace");
    let data_dir = SinomoDataDir::new(&root);
    let paths = ClusterPaths::new(&data_dir);
    paths.ensure().expect("cluster paths");

    let now = OffsetDateTime::now_utc();
    let cluster_id = ClusterId::from_legacy_named("cluster_identity_replace").expect("cluster");
    let old_node = NodeId::from_legacy_named("node_identity_replace_old").expect("old node");
    let new_node = NodeId::from_legacy_named("node_identity_replace_new").expect("new node");
    let shared_public_key = "pk-identity-replace";
    let mut state = ClusterBootstrapState::initialized_locally(
        cluster_id.clone(),
        "identity replace",
        new_node.clone(),
        "new",
        shared_public_key,
        now,
    );
    state.members[0].capabilities =
        vec![CapabilityName::new("daemon.main.run").expect("capability")];
    state.members[0].allowed_capabilities = state.members[0].capabilities.clone();
    let new_endpoint = ClusterEndpointRecord {
        endpoint_id: ClusterEndpointId::from_legacy_named("endpoint_identity_replace_new")
            .expect("endpoint"),
        node_id: new_node.clone(),
        transport: ClusterTransportKind::LanTcp,
        address: "127.0.0.4:21353".to_string(),
        source: ClusterEndpointSource::Static,
        privacy: ClusterEndpointPrivacy::Lan,
        priority: 0,
        last_observed_latency_ms: None,
    };
    state.members[0].endpoints = vec![new_endpoint.clone()];

    let mut old_member = ClusterMemberRecord::local_voter(
        cluster_id,
        old_node.clone(),
        "old",
        shared_public_key,
        now,
    );
    old_member.capabilities = vec![CapabilityName::new("daemon.main.run").expect("capability")];
    old_member.allowed_capabilities = old_member.capabilities.clone();
    let old_endpoint = ClusterEndpointRecord {
        endpoint_id: ClusterEndpointId::from_legacy_named("endpoint_identity_replace_old")
            .expect("endpoint"),
        node_id: old_node.clone(),
        transport: ClusterTransportKind::LanTcp,
        address: "127.0.0.3:21353".to_string(),
        source: ClusterEndpointSource::Static,
        privacy: ClusterEndpointPrivacy::Lan,
        priority: 0,
        last_observed_latency_ms: None,
    };
    old_member.endpoints = vec![old_endpoint.clone()];

    let old_member_key = cluster_member_key(&old_node);
    let old_policy_key = cluster_capability_policy_key(&old_node);
    let old_endpoint_key = cluster_endpoint_key(&old_node, &old_endpoint);
    let new_member_key = cluster_member_key(&new_node);
    let mut store = InProcessKvStore::new();
    store
        .put_serde(old_member_key.clone(), &old_member, None)
        .expect("old member");
    store
        .put_serde(
            old_policy_key.clone(),
            &ClusterCapabilityPolicyRecord::from(&old_member),
            None,
        )
        .expect("old policy");
    store
        .put_serde(old_endpoint_key.clone(), &old_endpoint, None)
        .expect("old endpoint");
    write_cluster_kv_snapshot(&paths, &store.snapshot().expect("snapshot"))
        .expect("seed duplicate identity");

    let txn = cluster_state_sync_txn(&paths, &state).expect("cluster state sync txn");

    assert!(
        txn.success
            .iter()
            .any(|op| matches!(op, KvOp::Delete { key } if key == &old_member_key)),
        "old same-key member should be deleted"
    );
    assert!(
        txn.success
            .iter()
            .any(|op| matches!(op, KvOp::Delete { key } if key == &old_policy_key)),
        "old same-key policy should be deleted"
    );
    assert!(
        txn.success
            .iter()
            .any(|op| matches!(op, KvOp::Delete { key } if key == &old_endpoint_key)),
        "old same-key endpoint should be deleted"
    );
    assert!(
        txn.success
            .iter()
            .any(|op| matches!(op, KvOp::Put { key, .. } if key == &new_member_key)),
        "replacement member should be put"
    );
    assert!(
        txn.success.iter().all(|op| !matches!(
            op,
            KvOp::DeletePrefix { prefix } if prefix == &cluster_endpoint_prefix(&old_node)
        )),
        "identity replacement should avoid broad endpoint prefix deletes"
    );
}

fn endpoint_limit_fixture(node_id: &NodeId, label: &str, index: usize) -> ClusterEndpointRecord {
    ClusterEndpointRecord {
        endpoint_id: ClusterEndpointId::from_legacy_named(format!("endpoint_{label}_{index:05}"))
            .expect("endpoint"),
        node_id: node_id.clone(),
        transport: ClusterTransportKind::LanTcp,
        address: format!(
            "10.{}.{}.{}:21353",
            (index / 65_536) % 256,
            (index / 256) % 256,
            index % 256
        ),
        source: ClusterEndpointSource::Observed,
        privacy: ClusterEndpointPrivacy::Lan,
        priority: (index % (u16::MAX as usize)) as u16,
        last_observed_latency_ms: None,
    }
}

fn seed_member_endpoint_prefix_over_limit(
    store: &mut InProcessKvStore,
    node_id: &NodeId,
    label: &str,
) {
    for index in 0..=MAX_CLUSTER_MEMBER_ENDPOINT_RECORDS {
        let endpoint = endpoint_limit_fixture(node_id, label, index);
        store
            .put_serde(cluster_endpoint_key(node_id, &endpoint), &endpoint, None)
            .expect("seed endpoint");
    }
}

#[test]
fn read_cluster_members_from_kv_allows_large_aggregate_endpoint_sets() {
    let root = sinomo_testdir::TestDir::new("sinomo-network-member-endpoint-aggregate-limit");
    let data_dir = SinomoDataDir::new(&root);
    let paths = ClusterPaths::new(&data_dir);
    paths.ensure().expect("cluster paths");

    let now = OffsetDateTime::now_utc();
    let cluster_id =
        ClusterId::from_legacy_named("cluster_endpoint_aggregate_limit").expect("cluster");
    let member_count = 65;
    let endpoints_per_member = 64;
    let mut store = InProcessKvStore::new();
    for member_index in 0..member_count {
        let node_id =
            NodeId::from_legacy_named(format!("node_endpoint_aggregate_{member_index:03}"))
                .expect("node");
        let member = ClusterMemberRecord::local_voter(
            cluster_id.clone(),
            node_id.clone(),
            format!("endpoint aggregate {member_index}"),
            format!("pk-endpoint-aggregate-{member_index}"),
            now,
        );
        store
            .put_serde(cluster_member_key(&node_id), &member, None)
            .expect("seed member");
        for endpoint_index in 0..endpoints_per_member {
            let endpoint = endpoint_limit_fixture(
                &node_id,
                &format!("aggregate_{member_index:03}"),
                endpoint_index,
            );
            store
                .put_serde(cluster_endpoint_key(&node_id, &endpoint), &endpoint, None)
                .expect("seed endpoint");
        }
    }
    assert!(
        member_count * endpoints_per_member > CLUSTER_KV_RANGE_PREFIX_MAX_ENTRIES,
        "fixture should exceed the aggregate endpoint range cap"
    );
    write_cluster_kv_snapshot(&paths, &store.snapshot().expect("snapshot"))
        .expect("write snapshot");

    let members = read_cluster_members_from_kv(&paths).expect("read members");
    assert_eq!(members.len(), member_count);
    assert_eq!(
        members
            .iter()
            .map(|member| member.endpoints.len())
            .sum::<usize>(),
        member_count * endpoints_per_member
    );
    assert_default_range_limit(
        read_cluster_endpoints_from_kv(&paths).expect_err("aggregate endpoint range limit"),
        "/cluster/endpoints/",
    );
}

