#[derive(Default)]
struct RecordingClusterLocalMemberPublishHost {
    has_quorum: bool,
    commits: usize,
    sends: Vec<(NodeId, Vec<NodeId>, Duration)>,
    response: Option<ClusterMemberPublishResponse>,
    responses: Vec<ClusterMemberPublishResponse>,
}

impl ClusterLocalMemberPublishHost for RecordingClusterLocalMemberPublishHost {
    fn authoritative_cluster_kv_snapshot(
        &mut self,
        paths: &ClusterPaths,
        _state: &mut ClusterBootstrapState,
    ) -> Result<sinomo_kv::KvAuthoritativeRead<KvSnapshot>, NetworkError> {
        test_authoritative_cluster_kv_snapshot(paths)
    }

    fn cluster_has_local_quorum(
        &mut self,
        _paths: &ClusterPaths,
        _state: &ClusterBootstrapState,
    ) -> bool {
        self.has_quorum
    }

    fn commit_cluster_kv_txn_with_quorum(
        &mut self,
        paths: &ClusterPaths,
        _state: &mut ClusterBootstrapState,
        request: KvTxnRequest,
    ) -> Result<ClusterKvTxnCommitResult, NetworkError> {
        self.commits += 1;
        let request_id = request.request_id;
        let mut store = read_cluster_kv_store(paths)?;
        let response = store.txn(request.txn).map_err(kv_err)?;
        let snapshot = store.snapshot().expect("snapshot");
        write_cluster_kv_snapshot(paths, &snapshot)?;
        Ok(test_cluster_kv_txn_commit_result_for_request(
            request_id,
            snapshot,
            Some(response),
        ))
    }

    fn send_cluster_member_publish(
        &mut self,
        endpoint: &ClusterEndpointRecord,
        request: &ClusterMemberPublishRequest,
        timeout: Duration,
    ) -> Result<ClusterMemberPublishResponse, NetworkError> {
        self.sends.push((
            endpoint.node_id.clone(),
            request
                .members
                .iter()
                .map(|member| member.node_id.clone())
                .collect(),
            timeout,
        ));
        if self.responses.is_empty() {
            Ok(self
                .response
                .clone()
                .expect("recording host response must be set"))
        } else {
            Ok(self.responses.remove(0))
        }
    }
}

impl ClusterLocalMemberPublishAsyncHost for RecordingClusterLocalMemberPublishHost {
    fn authoritative_cluster_kv_snapshot_async<'a>(
        &'a mut self,
        paths: &'a ClusterPaths,
        state: &'a mut ClusterBootstrapState,
    ) -> ClusterMembershipRpcFuture<'a, sinomo_kv::KvAuthoritativeRead<KvSnapshot>> {
        Box::pin(async move {
            ClusterLocalMemberPublishHost::authoritative_cluster_kv_snapshot(self, paths, state)
        })
    }

    fn cluster_has_local_quorum_async<'a>(
        &'a mut self,
        _paths: &'a ClusterPaths,
        _state: &'a ClusterBootstrapState,
    ) -> ClusterMembershipRpcFuture<'a, bool> {
        Box::pin(async move { Ok(self.has_quorum) })
    }

    fn commit_cluster_kv_txn_with_quorum_async<'a>(
        &'a mut self,
        paths: &'a ClusterPaths,
        state: &'a mut ClusterBootstrapState,
        request: KvTxnRequest,
    ) -> ClusterMembershipRpcFuture<'a, ClusterKvTxnCommitResult> {
        Box::pin(async move {
            ClusterLocalMemberPublishHost::commit_cluster_kv_txn_with_quorum(
                self, paths, state, request,
            )
        })
    }

    fn send_cluster_member_publish_async<'a>(
        &'a mut self,
        endpoint: &'a ClusterEndpointRecord,
        request: &'a ClusterMemberPublishRequest,
        timeout: Duration,
    ) -> ClusterMembershipRpcFuture<'a, ClusterMemberPublishResponse> {
        Box::pin(async move {
            ClusterLocalMemberPublishHost::send_cluster_member_publish(
                self, endpoint, request, timeout,
            )
        })
    }
}

#[test]
fn cluster_member_publish_request_with_host_validates_and_delegates_commit() {
    let root = sinomo_testdir::TestDir::new("sinomo-network-member-publish-request-host");
    let data_dir = SinomoDataDir::new(&root);
    let paths = ClusterPaths::new(&data_dir);
    paths.ensure().expect("cluster paths");

    let now = OffsetDateTime::now_utc();
    let cluster_id =
        ClusterId::from_legacy_named("cluster_member_publish_request_host").expect("cluster");
    let local = NodeId::from_legacy_named("node_member_publish_request_host_local").expect("local");
    let mut state = ClusterBootstrapState::initialized_locally(
        cluster_id,
        "member publish request host",
        local.clone(),
        "local",
        "pk-local",
        now,
    );
    state.members[0].capabilities = sinomo_node::main_daemon_capabilities(&state.members[0].role);
    state.members[0].allowed_capabilities = state.members[0].capabilities.clone();
    write_cluster_state(&paths, &state).expect("write state");
    sync_cluster_state_to_local_raft_unchecked(&paths, &state).expect("sync state to kv");

    let mut published = state.members[0].clone();
    let endpoint = daemon_lan_endpoint(&local, "10.47.0.7:21353".to_string(), 10);
    published.endpoints = vec![endpoint.clone()];
    let endpoint_key = cluster_endpoint_key(&local, &endpoint);

    let mut host = RecordingClusterMemberPublishHost::default();
    let response = handle_cluster_member_publish_request_with_host(
        &paths,
        ClusterMemberPublishRequest {
            members: vec![published],
            local_kv_revision: None,
        },
        local.as_str(),
        &mut host,
    )
    .expect("member publish response");

    assert!(response.accepted);
    assert_eq!(response.detail, "member endpoints published");
    assert!(response.kv_snapshot.is_some());
    assert_eq!(host.commits, 1);
    let txn = host.last_txn.expect("committed txn");
    assert!(
        txn.success
            .iter()
            .any(|op| matches!(op, KvOp::Put { key, .. } if key == &endpoint_key)),
        "network handler should plan endpoint publication"
    );
    assert!(
        read_cluster_kv_current_snapshot(&paths)
            .expect("snapshot after publish")
            .get(&endpoint_key)
            .is_some(),
        "host-applied commit should persist the endpoint"
    );

    let mut async_published = state.members[0].clone();
    let async_endpoint = daemon_lan_endpoint(&local, "10.47.0.8:21353".to_string(), 10);
    async_published.endpoints = vec![async_endpoint.clone()];
    let async_endpoint_key = cluster_endpoint_key(&local, &async_endpoint);
    let runtime = tokio::runtime::Builder::new_current_thread()
        .enable_all()
        .build()
        .expect("runtime");
    let mut async_host = RecordingClusterMemberPublishHost::default();
    let async_response = runtime
        .block_on(handle_cluster_member_publish_request_async_with_host(
            runtime.handle(),
            &paths,
            ClusterMemberPublishRequest {
                members: vec![async_published],
                local_kv_revision: None,
            },
            local.as_str(),
            &mut async_host,
        ))
        .expect("async member publish response");
    assert!(async_response.accepted);
    assert_eq!(async_response.detail, "member endpoints published");
    assert!(async_response.kv_snapshot.is_some());
    assert_eq!(async_host.commits, 1);
    assert!(
        async_host
            .last_txn
            .expect("async committed txn")
            .success
            .iter()
            .any(|op| matches!(op, KvOp::Put { key, .. } if key == &async_endpoint_key)),
        "async network handler should plan endpoint publication"
    );
    assert!(
        read_cluster_kv_current_snapshot(&paths)
            .expect("snapshot after async publish")
            .get(&async_endpoint_key)
            .is_some(),
        "async host-applied commit should persist the endpoint"
    );

    let mut unauthorized_host = RecordingClusterMemberPublishHost::default();
    let rejected = handle_cluster_member_publish_request_with_host(
        &paths,
        ClusterMemberPublishRequest {
            members: vec![state.members[0].clone()],
            local_kv_revision: None,
        },
        "node_member_publish_request_host_other",
        &mut unauthorized_host,
    )
    .expect("unauthorized member publish response");
    assert!(!rejected.accepted);
    assert_eq!(unauthorized_host.commits, 0);

    let mut stale_authorization_host = RecordingClusterMemberPublishHost {
        authoritative_snapshot: Some(
            InProcessKvStore::new()
                .snapshot()
                .expect("empty authoritative snapshot"),
        ),
        ..Default::default()
    };
    let stale_authorization = handle_cluster_member_publish_request_with_host(
        &paths,
        ClusterMemberPublishRequest {
            members: vec![state.members[0].clone()],
            local_kv_revision: None,
        },
        local.as_str(),
        &mut stale_authorization_host,
    )
    .expect("stale authorization response");
    assert!(!stale_authorization.accepted);
    assert!(
        stale_authorization
            .detail
            .contains("not an authorized cluster member")
    );
    assert_eq!(stale_authorization_host.commits, 0);

    let mut cas_failure_host = RecordingClusterMemberPublishHost {
        force_compare_failure: true,
        ..Default::default()
    };
    let cas_rejected = handle_cluster_member_publish_request_with_host(
        &paths,
        ClusterMemberPublishRequest {
            members: vec![state.members[0].clone()],
            local_kv_revision: None,
        },
        local.as_str(),
        &mut cas_failure_host,
    )
    .expect("CAS conflict response");
    assert!(!cas_rejected.accepted);
    assert_eq!(
        cas_rejected.detail,
        "cluster membership changed while publishing member state"
    );
    assert_eq!(cas_failure_host.commits, 1);
}

#[test]
fn cluster_membership_rpc_dispatch_decodes_and_encodes_member_publish() {
    let root = sinomo_testdir::TestDir::new("sinomo-network-membership-rpc-member-publish");
    let data_dir = SinomoDataDir::new(&root);
    let paths = ClusterPaths::new(&data_dir);
    paths.ensure().expect("cluster paths");

    let now = OffsetDateTime::now_utc();
    let cluster_id =
        ClusterId::from_legacy_named("cluster_membership_rpc_member_publish").expect("cluster");
    let local =
        NodeId::from_legacy_named("node_membership_rpc_member_publish_local").expect("local");
    let mut state = ClusterBootstrapState::initialized_locally(
        cluster_id,
        "membership rpc member publish",
        local.clone(),
        "local",
        "pk-local",
        now,
    );
    state.members[0].capabilities = sinomo_node::main_daemon_capabilities(&state.members[0].role);
    state.members[0].allowed_capabilities = state.members[0].capabilities.clone();
    write_cluster_state(&paths, &state).expect("write state");
    sync_cluster_state_to_local_raft_unchecked(&paths, &state).expect("sync state to kv");

    let mut published = state.members[0].clone();
    let endpoint = daemon_lan_endpoint(&local, "10.47.1.7:21353".to_string(), 10);
    published.endpoints = vec![endpoint.clone()];
    let endpoint_key = cluster_endpoint_key(&local, &endpoint);
    let request = ObjectRpcRequest::encode_body(
        CLUSTER_MEMBER_PUBLISH_ROUTE,
        CLUSTER_MEMBERSHIP_RPC_CATEGORY,
        &ClusterMemberPublishRequest {
            members: vec![published],
            local_kv_revision: None,
        },
    )
    .expect("member publish rpc");

    let mut join_host = UnusedClusterJoinRegistrationHost;
    let mut member_host = RecordingClusterMemberPublishHost::default();
    let mut invite_host = UnusedClusterInvitePublishHost;
    let response = handle_cluster_membership_rpc_request_with_hosts(
        &paths,
        request,
        local.as_str(),
        "pk-local",
        now,
        &mut join_host,
        &mut member_host,
        &mut invite_host,
    )
    .expect("membership rpc dispatch");
    assert_eq!(response.route, CLUSTER_MEMBER_PUBLISH_ROUTE);
    let response: ClusterMemberPublishResponse =
        response.decode_body().expect("member publish response");
    assert!(response.accepted);
    assert_eq!(response.detail, "member endpoints published");
    assert_eq!(member_host.commits, 1);
    assert!(
        read_cluster_kv_current_snapshot(&paths)
            .expect("snapshot after publish")
            .get(&endpoint_key)
            .is_some(),
        "network membership RPC dispatch should commit endpoint publication through the host"
    );
}

#[test]
fn local_member_publish_with_host_skips_noop_commit_when_local_voter_has_quorum() {
    let root = sinomo_testdir::TestDir::new("sinomo-network-local-member-publish-commit");
    let data_dir = SinomoDataDir::new(&root);
    let paths = ClusterPaths::new(&data_dir);
    paths.ensure().expect("cluster paths");
    let now = OffsetDateTime::now_utc();
    let cluster_id =
        ClusterId::from_legacy_named("cluster_local_member_publish_commit").expect("cluster");
    let local = NodeId::from_legacy_named("node_local_member_publish_commit").expect("local");
    let mut state = ClusterBootstrapState::initialized_locally(
        cluster_id,
        "local member publish commit",
        local.clone(),
        "local",
        "pk-local",
        now,
    );
    state.members[0].capabilities = sinomo_node::main_daemon_capabilities(&state.members[0].role);
    state.members[0].allowed_capabilities = state.members[0].capabilities.clone();
    write_cluster_state(&paths, &state).expect("write state");
    sync_cluster_state_to_local_raft_unchecked(&paths, &state)
        .expect("seed authoritative membership");

    let mut host = RecordingClusterLocalMemberPublishHost {
        has_quorum: true,
        ..Default::default()
    };
    let snapshot = publish_local_members_to_quorum_if_needed_with_host(
        &paths,
        &state,
        ClusterLocalMemberPublishOptions {
            member_publish_timeout: Duration::from_secs(1),
            force_kv_snapshot_sync: false,
        },
        &mut host,
    )
    .expect("local member publish");

    assert_eq!(host.commits, 0);
    assert!(host.sends.is_empty());
    assert!(snapshot.is_none(), "stable source publication is terminal");
    let stable = publish_local_members_to_quorum_if_needed_with_host(
        &paths,
        &state,
        ClusterLocalMemberPublishOptions {
            member_publish_timeout: Duration::from_secs(1),
            force_kv_snapshot_sync: false,
        },
        &mut host,
    )
    .expect("stable local member publish");
    assert_eq!(
        host.commits, 0,
        "stable publication must not acquire an authoritative barrier"
    );
    assert!(stable.is_none());
}

