#[test]
fn async_cluster_raft_append_replication_retries_from_rejected_match_index() {
    struct ScriptedAsyncRaftAppendHost {
        last_index: u64,
        next_indexes: Vec<u64>,
        snapshot_flags: Vec<bool>,
        timeouts: Vec<Duration>,
        sent: usize,
        responses: std::collections::VecDeque<ClusterRaftAppendResponse>,
    }

    impl ClusterRaftAppendReplicationAsyncHost for ScriptedAsyncRaftAppendHost {
        fn last_local_raft_log_index_async<'a>(
            &'a mut self,
            _paths: &'a ClusterPaths,
            _state: &'a ClusterBootstrapState,
        ) -> ClusterMembershipRpcFuture<'a, u64> {
            let last_index = self.last_index;
            Box::pin(async move { Ok(last_index) })
        }

        fn build_raft_append_request_async<'a>(
            &'a mut self,
            _paths: &'a ClusterPaths,
            state: &'a ClusterBootstrapState,
            next_index: u64,
        ) -> ClusterMembershipRpcFuture<'a, ClusterRaftAppendRequest> {
            self.next_indexes.push(next_index);
            let state = state.clone();
            let leader_id = state.local_node_id.clone();
            let snapshot = (next_index == 1).then(|| RaftSnapshot {
                last_included_index: 0,
                last_included_term: 0,
                kv: (InProcessKvStore::new()
                    .snapshot()
                    .expect("catch-up snapshot"))
                .into(),
            });
            Box::pin(async move {
                Ok(ClusterRaftAppendRequest {
                    state,
                    snapshot,
                    read_index_probe: false,
                    append: RaftAppendEntriesRequest {
                        term: 1,
                        leader_id,
                        prev_log_index: next_index.saturating_sub(1),
                        prev_log_term: 1,
                        entries: Vec::new(),
                        leader_commit: next_index.saturating_sub(1),
                    },
                })
            })
        }

        fn send_raft_append_async<'a>(
            &'a mut self,
            _endpoint: &'a ClusterEndpointRecord,
            request: &'a ClusterRaftAppendRequest,
            timeout: Duration,
        ) -> ClusterMembershipRpcFuture<'a, ClusterRaftAppendResponse> {
            self.snapshot_flags.push(request.snapshot.is_some());
            self.timeouts.push(timeout);
            let response = self.responses.pop_front().expect("scripted response");
            Box::pin(async move { Ok(response) })
        }

        fn on_raft_append_sent_async<'a>(&'a mut self) -> ClusterMembershipRpcFuture<'a, ()> {
            self.sent += 1;
            Box::pin(async { Ok(()) })
        }
    }

    fn response(
        state: &ClusterBootstrapState,
        accepted: bool,
        match_index: u64,
    ) -> ClusterRaftAppendResponse {
        ClusterRaftAppendResponse {
            accepted,
            detail: if accepted { "accepted" } else { "rejected" }.to_string(),
            state: state.clone(),
            append: RaftAppendEntriesResponse {
                term: 1,
                success: accepted,
                match_index,
            },
        }
    }

    let root = sinomo_testdir::TestDir::new("sinomo-network-async-raft-append-retry");
    let data_dir = SinomoDataDir::new(&root);
    let paths = ClusterPaths::new(&data_dir);
    paths.ensure().expect("cluster paths");
    let now = OffsetDateTime::now_utc();
    let cluster_id =
        ClusterId::from_legacy_named("cluster_async_raft_append_retry").expect("cluster");
    let local = NodeId::from_legacy_named("node_async_raft_append_retry_local").expect("local");
    let remote = NodeId::from_legacy_named("node_async_raft_append_retry_remote").expect("remote");
    let state = ClusterBootstrapState::initialized_locally(
        cluster_id,
        "async raft append retry",
        local,
        "local",
        "pk-local",
        now,
    );
    let endpoint = daemon_lan_endpoint(&remote, "10.70.0.2:21353".to_string(), 10);
    let mut host = ScriptedAsyncRaftAppendHost {
        last_index: 5,
        next_indexes: Vec::new(),
        snapshot_flags: Vec::new(),
        timeouts: Vec::new(),
        sent: 0,
        responses: Vec::from([response(&state, false, 2), response(&state, true, 3)]).into(),
    };
    let runtime = tokio::runtime::Builder::new_current_thread()
        .enable_all()
        .build()
        .expect("runtime");
    let outcome = runtime
        .block_on(replicate_cluster_raft_to_endpoint_async_with_host(
            &paths,
            &state,
            &endpoint,
            &[],
            ClusterControlPlaneTimeouts {
                max_raft_append_attempts: 3,
                tcp_command_timeout: Duration::from_secs(1),
                iroh_command_timeout: Duration::from_secs(1),
                tcp_foreground_attempt_timeout: Duration::from_secs(1),
                public_foreground_attempt_timeout: Duration::from_secs(1),
                iroh_foreground_attempt_timeout: Duration::from_secs(1),
                raft_append_timeout: Duration::from_secs(5),
                rpc_timeout: Duration::from_secs(5),
                membership_rpc_timeout: Duration::from_secs(5),
                raft_campaign_jitter_max: Duration::ZERO,
            },
            Duration::from_secs(5),
            &mut host,
        ))
        .expect("async replicate");

    assert!(outcome.response.accepted);
    assert_eq!(host.next_indexes, vec![6, 3]);
    assert_eq!(host.snapshot_flags, vec![false, false]);
    assert_eq!(host.sent, 2);
    assert_eq!(host.timeouts.len(), 2);

    let mut committed_conflict_host = ScriptedAsyncRaftAppendHost {
        last_index: 5,
        next_indexes: Vec::new(),
        snapshot_flags: Vec::new(),
        timeouts: Vec::new(),
        sent: 0,
        responses: Vec::from([
            response(&state, false, 4),
            response(&state, false, 4),
            response(&state, true, 5),
        ])
        .into(),
    };
    let outcome = runtime
        .block_on(replicate_cluster_raft_to_endpoint_async_with_host(
            &paths,
            &state,
            &endpoint,
            &[],
            ClusterControlPlaneTimeouts {
                max_raft_append_attempts: 3,
                tcp_command_timeout: Duration::from_secs(1),
                iroh_command_timeout: Duration::from_secs(1),
                tcp_foreground_attempt_timeout: Duration::from_secs(1),
                public_foreground_attempt_timeout: Duration::from_secs(1),
                iroh_foreground_attempt_timeout: Duration::from_secs(1),
                raft_append_timeout: Duration::from_secs(5),
                rpc_timeout: Duration::from_secs(5),
                membership_rpc_timeout: Duration::from_secs(5),
                raft_campaign_jitter_max: Duration::ZERO,
            },
            Duration::from_secs(5),
            &mut committed_conflict_host,
        ))
        .expect("async replicate through committed conflict");

    assert!(outcome.response.accepted);
    assert_eq!(committed_conflict_host.next_indexes, vec![6, 5, 1]);
    assert_eq!(
        committed_conflict_host.snapshot_flags,
        vec![false, false, true]
    );
    assert_eq!(committed_conflict_host.sent, 3);
    assert_eq!(committed_conflict_host.timeouts.len(), 3);
}

#[test]
fn async_cluster_raft_quorum_commit_uses_async_replication_and_fanout() {
    struct AcceptingAsyncQuorumHost {
        sent_appends: usize,
        connectivity_records: Vec<(NodeId, ClusterConnectivityState)>,
        fanout_targets: Vec<NodeId>,
    }

    impl ClusterRaftAppendReplicationAsyncHost for AcceptingAsyncQuorumHost {
        fn last_local_raft_log_index_async<'a>(
            &'a mut self,
            paths: &'a ClusterPaths,
            state: &'a ClusterBootstrapState,
        ) -> ClusterMembershipRpcFuture<'a, u64> {
            Box::pin(async move {
                paths
                    .kv_paths()
                    .locked_last_raft_log_index_async(&state.local_node_id)
                    .await
                    .map_err(kv_err)
            })
        }

        fn build_raft_append_request_async<'a>(
            &'a mut self,
            paths: &'a ClusterPaths,
            state: &'a ClusterBootstrapState,
            next_index: u64,
        ) -> ClusterMembershipRpcFuture<'a, ClusterRaftAppendRequest> {
            Box::pin(async move {
                paths
                    .kv_paths()
                    .locked_build_raft_append_request_from_next_index_async(state, next_index)
                    .await
                    .map_err(kv_err)
            })
        }

        fn send_raft_append_async<'a>(
            &'a mut self,
            _endpoint: &'a ClusterEndpointRecord,
            request: &'a ClusterRaftAppendRequest,
            _timeout: Duration,
        ) -> ClusterMembershipRpcFuture<'a, ClusterRaftAppendResponse> {
            self.sent_appends += 1;
            let state = request.state.clone();
            let match_index = request
                .append
                .entries
                .last()
                .map(|entry| entry.index)
                .unwrap_or(request.append.prev_log_index);
            Box::pin(async move {
                Ok(ClusterRaftAppendResponse {
                    accepted: true,
                    detail: "accepted".to_string(),
                    state,
                    append: RaftAppendEntriesResponse {
                        term: 1,
                        success: true,
                        match_index,
                    },
                })
            })
        }
    }

    impl ClusterRaftQuorumAsyncHost for AcceptingAsyncQuorumHost {
        fn send_raft_append_to_node_async<'a>(
            &'a mut self,
            _paths: &'a ClusterPaths,
            _state: &'a ClusterBootstrapState,
            _target_node_id: &'a NodeId,
            request: &'a ClusterRaftAppendRequest,
            _timeout: Duration,
        ) -> ClusterMembershipRpcFuture<'a, ClusterRaftAppendResponse> {
            self.sent_appends += 1;
            let state = request.state.clone();
            let match_index = request
                .append
                .entries
                .last()
                .map(|entry| entry.index)
                .unwrap_or(request.append.prev_log_index);
            Box::pin(async move {
                Ok(ClusterRaftAppendResponse {
                    accepted: true,
                    detail: "accepted".to_string(),
                    state,
                    append: RaftAppendEntriesResponse {
                        term: 1,
                        success: true,
                        match_index,
                    },
                })
            })
        }

        fn record_node_command_connectivity(
            &mut self,
            _paths: &ClusterPaths,
            _state: &ClusterBootstrapState,
            target_node_id: &NodeId,
            connectivity_state: ClusterConnectivityState,
            _latency_ms: Option<u64>,
        ) {
            self.connectivity_records
                .push((target_node_id.clone(), connectivity_state));
        }

        fn fan_out_committed_cluster_raft_command_async<'a>(
            &'a mut self,
            _paths: ClusterPaths,
            _state: ClusterBootstrapState,
            _events: std::sync::Arc<Vec<KvEvent>>,
            targets: Vec<NodeId>,
        ) -> ClusterMembershipRpcFuture<'a, ()> {
            Box::pin(async move {
                self.fanout_targets = targets;
                Ok(())
            })
        }
    }

    let root = sinomo_testdir::TestDir::new("sinomo-network-async-raft-quorum");
    let data_dir = SinomoDataDir::new(&root);
    let paths = ClusterPaths::new(&data_dir);
    paths.ensure().expect("cluster paths");
    let now = OffsetDateTime::now_utc();
    let cluster_id = ClusterId::from_legacy_named("cluster_async_raft_quorum").expect("cluster");
    let local = NodeId::from_legacy_named("node_async_raft_quorum_local").expect("local");
    let remote = NodeId::from_legacy_named("node_async_raft_quorum_remote").expect("remote");
    let mut state = ClusterBootstrapState::initialized_locally(
        cluster_id.clone(),
        "async raft quorum",
        local.clone(),
        "local",
        "pk-local",
        now,
    );
    state.members[0].capabilities =
        vec![CapabilityName::new(sinomo_node::DAEMON_MAIN_RUN_CAPABILITY).expect("capability")];
    state.members[0].allowed_capabilities = state.members[0].capabilities.clone();
    let mut remote_member =
        ClusterMemberRecord::local_voter(cluster_id, remote.clone(), "remote", "pk-remote", now);
    remote_member.capabilities =
        vec![CapabilityName::new(sinomo_node::DAEMON_MAIN_RUN_CAPABILITY).expect("capability")];
    remote_member.allowed_capabilities = remote_member.capabilities.clone();
    remote_member.endpoints = vec![daemon_lan_endpoint(
        &remote,
        "10.80.0.2:21353".to_string(),
        10,
    )];
    state.members.push(remote_member);
    write_cluster_state(&paths, &state).expect("write state");
    sync_cluster_state_to_local_raft_unchecked(&paths, &state).expect("sync state");
    locked_set_cluster_raft_leader(&paths, &local, 1).expect("set leader");

    let mut host = AcceptingAsyncQuorumHost {
        sent_appends: 0,
        connectivity_records: Vec::new(),
        fanout_targets: Vec::new(),
    };
    let runtime = tokio::runtime::Builder::new_current_thread()
        .enable_all()
        .build()
        .expect("runtime");
    let result = runtime
        .block_on(
            sinomo_cluster::commit_cluster_raft_command_with_quorum_async_with_host(
                runtime.handle(),
                &paths,
                &mut state,
                KvCommandRequest::generated(KvCommand::Op(KvOp::Put {
                    key: "/test/async-quorum".to_string(),
                    value: b"ok".to_vec(),
                    lease_id: None,
                })),
                ClusterKvRaftQuorumCommitOptions {
                    timeout: Duration::from_secs(5),
                },
                ClusterRaftAppendReplicationOptions {
                    timeout: Duration::from_secs(5),
                    max_attempts: 3,
                    tcp_command_timeout: Duration::from_secs(1),
                    iroh_command_timeout: Duration::from_secs(1),
                    tcp_foreground_attempt_timeout: Duration::from_secs(1),
                    public_foreground_attempt_timeout: Duration::from_secs(1),
                    iroh_foreground_attempt_timeout: Duration::from_secs(1),
                },
                &mut host,
            ),
        )
        .expect("async quorum commit");

    assert_eq!(
        result.snapshot.revision, result.authority.revision,
        "legacy full-view response must pair one snapshot generation with its authority proof"
    );
    assert_eq!(
        result
            .snapshot
            .get("/test/async-quorum")
            .expect("committed value")
            .value,
        b"ok".to_vec()
    );
    assert_eq!(host.sent_appends, 1);
    assert_eq!(
        host.connectivity_records,
        vec![(remote.clone(), ClusterConnectivityState::Healthy)]
    );
    assert!(host.fanout_targets.contains(&remote));
}

#[test]
fn async_cluster_raft_quorum_commit_races_voters_and_returns_at_quorum() {
    struct ConcurrentQuorumHost {
        delays: BTreeMap<NodeId, Duration>,
        higher_term_rejection: Option<(NodeId, u64)>,
        started: Arc<std::sync::atomic::AtomicUsize>,
        connectivity_records: Vec<(NodeId, ClusterConnectivityState)>,
    }

    impl ClusterRaftQuorumAsyncHost for ConcurrentQuorumHost {
        fn send_raft_append_to_node_async<'a>(
            &'a mut self,
            _paths: &'a ClusterPaths,
            _state: &'a ClusterBootstrapState,
            target_node_id: &'a NodeId,
            request: &'a ClusterRaftAppendRequest,
            _timeout: Duration,
        ) -> ClusterMembershipRpcFuture<'a, ClusterRaftAppendResponse> {
            let delay = self
                .delays
                .get(target_node_id)
                .copied()
                .unwrap_or(Duration::from_secs(2));
            let started = Arc::clone(&self.started);
            let request = request.clone();
            Box::pin(async move {
                started.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
                tokio::time::sleep(delay).await;
                Ok(ClusterRaftAppendResponse {
                    accepted: true,
                    detail: "accepted commit confirmation".to_string(),
                    state: request.state.clone(),
                    append: RaftAppendEntriesResponse {
                        term: request.append.term,
                        success: true,
                        match_index: request
                            .append
                            .entries
                            .last()
                            .map(|entry| entry.index)
                            .unwrap_or(request.append.prev_log_index),
                    },
                })
            })
        }

        fn send_raft_appends_to_quorum_async<'a>(
            &'a mut self,
            _paths: &'a ClusterPaths,
            _state: &'a ClusterBootstrapState,
            attempts: sinomo_cluster::ClusterRaftQuorumBatch,
            required_acks: usize,
        ) -> ClusterMembershipRpcFuture<'a, sinomo_cluster::ClusterRaftQuorumBatchOutcomes>
        {
            let delays = self.delays.clone();
            let higher_term_rejection = self.higher_term_rejection.clone();
            let started = Arc::clone(&self.started);
            Box::pin(async move {
                let mut tasks = tokio::task::JoinSet::new();
                for (target, request, _timeout) in attempts {
                    let delay = delays
                        .get(&target)
                        .copied()
                        .unwrap_or(Duration::from_secs(2));
                    let started = Arc::clone(&started);
                    let higher_term_rejection = higher_term_rejection.clone();
                    tasks.spawn(async move {
                        started.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
                        tokio::time::sleep(delay).await;
                        let match_index = request
                            .append
                            .entries
                            .last()
                            .map(|entry| entry.index)
                            .unwrap_or(request.append.prev_log_index);
                        let rejected_term =
                            higher_term_rejection
                                .as_ref()
                                .and_then(|(rejected_node_id, term)| {
                                    (rejected_node_id == &target).then_some(*term)
                                });
                        let response = ClusterRaftAppendResponse {
                            accepted: rejected_term.is_none(),
                            detail: if rejected_term.is_some() {
                                "higher term".to_string()
                            } else {
                                "accepted".to_string()
                            },
                            state: request.state.clone(),
                            append: RaftAppendEntriesResponse {
                                term: rejected_term.unwrap_or(request.append.term),
                                success: rejected_term.is_none(),
                                match_index,
                            },
                        };
                        (target, request, Ok(response))
                    });
                }
                let mut accepted = 0_usize;
                let mut outcomes = Vec::new();
                while let Some(joined) = tasks.join_next().await {
                    let outcome = joined.map_err(|source| NetworkError::Io {
                        operation: "join test quorum append".to_string(),
                        detail: source.to_string(),
                    })?;
                    if outcome.2.as_ref().is_ok_and(|response| response.accepted) {
                        accepted = accepted.saturating_add(1);
                    }
                    outcomes.push(outcome);
                    if accepted >= required_acks {
                        tasks.abort_all();
                        break;
                    }
                }
                Ok(outcomes)
            })
        }

        fn record_node_command_connectivity(
            &mut self,
            _paths: &ClusterPaths,
            _state: &ClusterBootstrapState,
            target_node_id: &NodeId,
            connectivity_state: ClusterConnectivityState,
            _latency_ms: Option<u64>,
        ) {
            self.connectivity_records
                .push((target_node_id.clone(), connectivity_state));
        }
    }

    let root = sinomo_testdir::TestDir::new("sinomo-network-concurrent-raft-quorum");
    let data_dir = SinomoDataDir::new(&root);
    let paths = ClusterPaths::new(&data_dir);
    paths.ensure().expect("cluster paths");
    let now = OffsetDateTime::now_utc();
    let cluster_id =
        ClusterId::from_legacy_named("cluster_concurrent_raft_quorum").expect("cluster");
    let local = NodeId::from_legacy_named("node_concurrent_raft_quorum_local").expect("local");
    let mut state = ClusterBootstrapState::initialized_locally(
        cluster_id.clone(),
        "concurrent raft quorum",
        local.clone(),
        "local",
        "pk-local",
        now,
    );
    state.members[0].capabilities =
        vec![CapabilityName::new(sinomo_node::DAEMON_MAIN_RUN_CAPABILITY).expect("capability")];
    state.members[0].allowed_capabilities = state.members[0].capabilities.clone();

    let mut remotes = Vec::new();
    for index in 0..4 {
        let remote =
            NodeId::from_legacy_named(format!("node_concurrent_raft_quorum_remote_{index}"))
                .expect("remote");
        let mut member = ClusterMemberRecord::local_voter(
            cluster_id.clone(),
            remote.clone(),
            format!("remote {index}"),
            format!("pk-remote-{index}"),
            now,
        );
        member.capabilities =
            vec![CapabilityName::new(sinomo_node::DAEMON_MAIN_RUN_CAPABILITY).expect("capability")];
        member.allowed_capabilities = member.capabilities.clone();
        member.endpoints = vec![daemon_lan_endpoint(
            &remote,
            format!("10.81.0.{}:21353", index + 2),
            10,
        )];
        state.members.push(member);
        remotes.push(remote);
    }
    write_cluster_state(&paths, &state).expect("write state");
    sync_cluster_state_to_local_raft_unchecked(&paths, &state).expect("sync state");
    locked_set_cluster_raft_leader(&paths, &local, 1).expect("set leader");

    let delays = remotes
        .iter()
        .cloned()
        .zip([
            Duration::from_millis(20),
            Duration::from_millis(40),
            Duration::from_secs(2),
            Duration::from_secs(2),
        ])
        .collect();
    let started = Arc::new(std::sync::atomic::AtomicUsize::new(0));
    let mut host = ConcurrentQuorumHost {
        delays,
        higher_term_rejection: None,
        started: Arc::clone(&started),
        connectivity_records: Vec::new(),
    };
    let runtime = tokio::runtime::Builder::new_current_thread()
        .enable_all()
        .build()
        .expect("runtime");
    let began = std::time::Instant::now();
    let result = runtime
        .block_on(
            sinomo_cluster::commit_cluster_raft_command_with_quorum_async_with_host(
                runtime.handle(),
                &paths,
                &mut state,
                KvCommandRequest::generated(KvCommand::Op(KvOp::Put {
                    key: "/test/concurrent-quorum".to_string(),
                    value: b"ok".to_vec(),
                    lease_id: None,
                })),
                ClusterKvRaftQuorumCommitOptions {
                    timeout: Duration::from_secs(3),
                },
                ClusterRaftAppendReplicationOptions {
                    timeout: Duration::from_secs(3),
                    max_attempts: 3,
                    tcp_command_timeout: Duration::from_secs(1),
                    iroh_command_timeout: Duration::from_secs(1),
                    tcp_foreground_attempt_timeout: Duration::from_secs(1),
                    public_foreground_attempt_timeout: Duration::from_secs(1),
                    iroh_foreground_attempt_timeout: Duration::from_secs(1),
                },
                &mut host,
            ),
        )
        .expect("concurrent quorum commit");

    assert!(
        began.elapsed() < Duration::from_secs(1),
        "quorum commit waited for a slow voter: {:?}",
        began.elapsed()
    );
    assert_eq!(
        started.load(std::sync::atomic::Ordering::Relaxed),
        remotes.len(),
        "all voter RPCs should start concurrently"
    );
    assert_eq!(host.connectivity_records.len(), 2);
    assert_eq!(
        result
            .snapshot
            .get("/test/concurrent-quorum")
            .expect("committed value")
            .value,
        b"ok".to_vec()
    );

    locked_set_cluster_raft_leader(&paths, &local, 2).expect("restore leader");
    state.term = 2;
    host.delays = remotes
        .iter()
        .cloned()
        .zip([
            Duration::from_millis(5),
            Duration::from_millis(10),
            Duration::from_secs(1),
            Duration::from_millis(15),
        ])
        .collect();
    host.connectivity_records.clear();
    started.store(0, std::sync::atomic::Ordering::Relaxed);
    // Model the voter that forwarded a write as the slow peer. Its identity is
    // intentionally absent from the Raft commit API: any majority may commit,
    // while forwarded-response materialization independently fetches an
    // authoritative snapshot when the forwarding voter's local view trails.
    let forwarding_voter = remotes[2].clone();
    let began = std::time::Instant::now();
    runtime
        .block_on(
            sinomo_cluster::commit_cluster_raft_command_with_quorum_async_with_host(
                runtime.handle(),
                &paths,
                &mut state,
                KvCommandRequest::generated(KvCommand::Op(KvOp::Put {
                    key: "/test/forwarding-voter-is-not-a-quorum-gate".to_string(),
                    value: b"ok".to_vec(),
                    lease_id: None,
                })),
                ClusterKvRaftQuorumCommitOptions {
                    timeout: Duration::from_secs(3),
                },
                ClusterRaftAppendReplicationOptions {
                    timeout: Duration::from_secs(3),
                    max_attempts: 3,
                    tcp_command_timeout: Duration::from_secs(1),
                    iroh_command_timeout: Duration::from_secs(1),
                    tcp_foreground_attempt_timeout: Duration::from_secs(1),
                    public_foreground_attempt_timeout: Duration::from_secs(1),
                    iroh_foreground_attempt_timeout: Duration::from_secs(1),
                },
                &mut host,
            ),
        )
        .expect("quorum commit without the forwarding voter");
    assert!(
        began.elapsed() < Duration::from_millis(500),
        "quorum commit waited for the slow forwarding voter: {:?}",
        began.elapsed()
    );
    assert!(
        !host
            .connectivity_records
            .iter()
            .any(|(node_id, state)| node_id == &forwarding_voter
                && state == &ClusterConnectivityState::Healthy),
        "slow forwarding voter unexpectedly gated the accepted quorum: {:?}",
        host.connectivity_records
    );
    assert_eq!(
        started.load(std::sync::atomic::Ordering::Relaxed),
        remotes.len(),
        "all voters should race once without a duplicate forwarding-voter append"
    );

    locked_set_cluster_raft_leader(&paths, &local, 3).expect("restore leader");
    state.term = 3;
    host.delays = remotes
        .iter()
        .cloned()
        .zip([
            Duration::from_millis(10),
            Duration::from_millis(20),
            Duration::from_millis(30),
            Duration::from_secs(2),
        ])
        .collect();
    host.higher_term_rejection = Some((remotes[0].clone(), 4));
    started.store(0, std::sync::atomic::Ordering::Relaxed);
    let error = runtime
        .block_on(
            sinomo_cluster::commit_cluster_raft_command_with_quorum_async_with_host(
                runtime.handle(),
                &paths,
                &mut state,
                KvCommandRequest::generated(KvCommand::Op(KvOp::Put {
                    key: "/test/concurrent-higher-term".to_string(),
                    value: b"must-not-commit".to_vec(),
                    lease_id: None,
                })),
                ClusterKvRaftQuorumCommitOptions {
                    timeout: Duration::from_secs(3),
                },
                ClusterRaftAppendReplicationOptions {
                    timeout: Duration::from_secs(3),
                    max_attempts: 3,
                    tcp_command_timeout: Duration::from_secs(1),
                    iroh_command_timeout: Duration::from_secs(1),
                    tcp_foreground_attempt_timeout: Duration::from_secs(1),
                    public_foreground_attempt_timeout: Duration::from_secs(1),
                    iroh_foreground_attempt_timeout: Duration::from_secs(1),
                },
                &mut host,
            ),
        )
        .expect_err("completed higher-term rejection must prevent commit");
    assert!(matches!(error, NetworkError::ClusterReadOnly { .. }));
    assert_eq!(
        started.load(std::sync::atomic::Ordering::Relaxed),
        remotes.len(),
        "all voter RPCs should still race before the higher term is observed"
    );
    assert!(
        read_cluster_kv_current_snapshot(&paths)
            .expect("snapshot after higher term")
            .get("/test/concurrent-higher-term")
            .is_none()
    );
    let node = open_cluster_raft_kv_node(&paths, &local).expect("raft after higher term");
    assert_eq!(node.hard_state().current_term, 4);
    assert_eq!(node.hard_state().leader_id, None);
}

#[test]
fn cluster_health_rows_with_probe_owns_liveness_and_peer_view_merge() {
    #[derive(Default)]
    struct StaticClusterStatusProbe {
        live: BTreeMap<NodeId, ClusterNodeStatusRecord>,
        peer_rows: BTreeMap<NodeId, Vec<ClusterHealthRow>>,
    }

    impl ClusterStatusProbe for StaticClusterStatusProbe {
        fn probe_member_status(
            &self,
            _state: &ClusterBootstrapState,
            member: &ClusterMemberRecord,
        ) -> Option<ClusterNodeStatusRecord> {
            self.live.get(&member.node_id).cloned()
        }

        fn peer_health_rows(
            &self,
            _state: &ClusterBootstrapState,
            member: &ClusterMemberRecord,
            _timeout: Duration,
        ) -> Option<Vec<ClusterHealthRow>> {
            self.peer_rows.get(&member.node_id).cloned()
        }
    }

    impl ClusterStatusAsyncProbe for StaticClusterStatusProbe {
        fn probe_member_status_async<'a>(
            &'a self,
            _state: &'a ClusterBootstrapState,
            member: &'a ClusterMemberRecord,
        ) -> ClusterMembershipRpcFuture<'a, Option<ClusterNodeStatusRecord>> {
            Box::pin(async move { Ok(self.live.get(&member.node_id).cloned()) })
        }

        fn peer_health_rows_async<'a>(
            &'a self,
            _state: &'a ClusterBootstrapState,
            member: &'a ClusterMemberRecord,
            _timeout: Duration,
        ) -> ClusterMembershipRpcFuture<'a, Option<Vec<ClusterHealthRow>>> {
            Box::pin(async move { Ok(self.peer_rows.get(&member.node_id).cloned()) })
        }
    }

    fn daemon_status_record(
        cluster_id: &ClusterId,
        node_id: &NodeId,
        availability: ClusterNodeAvailability,
        rollout: Option<ClusterNodeRolloutStatus>,
        observed_at: OffsetDateTime,
    ) -> ClusterNodeStatusRecord {
        ClusterNodeStatusRecord {
            cluster_id: cluster_id.clone(),
            node_id: node_id.clone(),
            process: sinomo_node::DAEMON_MAIN_CLUSTER_ROLE.to_string(),
            availability,
            daemon_version: "0.1.0-test".to_string(),
            commit: None,
            target_os: Some("test-os".to_string()),
            target_arch: Some("test-arch".to_string()),
            hostname: None,
            pid: Some(42),
            address: Some(format!("{}:21353", node_id.as_str())),
            bind_address: None,
            executable: Some("sinomo".to_string()),
            rollout,
            daemon_started_at: Some("2026-05-04T00:00:00Z".to_string()),
            observed_at,
        }
    }

    fn test_rollout_status() -> ClusterNodeRolloutStatus {
        ClusterNodeRolloutStatus {
            status: "healthy".to_string(),
            mode: None,
            detail: None,
            phase: None,
            progress_current: None,
            progress_total: None,
            progress_message: None,
            source: None,
            requested_at: None,
            staged_at: None,
            updated_at: Some("2026-05-04T00:00:00Z".to_string()),
            failed_at: None,
            diagnostics: None,
            stdout_log: None,
            stderr_log: None,
            stdout_tail: None,
            stderr_tail: None,
        }
    }

    let health_request = cluster_health_rpc_request().expect("health rpc request");
    assert_eq!(health_request.route, CLUSTER_HEALTH_ROUTE);
    assert_eq!(health_request.category, CLUSTER_HEALTH_RPC_CATEGORY);
    assert!(!cluster_health_rpc_request_is_local_scope(&health_request));
    let local_health_request =
        cluster_local_health_rpc_request().expect("local health rpc request");
    assert!(cluster_health_rpc_request_is_local_scope(
        &local_health_request
    ));
    let empty_health_response =
        ObjectRpcResponse::encode_body(CLUSTER_HEALTH_ROUTE, &Vec::<ClusterHealthRow>::new())
            .expect("health rpc response");
    assert!(
        decode_cluster_health_rpc_response(&empty_health_response)
            .expect("health rows")
            .is_empty()
    );

    let root = sinomo_testdir::TestDir::new("sinomo-network-cluster-health-probe");
    let data_dir = SinomoDataDir::new(&root);
    let paths = ClusterPaths::new(&data_dir);
    paths.ensure().expect("cluster paths");

    let now = OffsetDateTime::now_utc();
    let cluster_id = ClusterId::from_legacy_named("cluster_health_probe").expect("cluster");
    let local_node = NodeId::from_legacy_named("node_health_probe_local").expect("local");
    let bridge_node = NodeId::from_legacy_named("node_health_probe_bridge").expect("bridge");
    let target_node = NodeId::from_legacy_named("node_health_probe_target").expect("target");
    let unknown_node = NodeId::from_legacy_named("node_health_probe_unknown").expect("unknown");
    let mut state = ClusterBootstrapState::initialized_locally(
        cluster_id.clone(),
        "health probe",
        local_node.clone(),
        "local",
        "pk-local",
        now,
    );
    state.members[0].capabilities =
        vec![CapabilityName::new(sinomo_node::DAEMON_MAIN_RUN_CAPABILITY).expect("capability")];
    state.members[0].allowed_capabilities = state.members[0].capabilities.clone();

    let mut bridge = ClusterMemberRecord::local_voter(
        cluster_id.clone(),
        bridge_node.clone(),
        "bridge",
        "pk-bridge",
        now,
    );
    bridge.capabilities =
        vec![CapabilityName::new(sinomo_node::DAEMON_MAIN_RUN_CAPABILITY).expect("capability")];
    bridge.allowed_capabilities = bridge.capabilities.clone();
    bridge.endpoints = vec![daemon_lan_endpoint(
        &bridge_node,
        "10.60.0.2:21353".to_string(),
        10,
    )];

    let mut target = ClusterMemberRecord::local_voter(
        cluster_id.clone(),
        target_node.clone(),
        "target",
        "pk-target",
        now,
    );
    target.capabilities =
        vec![CapabilityName::new(sinomo_node::DAEMON_MAIN_RUN_CAPABILITY).expect("capability")];
    target.allowed_capabilities = target.capabilities.clone();
    target.endpoints = vec![daemon_lan_endpoint(
        &target_node,
        "10.60.0.3:21353".to_string(),
        10,
    )];

    let mut unknown = ClusterMemberRecord::local_voter(
        cluster_id.clone(),
        unknown_node.clone(),
        "unknown",
        "pk-unknown",
        now,
    );
    unknown.capabilities =
        vec![CapabilityName::new(sinomo_node::DAEMON_MAIN_RUN_CAPABILITY).expect("capability")];
    unknown.allowed_capabilities = unknown.capabilities.clone();

    state.members.push(bridge.clone());
    state.members.push(target.clone());
    state.members.push(unknown);
    write_cluster_state(&paths, &state).expect("write state");
    sync_cluster_state_to_local_raft_unchecked(&paths, &state).expect("sync state");

    let stored_rollout = test_rollout_status();
    sync_cluster_node_status_to_kv(
        &paths,
        daemon_status_record(
            &cluster_id,
            &local_node,
            ClusterNodeAvailability::Online,
            Some(stored_rollout.clone()),
            now,
        ),
    )
    .expect("sync stored local status");

    let mut probe = StaticClusterStatusProbe::default();
    probe.live.insert(
        local_node.clone(),
        daemon_status_record(
            &cluster_id,
            &local_node,
            ClusterNodeAvailability::Online,
            None,
            now,
        ),
    );
    probe.live.insert(
        bridge_node.clone(),
        daemon_status_record(
            &cluster_id,
            &bridge_node,
            ClusterNodeAvailability::Online,
            None,
            now,
        ),
    );
    probe.peer_rows.insert(
        bridge_node.clone(),
        vec![ClusterHealthRow {
            member: target.clone(),
            status: daemon_status_record(
                &cluster_id,
                &target_node,
                ClusterNodeAvailability::Online,
                None,
                now,
            ),
            availability: ClusterNodeAvailability::Online,
            live_probe_observed: true,
        }],
    );

    let local_rows =
        cluster_health_rows_with_probe(&paths, &state, &probe, false, now).expect("local rows");
    let local_response = handle_cluster_health_rpc_request(
        &paths,
        &state,
        &probe,
        cluster_local_health_rpc_request().expect("local health request"),
        now,
    )
    .expect("local health response");
    let local_response_rows =
        decode_cluster_health_rpc_response(&local_response).expect("local response rows");
    assert_eq!(
        local_response_rows
            .iter()
            .map(|row| row.member.node_id.clone())
            .collect::<Vec<_>>(),
        vec![local_node.clone()],
        "local-scope health RPC should not spend its budget probing remote members"
    );
    let local_row = local_rows
        .iter()
        .find(|row| row.member.node_id == local_node)
        .expect("local row");
    assert_eq!(local_row.availability, ClusterNodeAvailability::Online);
    assert_eq!(local_row.status.rollout, Some(stored_rollout));
    assert_eq!(
        local_rows
            .iter()
            .find(|row| row.member.node_id == target_node)
            .expect("target row")
            .availability,
        ClusterNodeAvailability::Unknown,
        "an unproven member without stored liveness or connectivity evidence remains unknown"
    );
    assert_eq!(
        local_rows
            .iter()
            .find(|row| row.member.node_id == unknown_node)
            .expect("unknown row")
            .availability,
        ClusterNodeAvailability::Unknown,
        "a member with no probeable endpoint remains unknown"
    );
    let no_peer_response = handle_cluster_health_rpc_request(
        &paths,
        &state,
        &probe,
        cluster_health_rpc_request_without_peer_views().expect("no-peer health request"),
        now,
    )
    .expect("no-peer health response");
    let no_peer_rows =
        decode_cluster_health_rpc_response(&no_peer_response).expect("no-peer response rows");
    assert_eq!(
        no_peer_rows
            .iter()
            .find(|row| row.member.node_id == target_node)
            .expect("no-peer target row")
            .availability,
        ClusterNodeAvailability::Unknown,
        "no-peer health requests must not spend the peer-view merge budget"
    );

    probe.live.insert(
        target_node.clone(),
        daemon_status_record(
            &cluster_id,
            &target_node,
            ClusterNodeAvailability::Online,
            None,
            now,
        ),
    );
    let non_recursive_live_response = handle_cluster_health_rpc_request(
        &paths,
        &state,
        &probe,
        cluster_health_rpc_request_without_recursive_peer_views()
            .expect("non-recursive live health request"),
        now,
    )
    .expect("non-recursive live health response");
    let non_recursive_live_rows = decode_cluster_health_rpc_response(&non_recursive_live_response)
        .expect("non-recursive live health rows");
    assert_eq!(
        non_recursive_live_rows
            .iter()
            .find(|row| row.member.node_id == target_node)
            .expect("non-recursive target row")
            .availability,
        ClusterNodeAvailability::Online,
        "a peer view must run live full-cluster probes without recursively expanding peer views"
    );
    probe.live.remove(&target_node);

    let merged_rows =
        cluster_health_rows_with_probe(&paths, &state, &probe, true, now).expect("merged rows");
    let merged_response = handle_cluster_health_rpc_request(
        &paths,
        &state,
        &probe,
        cluster_health_rpc_request().expect("health request"),
        now,
    )
    .expect("merged health response");
    let merged_response_rows =
        decode_cluster_health_rpc_response(&merged_response).expect("merged response rows");
    assert_eq!(merged_response_rows.len(), merged_rows.len());
    let current_state_response = handle_current_cluster_health_rpc_request(
        &paths,
        &probe,
        cluster_health_rpc_request().expect("current-state health request"),
        now,
    )
    .expect("current-state health response");
    let current_state_response_rows = decode_cluster_health_rpc_response(&current_state_response)
        .expect("current-state response rows");
    assert_eq!(
        current_state_response_rows.len(),
        merged_response_rows.len(),
        "current-state health helper should own reading cluster state before aggregation"
    );
    assert_eq!(
        current_state_response_rows
            .iter()
            .find(|row| row.member.node_id == target_node)
            .expect("current-state target row")
            .availability,
        ClusterNodeAvailability::Online
    );
    assert_eq!(
        merged_response_rows
            .iter()
            .find(|row| row.member.node_id == target_node)
            .expect("merged response target row")
            .availability,
        ClusterNodeAvailability::Online
    );
    assert_eq!(
        merged_rows
            .iter()
            .find(|row| row.member.node_id == target_node)
            .expect("target row")
            .availability,
        ClusterNodeAvailability::Online,
        "reachable peer-local health rows can prove another member online"
    );

    let runtime = tokio::runtime::Builder::new_current_thread()
        .enable_all()
        .build()
        .expect("runtime");
    let async_rows = runtime
        .block_on(cluster_health_rows_with_async_probe(
            &paths, &state, &probe, true, now,
        ))
        .expect("async merged rows");
    assert_eq!(async_rows.len(), merged_rows.len());
    assert_eq!(
        async_rows
            .iter()
            .find(|row| row.member.node_id == target_node)
            .expect("async target row")
            .availability,
        ClusterNodeAvailability::Online
    );
    let async_merged_response = runtime
        .block_on(handle_cluster_health_rpc_request_async(
            &paths,
            &state,
            &probe,
            cluster_health_rpc_request().expect("async health request"),
            now,
        ))
        .expect("async merged health response");
    let async_merged_response_rows = decode_cluster_health_rpc_response(&async_merged_response)
        .expect("async merged response rows");
    assert_eq!(async_merged_response_rows.len(), merged_response_rows.len());
    let async_current_state_response = runtime
        .block_on(handle_current_cluster_health_rpc_request_async(
            runtime.handle(),
            &paths,
            &probe,
            cluster_health_rpc_request().expect("async current-state health request"),
            now,
        ))
        .expect("async current-state health response");
    let async_current_state_rows =
        decode_cluster_health_rpc_response(&async_current_state_response)
            .expect("async current-state response rows");
    assert_eq!(
        async_current_state_rows.len(),
        current_state_response_rows.len()
    );
}

#[test]
fn cluster_health_rows_select_member_process_status() {
    #[derive(Default)]
    struct ProcessMismatchProbe {
        live: BTreeMap<NodeId, ClusterNodeStatusRecord>,
    }

    impl ClusterStatusProbe for ProcessMismatchProbe {
        fn probe_member_status(
            &self,
            _state: &ClusterBootstrapState,
            member: &ClusterMemberRecord,
        ) -> Option<ClusterNodeStatusRecord> {
            self.live.get(&member.node_id).cloned()
        }
    }

    impl ClusterStatusAsyncProbe for ProcessMismatchProbe {
        fn probe_member_status_async<'a>(
            &'a self,
            _state: &'a ClusterBootstrapState,
            member: &'a ClusterMemberRecord,
        ) -> ClusterMembershipRpcFuture<'a, Option<ClusterNodeStatusRecord>> {
            Box::pin(async move { Ok(self.live.get(&member.node_id).cloned()) })
        }
    }

    let root = sinomo_testdir::TestDir::new("sinomo-network-health-process-status");
    let data_dir = SinomoDataDir::new(&root);
    let paths = ClusterPaths::new(&data_dir);
    paths.ensure().expect("cluster paths");

    let now = OffsetDateTime::now_utc();
    let cluster_id =
        ClusterId::from_legacy_named("cluster_health_process_status").expect("cluster");
    let node_id = NodeId::from_legacy_named("node_health_process_status").expect("node");
    let mut state = ClusterBootstrapState::initialized_locally(
        cluster_id.clone(),
        "health process status",
        node_id.clone(),
        "node",
        "public-key",
        now,
    );
    state.members[0].capabilities =
        vec![CapabilityName::new(sinomo_node::DAEMON_MAIN_RUN_CAPABILITY).expect("capability")];
    state.members[0].allowed_capabilities = state.members[0].capabilities.clone();
    state.members[0].endpoints = vec![daemon_lan_endpoint(
        &node_id,
        "127.0.0.1:21353".to_string(),
        10,
    )];
    write_cluster_state(&paths, &state).expect("write state");
    sync_cluster_state_to_local_raft_unchecked(&paths, &state).expect("sync state");

    let shadow_status = ClusterNodeStatusRecord {
        cluster_id: cluster_id.clone(),
        node_id: node_id.clone(),
        process: sinomo_node::DAEMON_SHADOW_CLUSTER_ROLE.to_string(),
        availability: ClusterNodeAvailability::Online,
        daemon_version: "0.1.0-test".to_string(),
        commit: None,
        target_os: Some("test-os".to_string()),
        target_arch: Some("test-arch".to_string()),
        hostname: None,
        pid: Some(43),
        address: Some("127.0.0.1:21354".to_string()),
        bind_address: Some("0.0.0.0:21354".to_string()),
        executable: Some("sinomo".to_string()),
        rollout: None,
        daemon_started_at: Some("2026-06-17T00:00:00Z".to_string()),
        observed_at: now,
    };
    append_cluster_raft_command(
        &paths,
        &node_id,
        KvCommand::Op(
            KvOp::put_serde(cluster_node_status_key(&node_id), &shadow_status, None)
                .expect("legacy shadow status op"),
        ),
    )
    .expect("write legacy shadow status");

    let mut probe = ProcessMismatchProbe::default();
    probe.live.insert(node_id.clone(), shadow_status);

    let rows =
        cluster_health_rows_with_probe(&paths, &state, &probe, false, now).expect("health rows");
    let row = rows
        .iter()
        .find(|row| row.member.node_id == node_id)
        .expect("main member row");
    assert_eq!(
        row.status.process,
        sinomo_node::DAEMON_MAIN_CLUSTER_ROLE,
        "a shadow status must not occupy the main member row"
    );
    assert_eq!(
        row.availability,
        ClusterNodeAvailability::Unknown,
        "a shadow response should not make the main daemon appear online"
    );

    let runtime = tokio::runtime::Builder::new_current_thread()
        .enable_all()
        .build()
        .expect("runtime");
    let async_rows = runtime
        .block_on(cluster_health_rows_with_async_probe(
            &paths, &state, &probe, false, now,
        ))
        .expect("async health rows");
    let async_row = async_rows
        .iter()
        .find(|row| row.member.node_id == node_id)
        .expect("async main member row");
    assert_eq!(
        async_row.status.process,
        sinomo_node::DAEMON_MAIN_CLUSTER_ROLE
    );
    assert_eq!(async_row.availability, ClusterNodeAvailability::Unknown);
}

#[test]
fn cluster_live_health_does_not_treat_stored_online_as_liveness() {
    struct EmptyStatusProbe;

    impl ClusterStatusProbe for EmptyStatusProbe {
        fn probe_member_status(
            &self,
            _state: &ClusterBootstrapState,
            _member: &ClusterMemberRecord,
        ) -> Option<ClusterNodeStatusRecord> {
            None
        }
    }

    let root = sinomo_testdir::TestDir::new("sinomo-network-health-stored-online");
    let data_dir = SinomoDataDir::new(&root);
    let paths = ClusterPaths::new(&data_dir);
    paths.ensure().expect("cluster paths");

    let now = OffsetDateTime::now_utc();
    let cluster_id = ClusterId::from_legacy_named("cluster_health_stored_online").expect("cluster");
    let local_node = NodeId::from_legacy_named("node_health_stored_online_local").expect("local");
    let remote_node =
        NodeId::from_legacy_named("node_health_stored_online_remote").expect("remote");
    let mut state = ClusterBootstrapState::initialized_locally(
        cluster_id.clone(),
        "stored online health",
        local_node.clone(),
        "local",
        "pk-local",
        now,
    );
    state.members[0].capabilities =
        vec![CapabilityName::new(sinomo_node::DAEMON_MAIN_RUN_CAPABILITY).expect("capability")];
    state.members[0].allowed_capabilities = state.members[0].capabilities.clone();

    let mut remote = ClusterMemberRecord::local_non_voting(
        cluster_id.clone(),
        remote_node.clone(),
        "remote",
        "pk-remote",
        now,
    );
    remote.capabilities =
        vec![CapabilityName::new(sinomo_node::DAEMON_MAIN_RUN_CAPABILITY).expect("capability")];
    remote.allowed_capabilities = remote.capabilities.clone();
    remote.endpoints = vec![daemon_lan_endpoint(
        &remote_node,
        "10.61.0.2:21353".to_string(),
        10,
    )];
    state.members.push(remote.clone());
    write_cluster_state(&paths, &state).expect("write state");
    sync_cluster_state_to_local_raft_unchecked(&paths, &state).expect("sync state");

    let mut stored = unknown_cluster_node_status(&state, &remote, now);
    stored.availability = ClusterNodeAvailability::Online;
    stored.daemon_version = "0.1.0-test".to_string();
    sync_cluster_node_status_to_kv(&paths, stored).expect("sync stored status");

    let rows = cluster_health_rows_with_probe(&paths, &state, &EmptyStatusProbe, false, now)
        .expect("health rows");
    assert_eq!(
        rows.iter()
            .find(|row| row.member.node_id == remote_node)
            .expect("remote row")
            .availability,
        ClusterNodeAvailability::Unknown,
        "stored status supplies details but cannot prove current liveness"
    );

    let endpoint = remote.endpoints.first().expect("remote endpoint");
    let unreachable = ClusterConnectivityRecord {
        cluster_id: cluster_id.clone(),
        source_node_id: local_node.clone(),
        target_node_id: remote_node.clone(),
        endpoint_id: endpoint.endpoint_id.clone(),
        transport: endpoint.transport.clone(),
        address: endpoint.address.clone(),
        state: ClusterConnectivityState::Unreachable,
        latency_ms: None,
        consecutive_failures: 3,
        last_success_at: None,
        last_failure_at: Some("failed".to_string()),
        failure_reason: None,
        observed_at: now,
        expires_at: now + time::Duration::seconds(900),
    };
    sync_cluster_connectivity_records_to_kv(&paths, &local_node, vec![unreachable])
        .expect("sync unreachable connectivity");

    let rows = cluster_health_rows_with_probe(&paths, &state, &EmptyStatusProbe, false, now)
        .expect("health rows");
    assert_eq!(
        rows.iter()
            .find(|row| row.member.node_id == remote_node)
            .expect("remote row")
            .availability,
        ClusterNodeAvailability::Offline,
        "connectivity records own offline liveness once every probeable endpoint is unreachable"
    );
}

#[test]
fn cluster_health_and_doctor_ignore_legacy_shadow_members() {
    struct EmptyStatusProbe;

    impl ClusterStatusProbe for EmptyStatusProbe {
        fn probe_member_status(
            &self,
            _state: &ClusterBootstrapState,
            _member: &ClusterMemberRecord,
        ) -> Option<ClusterNodeStatusRecord> {
            None
        }
    }

    impl ClusterStatusAsyncProbe for EmptyStatusProbe {
        fn probe_member_status_async<'a>(
            &'a self,
            _state: &'a ClusterBootstrapState,
            _member: &'a ClusterMemberRecord,
        ) -> ClusterMembershipRpcFuture<'a, Option<ClusterNodeStatusRecord>> {
            Box::pin(async { Ok(None) })
        }
    }

    let root = sinomo_testdir::TestDir::new("sinomo-network-health-legacy-shadow-member");
    let data_dir = SinomoDataDir::new(&root);
    let paths = ClusterPaths::new(&data_dir);
    paths.ensure().expect("cluster paths");

    let now = OffsetDateTime::now_utc();
    let cluster_id = ClusterId::from_legacy_named("cluster_health_legacy_shadow").expect("cluster");
    let main_node_id = NodeId::from_legacy_named("node_health_legacy_shadow_main").expect("main");
    let shadow_node_id = sinomo_node::shadow_daemon_node_id(&main_node_id);
    let mut state = ClusterBootstrapState::initialized_locally(
        cluster_id.clone(),
        "legacy shadow health",
        main_node_id.clone(),
        "main",
        "main-public-key",
        now,
    );
    state.members[0].capabilities = vec![
        CapabilityName::new(sinomo_node::DAEMON_MAIN_RUN_CAPABILITY).expect("main capability"),
    ];
    state.members[0].allowed_capabilities = state.members[0].capabilities.clone();
    let mut legacy_shadow = ClusterMemberRecord::local_non_voting(
        cluster_id.clone(),
        shadow_node_id.clone(),
        "main shadow",
        "shadow-public-key",
        now,
    );
    legacy_shadow.capabilities = vec![
        CapabilityName::new(sinomo_node::DAEMON_SHADOW_SUPERVISE_CAPABILITY)
            .expect("shadow capability"),
    ];
    legacy_shadow.allowed_capabilities = legacy_shadow.capabilities.clone();
    legacy_shadow.endpoints = vec![daemon_lan_endpoint(
        &shadow_node_id,
        "127.0.0.1:21354".to_string(),
        10,
    )];
    state.members.push(legacy_shadow.clone());

    let rows = cluster_health_rows_with_probe(&paths, &state, &EmptyStatusProbe, false, now)
        .expect("health rows");

    assert!(
        rows.iter().all(|row| row.member.node_id != shadow_node_id),
        "legacy shadow-only members must not appear as cluster health rows: {rows:?}"
    );

    let shadow_health = ClusterHealthRow {
        member: legacy_shadow.clone(),
        status: unknown_cluster_node_status(&state, &legacy_shadow, now),
        availability: ClusterNodeAvailability::Offline,
        live_probe_observed: false,
    };
    let findings = cluster_doctor_findings(
        &state,
        &[
            doctor_connectivity_record(
                &cluster_id,
                &main_node_id,
                &shadow_node_id,
                "endpoint_health_legacy_shadow_target",
                "127.0.0.1:21354",
                ClusterConnectivityState::Unreachable,
            ),
            doctor_connectivity_record(
                &cluster_id,
                &shadow_node_id,
                &main_node_id,
                "endpoint_health_legacy_shadow_source",
                "127.0.0.1:21353",
                ClusterConnectivityState::Unreachable,
            ),
        ],
        &[shadow_health],
    );

    assert!(
        findings.is_empty(),
        "legacy shadow-only members should not create doctor warnings: {findings:?}"
    );

    let mut state_without_shadow = state.clone();
    state_without_shadow
        .members
        .retain(|member| member.node_id != shadow_node_id);
    let findings = cluster_doctor_findings(
        &state_without_shadow,
        &[doctor_connectivity_record(
            &cluster_id,
            &main_node_id,
            &shadow_node_id,
            "endpoint_health_removed_local_shadow",
            "127.0.0.1:21354",
            ClusterConnectivityState::Unreachable,
        )],
        &[],
    );
    assert!(
        findings.is_empty(),
        "removed local shadow records should not create doctor warnings: {findings:?}"
    );

    let runtime = tokio::runtime::Builder::new_current_thread()
        .enable_all()
        .build()
        .expect("runtime");
    let async_rows = runtime
        .block_on(cluster_health_rows_with_async_probe(
            &paths,
            &state,
            &EmptyStatusProbe,
            false,
            now,
        ))
        .expect("async health rows");
    assert!(
        async_rows
            .iter()
            .all(|row| row.member.node_id != shadow_node_id)
    );
}

fn doctor_connectivity_record(
    cluster_id: &ClusterId,
    source: &NodeId,
    target: &NodeId,
    endpoint_name: &str,
    address: &str,
    state: ClusterConnectivityState,
) -> ClusterConnectivityRecord {
    let now = OffsetDateTime::now_utc();
    let healthy = state == ClusterConnectivityState::Healthy;
    ClusterConnectivityRecord {
        cluster_id: cluster_id.clone(),
        source_node_id: source.clone(),
        target_node_id: target.clone(),
        endpoint_id: ClusterEndpointId::from_legacy_named(endpoint_name).expect("endpoint"),
        transport: ClusterTransportKind::LanTcp,
        address: address.to_string(),
        state,
        latency_ms: if healthy { Some(4) } else { None },
        consecutive_failures: if healthy { 0 } else { 3 },
        last_success_at: if healthy {
            Some("ok".to_string())
        } else {
            None
        },
        last_failure_at: if healthy {
            None
        } else {
            Some("failed".to_string())
        },
        failure_reason: None,
        observed_at: now,
        expires_at: now + time::Duration::seconds(900),
    }
}

fn doctor_health_row(
    state: &ClusterBootstrapState,
    member: &ClusterMemberRecord,
    availability: ClusterNodeAvailability,
    now: OffsetDateTime,
) -> ClusterHealthRow {
    let mut status = unknown_cluster_node_status(state, member, now);
    status.availability = availability.clone();
    ClusterHealthRow {
        member: member.clone(),
        status,
        availability,
        live_probe_observed: false,
    }
}

#[test]
fn cluster_doctor_tolerates_unavailable_member_while_authorities_retain_quorum() {
    let now = OffsetDateTime::now_utc();
    let cluster_id =
        ClusterId::from_legacy_named("cluster_network_doctor_tolerated_offline").expect("cluster");
    let first = NodeId::from_legacy_named("node_network_doctor_tolerated_first").expect("first");
    let second = NodeId::from_legacy_named("node_network_doctor_tolerated_second").expect("second");
    let offline =
        NodeId::from_legacy_named("node_network_doctor_tolerated_offline").expect("offline");
    let replica =
        NodeId::from_legacy_named("node_network_doctor_tolerated_replica").expect("replica");
    let mut state = ClusterBootstrapState::initialized_locally(
        cluster_id.clone(),
        "doctor tolerated offline",
        first.clone(),
        "first",
        "pk-first",
        now,
    );
    let main_capability =
        CapabilityName::new(sinomo_node::DAEMON_MAIN_RUN_CAPABILITY).expect("main capability");
    state.members[0].capabilities = vec![main_capability.clone()];
    let mut second_member = ClusterMemberRecord::local_voter(
        cluster_id.clone(),
        second.clone(),
        "second",
        "pk-second",
        now,
    );
    second_member.capabilities = vec![main_capability.clone()];
    let mut offline_member = ClusterMemberRecord::local_voter(
        cluster_id.clone(),
        offline.clone(),
        "offline",
        "pk-offline",
        now,
    );
    offline_member.capabilities = vec![main_capability];
    let replica_member = ClusterMemberRecord::local_non_voting(
        cluster_id.clone(),
        replica,
        "replica",
        "pk-replica",
        now,
    );
    state.members.extend([
        second_member.clone(),
        offline_member.clone(),
        replica_member.clone(),
    ]);

    let health = vec![
        doctor_health_row(
            &state,
            &state.members[0],
            ClusterNodeAvailability::Online,
            now,
        ),
        doctor_health_row(&state, &second_member, ClusterNodeAvailability::Online, now),
        doctor_health_row(
            &state,
            &offline_member,
            ClusterNodeAvailability::Offline,
            now,
        ),
        doctor_health_row(
            &state,
            &replica_member,
            ClusterNodeAvailability::Online,
            now,
        ),
    ];
    let records = vec![
        doctor_connectivity_record(
            &cluster_id,
            &first,
            &second,
            "endpoint_network_doctor_tolerated_first_second",
            "172.25.0.2:21353",
            ClusterConnectivityState::Healthy,
        ),
        doctor_connectivity_record(
            &cluster_id,
            &second,
            &first,
            "endpoint_network_doctor_tolerated_second_first",
            "172.25.0.1:21353",
            ClusterConnectivityState::Healthy,
        ),
        doctor_connectivity_record(
            &cluster_id,
            &first,
            &offline,
            "endpoint_network_doctor_tolerated_offline",
            "172.25.0.3:21353",
            ClusterConnectivityState::Unreachable,
        ),
    ];

    let authority_health = cluster_state_authority_health(&state, &health);
    assert_eq!(authority_health.authority_count, 3);
    assert_eq!(authority_health.online_authority_count, 2);
    assert_eq!(authority_health.quorum_size, 2);
    assert!(authority_health.has_quorum());

    let findings = cluster_doctor_findings(&state, &records, &health);
    let offline_finding = findings
        .iter()
        .find(|finding| finding.code == "node-offline")
        .expect("offline member remains visible");
    assert_eq!(offline_finding.severity, "info");
    assert!(offline_finding.detail.contains("quorum remains available"));
    assert!(findings.iter().all(|finding| !finding.is_warning()));
    assert!(
        findings
            .iter()
            .all(|finding| finding.code != "authority-route-missing")
    );
    assert!(
        findings
            .iter()
            .all(|finding| finding.code != "endpoint-unreachable")
    );
}

#[test]
fn cluster_doctor_warns_when_unavailable_authority_breaks_quorum() {
    let now = OffsetDateTime::now_utc();
    let cluster_id =
        ClusterId::from_legacy_named("cluster_network_doctor_quorum_lost").expect("cluster");
    let first = NodeId::from_legacy_named("node_network_doctor_quorum_first").expect("first");
    let offline = NodeId::from_legacy_named("node_network_doctor_quorum_offline").expect("offline");
    let mut state = ClusterBootstrapState::initialized_locally(
        cluster_id.clone(),
        "doctor quorum lost",
        first,
        "first",
        "pk-first",
        now,
    );
    let main_capability =
        CapabilityName::new(sinomo_node::DAEMON_MAIN_RUN_CAPABILITY).expect("main capability");
    state.members[0].capabilities = vec![main_capability.clone()];
    let mut offline_member =
        ClusterMemberRecord::local_voter(cluster_id, offline, "offline", "pk-offline", now);
    offline_member.capabilities = vec![main_capability];
    state.members.push(offline_member.clone());
    let health = vec![
        doctor_health_row(
            &state,
            &state.members[0],
            ClusterNodeAvailability::Online,
            now,
        ),
        doctor_health_row(
            &state,
            &offline_member,
            ClusterNodeAvailability::Offline,
            now,
        ),
    ];

    let authority_health = cluster_state_authority_health(&state, &health);
    assert_eq!(authority_health.authority_count, 2);
    assert_eq!(authority_health.online_authority_count, 1);
    assert_eq!(authority_health.quorum_size, 2);
    assert!(!authority_health.has_quorum());

    let findings = cluster_doctor_findings(&state, &[], &health);
    assert!(
        findings
            .iter()
            .any(|finding| { finding.code == "node-offline" && finding.severity == "warning" })
    );
    assert!(
        findings
            .iter()
            .any(|finding| finding.code == "authority-route-missing")
    );
}

