#[derive(Default)]
struct RecordingClusterNetworkInfoPublishHost {
    cache_matches: bool,
    cache_checks: usize,
    remembers: usize,
    commits: usize,
    last_txn: Option<KvTxn>,
}

impl ClusterNetworkInfoPublishHost for RecordingClusterNetworkInfoPublishHost {
    type Error = NetworkError;

    fn published_network_info_matches(
        &mut self,
        _paths: &ClusterPaths,
        _info: &ClusterNetworkInfoRecord,
    ) -> bool {
        self.cache_checks += 1;
        self.cache_matches
    }

    fn remember_published_network_info(
        &mut self,
        _paths: &ClusterPaths,
        _info: &ClusterNetworkInfoRecord,
    ) {
        self.remembers += 1;
    }

    fn commit_cluster_kv_txn_with_quorum(
        &mut self,
        paths: &ClusterPaths,
        state: &mut ClusterBootstrapState,
        request: KvTxnRequest,
    ) -> Result<KvSnapshot, Self::Error> {
        self.commits += 1;
        self.last_txn = Some(request.txn.clone());
        append_cluster_raft_command(paths, &state.local_node_id, KvCommand::Txn(request.txn))
    }
}

impl ClusterNetworkInfoPublishAsyncHost for RecordingClusterNetworkInfoPublishHost {
    type Error = NetworkError;

    fn published_network_info_matches_async<'a>(
        &'a mut self,
        _paths: &'a ClusterPaths,
        _info: &'a ClusterNetworkInfoRecord,
    ) -> ClusterMembershipRpcFuture<'a, bool> {
        Box::pin(async move {
            self.cache_checks += 1;
            Ok(self.cache_matches)
        })
    }

    fn remember_published_network_info_async<'a>(
        &'a mut self,
        _paths: &'a ClusterPaths,
        _info: &'a ClusterNetworkInfoRecord,
    ) -> ClusterMembershipRpcFuture<'a, ()> {
        Box::pin(async move {
            self.remembers += 1;
            Ok(())
        })
    }

    fn commit_cluster_kv_txn_with_quorum_async<'a>(
        &'a mut self,
        paths: &'a ClusterPaths,
        state: &'a mut ClusterBootstrapState,
        request: KvTxnRequest,
    ) -> ClusterMembershipRpcFuture<'a, KvSnapshot> {
        Box::pin(async move {
            self.commits += 1;
            self.last_txn = Some(request.txn.clone());
            append_cluster_raft_command(paths, &state.local_node_id, KvCommand::Txn(request.txn))
        })
    }
}

