#[test]
fn connectivity_full_sync_plans_bounded_batches() {
    let root = sinomo_testdir::TestDir::new("sinomo-network-connectivity-bounded-planner");
    let data_dir = SinomoDataDir::new(&root);
    let paths = ClusterPaths::new(&data_dir);
    paths.ensure().expect("cluster paths");
    let now = OffsetDateTime::now_utc();
    let cluster_id =
        ClusterId::from_legacy_named("cluster_connectivity_bounded_planner").expect("cluster");
    let source_node =
        NodeId::from_legacy_named("node_connectivity_bounded_planner_source").expect("source");
    let state = ClusterBootstrapState::initialized_locally(
        cluster_id,
        "connectivity bounded planner",
        source_node.clone(),
        "source",
        "pk-source",
        now,
    );
    write_cluster_state(&paths, &state).expect("write state");

    let mut stale_keys = Vec::new();
    for index in 0..5 {
        let target_node =
            NodeId::from_legacy_named(format!("node_connectivity_bounded_target_{index}"))
                .expect("target");
        let endpoint = daemon_lan_endpoint(&target_node, format!("10.52.0.{index}:21353"), 10);
        let record = cluster_connectivity_record(
            &state,
            &endpoint,
            ClusterConnectivityState::Healthy,
            Some(9),
            0,
            Some("stale".to_string()),
            None,
            now,
            600,
        );
        let key = cluster_connectivity_key(
            &record.source_node_id,
            &record.target_node_id,
            &record.endpoint_id,
        );
        append_cluster_raft_command(
            &paths,
            &source_node,
            KvCommand::Op(KvOp::put_serde(&key, &record, None).expect("stale connectivity put")),
        )
        .expect("seed stale connectivity in raft");
        stale_keys.push(key);
    }

    let incoming_target =
        NodeId::from_legacy_named("node_connectivity_bounded_target_incoming").expect("target");
    let incoming_endpoint =
        daemon_lan_endpoint(&incoming_target, "10.52.0.99:21353".to_string(), 10);
    let incoming = cluster_connectivity_record(
        &state,
        &incoming_endpoint,
        ClusterConnectivityState::Healthy,
        Some(7),
        0,
        Some("current".to_string()),
        None,
        now,
        600,
    );
    let incoming_key = cluster_connectivity_key(
        &incoming.source_node_id,
        &incoming.target_node_id,
        &incoming.endpoint_id,
    );

    let first = cluster_connectivity_full_sync_batch_ops(
        &paths,
        &source_node,
        std::slice::from_ref(&incoming),
        3,
    )
    .expect("first batch");
    assert_eq!(first.len(), 3);
    assert!(first.iter().all(|op| matches!(op, KvOp::Delete { .. })));
    append_cluster_raft_command(
        &paths,
        &source_node,
        KvCommand::Txn(KvTxn {
            compares: Vec::new(),
            success: first,
            failure: Vec::new(),
        }),
    )
    .expect("append first batch");

    let second = cluster_connectivity_full_sync_batch_ops(
        &paths,
        &source_node,
        std::slice::from_ref(&incoming),
        3,
    )
    .expect("second batch");
    assert!(second.len() <= 3);
    assert_eq!(
        second
            .iter()
            .filter(|op| matches!(op, KvOp::Delete { .. }))
            .count(),
        2
    );
    assert!(
        second
            .iter()
            .any(|op| matches!(op, KvOp::Put { key, .. } if key == &incoming_key))
    );
    append_cluster_raft_command(
        &paths,
        &source_node,
        KvCommand::Txn(KvTxn {
            compares: Vec::new(),
            success: second,
            failure: Vec::new(),
        }),
    )
    .expect("append second batch");

    let final_ops = cluster_connectivity_full_sync_batch_ops(
        &paths,
        &source_node,
        std::slice::from_ref(&incoming),
        3,
    )
    .expect("final batch");
    assert!(final_ops.is_empty());

    let snapshot = read_cluster_kv_current_snapshot(&paths).expect("read snapshot");
    assert!(snapshot.get(&incoming_key).is_some());
    assert!(
        stale_keys
            .iter()
            .all(|key| snapshot.get(key.as_str()).is_none())
    );
}

#[derive(Default)]
struct RecordingClusterConnectivityPublishHost {
    cache_matches: bool,
    cache_checks: usize,
    remembers: usize,
    remembered_records: Vec<Vec<ClusterConnectivityRecord>>,
    commits: Vec<usize>,
    last_txn: Option<KvTxn>,
}

impl ClusterConnectivityPublishHost for RecordingClusterConnectivityPublishHost {
    type Error = NetworkError;

    fn published_connectivity_record_set_matches(
        &mut self,
        _paths: &ClusterPaths,
        _source_node_id: &NodeId,
        _records: &[ClusterConnectivityRecord],
    ) -> bool {
        self.cache_checks += 1;
        self.cache_matches
    }

    fn remember_published_connectivity_record_set(
        &mut self,
        _paths: &ClusterPaths,
        _source_node_id: &NodeId,
        records: &[ClusterConnectivityRecord],
    ) {
        self.remembers += 1;
        self.remembered_records.push(records.to_vec());
    }

    fn commit_cluster_kv_txn_with_quorum(
        &mut self,
        paths: &ClusterPaths,
        state: &mut ClusterBootstrapState,
        request: KvTxnRequest,
    ) -> Result<KvSnapshot, Self::Error> {
        self.commits.push(request.txn.success.len());
        self.last_txn = Some(request.txn.clone());
        append_cluster_raft_command(paths, &state.local_node_id, KvCommand::Txn(request.txn))
    }
}

#[test]
fn connectivity_quorum_sync_driver_delegates_commits_and_remembers() {
    let root = sinomo_testdir::TestDir::new("sinomo-network-connectivity-quorum-driver");
    let data_dir = SinomoDataDir::new(&root);
    let paths = ClusterPaths::new(&data_dir);
    paths.ensure().expect("cluster paths");
    let now = OffsetDateTime::now_utc();
    let cluster_id =
        ClusterId::from_legacy_named("cluster_connectivity_quorum_driver").expect("cluster");
    let source_node =
        NodeId::from_legacy_named("node_connectivity_quorum_driver_source").expect("source");
    let target_node =
        NodeId::from_legacy_named("node_connectivity_quorum_driver_target").expect("target");
    let state = ClusterBootstrapState::initialized_locally(
        cluster_id,
        "connectivity quorum driver",
        source_node.clone(),
        "source",
        "pk-source",
        now,
    );
    write_cluster_state(&paths, &state).expect("write state");
    sync_cluster_state_to_local_raft_unchecked(&paths, &state).expect("sync state to kv");

    let endpoint = daemon_lan_endpoint(&target_node, "10.54.0.1:21353".to_string(), 10);
    let record = cluster_connectivity_record(
        &state,
        &endpoint,
        ClusterConnectivityState::Healthy,
        Some(6),
        0,
        Some("ok".to_string()),
        None,
        now,
        600,
    );
    let key = cluster_connectivity_key(
        &record.source_node_id,
        &record.target_node_id,
        &record.endpoint_id,
    );

    let mut host = RecordingClusterConnectivityPublishHost::default();
    let result = sync_cluster_connectivity_records_to_quorum_with_host(
        &paths,
        &source_node,
        vec![record.clone()],
        &mut host,
    )
    .expect("connectivity quorum sync");

    assert!(
        result.is_some(),
        "driver should return the committed snapshot"
    );
    assert_eq!(host.cache_checks, 0);
    assert_eq!(host.commits, vec![1]);
    assert_eq!(host.remembers, 1);
    assert!(
        host.last_txn
            .as_ref()
            .expect("committed txn")
            .success
            .iter()
            .any(|op| matches!(op, KvOp::Put { key: put_key, .. } if put_key == &key)),
        "network driver should plan connectivity publication"
    );
    assert_eq!(
        read_local_cluster_connectivity_records(&paths).expect("local records"),
        vec![record.clone()]
    );
    assert!(
        read_cluster_kv_current_snapshot(&paths)
            .expect("snapshot")
            .get(&key)
            .is_some(),
        "host-applied commit should publish connectivity into cluster KV"
    );

    host.cache_matches = true;
    host.commits.clear();
    let cached = sync_cluster_connectivity_records_to_quorum_with_host(
        &paths,
        &source_node,
        vec![record.clone()],
        &mut host,
    )
    .expect("cached connectivity quorum sync");
    assert!(
        cached.is_none(),
        "an unchanged source publication must be terminal without a Raft commit"
    );
    assert!(
        host.commits.is_empty(),
        "an unchanged source publication must not manufacture an empty transaction"
    );
    assert_eq!(
        host.remembers, 2,
        "an authoritative stored KV match should warm a cold publication cache"
    );
    assert_eq!(host.remembered_records.last(), Some(&vec![record]));
}

#[test]
fn connectivity_quorum_sync_does_not_cache_uncommitted_ttl_refresh() {
    let root = sinomo_testdir::TestDir::new("sinomo-network-connectivity-noop-cache");
    let data_dir = SinomoDataDir::new(&root);
    let paths = ClusterPaths::new(&data_dir);
    paths.ensure().expect("cluster paths");
    let now = OffsetDateTime::now_utc();
    let cluster_id =
        ClusterId::from_legacy_named("cluster_connectivity_noop_cache").expect("cluster");
    let source_node =
        NodeId::from_legacy_named("node_connectivity_noop_cache_source").expect("source");
    let target_node =
        NodeId::from_legacy_named("node_connectivity_noop_cache_target").expect("target");
    let state = ClusterBootstrapState::initialized_locally(
        cluster_id,
        "connectivity noop cache",
        source_node.clone(),
        "source",
        "pk-source",
        now,
    );
    write_cluster_state(&paths, &state).expect("write state");
    sync_cluster_state_to_local_raft_unchecked(&paths, &state).expect("sync state to kv");

    let endpoint = daemon_lan_endpoint(&target_node, "10.54.0.2:21353".to_string(), 10);
    let stored = cluster_connectivity_record(
        &state,
        &endpoint,
        ClusterConnectivityState::Healthy,
        Some(6),
        0,
        Some("stored".to_string()),
        None,
        now,
        600,
    );
    let key = cluster_connectivity_key(
        &stored.source_node_id,
        &stored.target_node_id,
        &stored.endpoint_id,
    );
    append_cluster_raft_command(
        &paths,
        &source_node,
        KvCommand::Txn(KvTxn {
            compares: Vec::new(),
            success: vec![KvOp::put_serde(&key, &stored, None).expect("stored put")],
            failure: Vec::new(),
        }),
    )
    .expect("seed connectivity");

    let mut refreshed = cluster_connectivity_record(
        &state,
        &endpoint,
        ClusterConnectivityState::Healthy,
        Some(1),
        0,
        Some("refreshed".to_string()),
        None,
        now + time::Duration::seconds(60),
        900,
    );
    refreshed.latency_ms = Some(1);
    let mut host = RecordingClusterConnectivityPublishHost::default();
    let result = sync_cluster_connectivity_records_to_quorum_with_host(
        &paths,
        &source_node,
        vec![refreshed.clone()],
        &mut host,
    )
    .expect("connectivity quorum sync");

    assert!(
        result.is_none(),
        "fresh stable KV records should not require a Raft commit"
    );
    assert_eq!(host.cache_checks, 0);
    assert!(host.commits.is_empty());
    assert_eq!(
        host.remembers, 1,
        "a verified no-op should warm the cache from authoritative KV"
    );
    assert_eq!(
        host.remembered_records,
        vec![vec![stored.clone()]],
        "the cache must retain the stored TTL, not the uncommitted incoming refresh"
    );
    assert_ne!(
        host.remembered_records[0][0].expires_at,
        refreshed.expires_at
    );
    let snapshot = read_cluster_kv_current_snapshot(&paths).expect("snapshot");
    let kept = snapshot
        .get(&key)
        .expect("stored connectivity")
        .decode::<ClusterConnectivityRecord>()
        .expect("decode stored connectivity");
    assert_eq!(kept.expires_at, stored.expires_at);
}

#[test]
fn connectivity_quorum_sync_publishes_post_merge_records_not_stale_input() {
    let root = sinomo_testdir::TestDir::new("sinomo-network-connectivity-post-merge-publish");
    let data_dir = SinomoDataDir::new(&root);
    let paths = ClusterPaths::new(&data_dir);
    paths.ensure().expect("cluster paths");
    let now = OffsetDateTime::now_utc();
    let cluster_id =
        ClusterId::from_legacy_named("cluster_connectivity_post_merge_publish").expect("cluster");
    let source_node =
        NodeId::from_legacy_named("node_connectivity_post_merge_source").expect("source");
    let target_node =
        NodeId::from_legacy_named("node_connectivity_post_merge_target").expect("target");
    let state = ClusterBootstrapState::initialized_locally(
        cluster_id,
        "connectivity post-merge publish",
        source_node.clone(),
        "source",
        "pk-source",
        now,
    );
    write_cluster_state(&paths, &state).expect("write state");
    sync_cluster_state_to_local_raft_unchecked(&paths, &state).expect("sync state to kv");

    let endpoint = daemon_lan_endpoint(&target_node, "10.54.0.3:21353".to_string(), 10);
    let stale = cluster_connectivity_record(
        &state,
        &endpoint,
        ClusterConnectivityState::Degraded,
        None,
        1,
        None,
        Some("stale".to_string()),
        now,
        900,
    );
    let current = cluster_connectivity_record(
        &state,
        &endpoint,
        ClusterConnectivityState::Unreachable,
        None,
        CLUSTER_CONNECTIVITY_FAILURE_THRESHOLD,
        None,
        Some("current".to_string()),
        now + time::Duration::seconds(60),
        CLUSTER_CONNECTIVITY_UNREACHABLE_TTL_SECONDS,
    );
    write_local_cluster_connectivity_record_set(
        &paths,
        &source_node,
        std::slice::from_ref(&current),
    )
    .expect("seed newer local observation");

    let runtime = tokio::runtime::Builder::new_current_thread()
        .enable_all()
        .build()
        .expect("runtime");
    let mut host = ForwardingOnlyConnectivityPublishAsyncHost {
        voter_store: InProcessKvStore::new(),
        commits: 0,
        apply_commits: true,
        inject_newer_local_on_first_commit: None,
    };
    let snapshot = runtime
        .block_on(
            sync_cluster_connectivity_records_to_quorum_async_with_state_and_host(
                runtime.handle(),
                &paths,
                &source_node,
                vec![stale],
                state,
                &mut host,
            ),
        )
        .expect("publish post-merge connectivity")
        .expect("committed snapshot");

    let key = cluster_connectivity_key(
        &current.source_node_id,
        &current.target_node_id,
        &current.endpoint_id,
    );
    let published = snapshot
        .get(&key)
        .expect("published connectivity")
        .decode::<ClusterConnectivityRecord>()
        .expect("decode published connectivity");
    assert_eq!(published, current);
    assert_eq!(host.commits, 1);
}

/// Simulates a forwarding learner: commits land in the "voter's" in-memory
/// store and the response snapshot reflects them, but the local paths-backed
/// KV never advances (no fan-out, no import). The async sync loop must
/// terminate against the response snapshot instead of spinning on the stale
/// local view (the cold-formation maintenance-loop wedge).
struct ForwardingOnlyConnectivityPublishAsyncHost {
    voter_store: InProcessKvStore,
    commits: usize,
    apply_commits: bool,
    inject_newer_local_on_first_commit: Option<ClusterConnectivityRecord>,
}

impl ClusterConnectivityPublishAsyncHost for ForwardingOnlyConnectivityPublishAsyncHost {
    type Error = NetworkError;

    fn commit_cluster_kv_txn_with_quorum_async<'a>(
        &'a mut self,
        paths: &'a ClusterPaths,
        _state: &'a mut ClusterBootstrapState,
        request: KvTxnRequest,
    ) -> ClusterMembershipRpcFuture<'a, KvSnapshot> {
        Box::pin(async move {
            self.commits += 1;
            if self.commits > 8 {
                return Err(NetworkError::Io {
                    operation: "test connectivity commit".to_string(),
                    detail: "connectivity sync loop did not converge".to_string(),
                });
            }
            if self.commits == 1
                && let Some(record) = self.inject_newer_local_on_first_commit.take()
            {
                write_local_cluster_connectivity_records(
                    paths,
                    &record.source_node_id,
                    std::slice::from_ref(&record),
                )?;
            }
            if self.apply_commits {
                self.voter_store.txn(request.txn).map_err(kv_err)?;
            }
            Ok(self.voter_store.snapshot().expect("snapshot"))
        })
    }
}

#[test]
fn async_connectivity_quorum_sync_terminates_when_local_kv_lags_forwarded_commits() {
    let root = sinomo_testdir::TestDir::new("sinomo-network-connectivity-forward-lag");
    let data_dir = SinomoDataDir::new(&root);
    let paths = ClusterPaths::new(&data_dir);
    paths.ensure().expect("cluster paths");
    let now = OffsetDateTime::now_utc();
    let cluster_id =
        ClusterId::from_legacy_named("cluster_connectivity_forward_lag").expect("cluster");
    let source_node =
        NodeId::from_legacy_named("node_connectivity_forward_lag_source").expect("source");
    let target_node =
        NodeId::from_legacy_named("node_connectivity_forward_lag_target").expect("target");
    let state = ClusterBootstrapState::initialized_locally(
        cluster_id,
        "connectivity forward lag",
        source_node.clone(),
        "source",
        "pk-source",
        now,
    );
    write_cluster_state(&paths, &state).expect("write state");
    sync_cluster_state_to_local_raft_unchecked(&paths, &state).expect("sync state to kv");

    let endpoint = daemon_lan_endpoint(&target_node, "10.55.0.1:21353".to_string(), 10);
    let record = cluster_connectivity_record(
        &state,
        &endpoint,
        ClusterConnectivityState::Healthy,
        Some(6),
        0,
        Some("ok".to_string()),
        None,
        now,
        600,
    );
    let key = cluster_connectivity_key(
        &record.source_node_id,
        &record.target_node_id,
        &record.endpoint_id,
    );

    let runtime = tokio::runtime::Builder::new_current_thread()
        .enable_all()
        .build()
        .expect("runtime");

    // Forwarded commits succeed at the voter; the local store stays stale.
    // The loop must converge from the response snapshot after one commit.
    let mut host = ForwardingOnlyConnectivityPublishAsyncHost {
        voter_store: InProcessKvStore::new(),
        commits: 0,
        apply_commits: true,
        inject_newer_local_on_first_commit: None,
    };
    let result = runtime
        .block_on(sync_cluster_connectivity_records_to_quorum_async_with_host(
            runtime.handle(),
            &paths,
            &source_node,
            vec![record.clone()],
            &mut host,
        ))
        .expect("forward-lagged connectivity sync should converge");
    assert_eq!(
        host.commits, 1,
        "one commit should converge the loop via the response snapshot"
    );
    let snapshot = result.expect("committed snapshot");
    assert!(
        snapshot.get(&key).is_some(),
        "response snapshot should hold the published record"
    );

    // A stale response snapshot can still be returned after the commit was accepted
    // by the quorum path. The publisher should stop retrying the identical batch and
    // let the next maintenance cycle refresh from KV instead of wedging the tick.
    let mut stale_host = ForwardingOnlyConnectivityPublishAsyncHost {
        voter_store: InProcessKvStore::new(),
        commits: 0,
        apply_commits: false,
        inject_newer_local_on_first_commit: None,
    };
    let stale_result = runtime
        .block_on(sync_cluster_connectivity_records_to_quorum_async_with_host(
            runtime.handle(),
            &paths,
            &source_node,
            vec![record],
            &mut stale_host,
        ))
        .expect("stale response snapshot should not wedge connectivity sync");
    assert_eq!(
        stale_host.commits, 1,
        "stale response progress must be detected on the iteration after the first commit"
    );
    assert!(stale_result.is_some());
}

