#[test]
fn cluster_kv_watch_event_log_is_bounded() {
    let root = sinomo_testdir::TestDir::new("sinomo-network-watch-events");
    let data_dir = SinomoDataDir::new(&root);
    let paths = ClusterPaths::new(&data_dir);
    paths.ensure().expect("cluster paths");
    let events = (0..(MAX_CLUSTER_KV_WATCH_EVENTS + 10))
        .map(|index| KvEvent {
            revision: KvRevision(index as u64 + 1),
            key: format!("/watch/{index}"),
            kind: KvEventKind::Put {
                value: index.to_string().into_bytes(),
            },
        })
        .collect::<Vec<_>>();

    assert_eq!(
        append_cluster_kv_watch_events(&paths.kv_paths(), &events).expect("append watch events"),
        MAX_CLUSTER_KV_WATCH_EVENTS
    );

    let retained = cluster_kv_watch_events(&paths.kv_paths()).expect("read watch events");
    assert_eq!(retained.len(), MAX_CLUSTER_KV_WATCH_EVENTS);
    assert_eq!(
        retained.first().expect("first retained").revision,
        KvRevision(11)
    );
    assert_eq!(
        retained.last().expect("last retained").revision,
        KvRevision(MAX_CLUSTER_KV_WATCH_EVENTS as u64 + 10)
    );
}

#[test]
fn cluster_kv_watch_events_append_log_suppresses_duplicate_batches() {
    let root = sinomo_testdir::TestDir::new("sinomo-network-watch-events-append");
    let data_dir = SinomoDataDir::new(&root);
    let paths = ClusterPaths::new(&data_dir);
    paths.ensure().expect("cluster paths");
    let event = KvEvent {
        revision: KvRevision(1),
        key: "/watch/append".to_string(),
        kind: KvEventKind::Put {
            value: b"value".to_vec(),
        },
    };

    assert_eq!(
        append_cluster_kv_watch_events(&paths.kv_paths(), std::slice::from_ref(&event))
            .expect("append watch event"),
        1
    );
    assert!(
        paths.kv_paths().watch_events_log.exists(),
        "new watch events should append to the log"
    );
    assert!(
        !paths.kv_paths().watch_events.exists(),
        "small batches should not rewrite the compacted checkpoint"
    );
    let log_len = std::fs::metadata(&paths.kv_paths().watch_events_log)
        .expect("watch event log metadata")
        .len();

    assert!(
        cached_cluster_kv_watch_events_contain_all(&paths.kv_paths(), std::slice::from_ref(&event)),
        "first append should seed the cache used for duplicate suppression"
    );
    assert_eq!(
        append_cluster_kv_watch_events(&paths.kv_paths(), std::slice::from_ref(&event))
            .expect("duplicate watch event"),
        0
    );
    assert_eq!(
        std::fs::metadata(&paths.kv_paths().watch_events_log)
            .expect("watch event log metadata after duplicate")
            .len(),
        log_len,
        "duplicate batches should not append more log bytes"
    );
    assert_eq!(
        cluster_kv_watch_events(&paths.kv_paths()).expect("read watch events"),
        vec![event]
    );
}

