#[test]
fn cluster_kv_watch_events_duplicate_append_repairs_damaged_log() {
    let root = sinomo_testdir::TestDir::new("sinomo-network-watch-events-duplicate-repair");
    let data_dir = SinomoDataDir::new(&root);
    let paths = ClusterPaths::new(&data_dir);
    paths.ensure().expect("cluster paths");
    let event = KvEvent {
        revision: KvRevision(1),
        key: "/watch/duplicate-repair/1".to_string(),
        kind: KvEventKind::Put {
            value: b"one".to_vec(),
        },
    };

    append_cluster_kv_watch_events(&paths.kv_paths(), std::slice::from_ref(&event))
        .expect("append first");
    let mut log = std::fs::OpenOptions::new()
        .append(true)
        .open(&paths.kv_paths().watch_events_log)
        .expect("open watch event log");
    log.write_all(&16_u32.to_be_bytes())
        .expect("write partial length");
    log.write_all(b"partial").expect("write partial body");
    log.sync_data().expect("sync partial tail");
    drop(log);

    assert_eq!(
        append_cluster_kv_watch_events(&paths.kv_paths(), std::slice::from_ref(&event))
            .expect("append duplicate after partial tail"),
        0
    );
    assert_eq!(
        cluster_kv_watch_events(&paths.kv_paths()).expect("read repaired events"),
        vec![event]
    );
    let log = std::fs::read(&paths.kv_paths().watch_events_log).expect("read repaired log");
    assert!(
        !log.windows(b"partial".len())
            .any(|window| window == b"partial"),
        "duplicate append should still repair a damaged watch-event log tail"
    );
}

