#[test]
fn create_cluster_kv_watch_prunes_and_allocates_with_one_directory_scan() {
    let root = sinomo_testdir::TestDir::new("sinomo-network-watch-create-scan");
    let data_dir = SinomoDataDir::new(&root);
    let paths = ClusterPaths::new(&data_dir);
    paths.ensure().expect("cluster paths");
    std::fs::create_dir_all(&paths.kv_paths().watches).expect("watch dir");

    write_object_file(
        &paths.kv_paths().watches.join("watch-7.sobj"),
        &ClusterKvWatchRegistration {
            watch_id: WatchId(7),
            prefix: "/watch/scan/stale/".to_string(),
            next_revision: KvRevision(1),
        },
    )
    .expect("write stale watch registration");
    write_object_file(
        &paths.kv_paths().watches.join("watch-9.sobj"),
        &ClusterKvWatchRegistration {
            watch_id: WatchId(9),
            prefix: "/watch/scan/live/".to_string(),
            next_revision: KvRevision(2),
        },
    )
    .expect("write live watch registration");
    let corrupt_path = paths.kv_paths().watches.join("watch-11.sobj");
    std::fs::write(&corrupt_path, b"not-a-sinomo-object").expect("write corrupt watch");

    let mut compacted = InProcessKvStore::new();
    compacted
        .put("/watch/scan/old", b"old".to_vec(), None)
        .expect("put compacted value");
    compacted.compact(KvRevision(1)).expect("compact store");
    write_cluster_kv_snapshot(&paths, &compacted.snapshot().expect("snapshot"))
        .expect("write compacted snapshot");

    reset_cluster_kv_watch_dir_scans_for_test(&paths.kv_paths());
    let watch = create_cluster_kv_watch(
        &paths.kv_paths(),
        cluster_kv_watch_test_node_id(),
        ClusterKvWatchPrefixRequest {
            prefix: "/watch/scan/new/".to_string(),
            start_revision: KvRevision(2),
        },
    )
    .expect("create watch after pruning");

    assert_eq!(
        cluster_kv_watch_dir_scans_for_test(&paths.kv_paths()),
        1,
        "watch creation should combine stale-pruning and max-id allocation in one directory scan"
    );
    assert!(
        !paths.kv_paths().watches.join("watch-7.sobj").exists(),
        "compacted registrations should be pruned"
    );
    assert!(
        paths.kv_paths().watches.join("watch-9.sobj").exists(),
        "live registrations should be retained"
    );
    assert!(
        !corrupt_path.exists(),
        "corrupt registrations should be pruned"
    );
    assert!(
        watch.watch_id.0 > 11,
        "watch ids must not be reused after pruning the highest seen registration"
    );
}

#[test]
fn cluster_kv_materialized_snapshot_event_history_is_bounded() {
    let root = sinomo_testdir::TestDir::new("sinomo-network-materialized-events");
    let data_dir = SinomoDataDir::new(&root);
    let paths = ClusterPaths::new(&data_dir);
    paths.ensure().expect("cluster paths");
    let mut store = InProcessKvStore::new();
    for index in 0..(sinomo_kv::MAX_CLUSTER_KV_MATERIALIZED_EVENTS + 10) {
        store
            .put(
                format!("/materialized/{index}"),
                index.to_string().into_bytes(),
                None,
            )
            .expect("put event");
    }

    write_cluster_kv_snapshot(&paths, &store.snapshot().expect("snapshot"))
        .expect("write snapshot");

    let stored = read_cluster_kv_snapshot(&paths).expect("read snapshot");
    assert_eq!(
        stored.events.len(),
        sinomo_kv::MAX_CLUSTER_KV_MATERIALIZED_EVENTS
    );
    assert_eq!(stored.compacted_revision, KvRevision(10));
    assert_eq!(
        stored.events.first().expect("first retained").revision,
        KvRevision(11)
    );
    assert_eq!(
        stored.events.last().expect("last retained").revision,
        KvRevision(sinomo_kv::MAX_CLUSTER_KV_MATERIALIZED_EVENTS as u64 + 10)
    );
}

#[test]
fn committed_raft_index_reports_only_new_events() {
    let root = sinomo_testdir::TestDir::new("sinomo-network-committed-events");
    let data_dir = SinomoDataDir::new(&root);
    let paths = ClusterPaths::new(&data_dir);
    paths.ensure().expect("cluster paths");
    let node_id = NodeId::from_legacy_named("node_committed_events").expect("node");
    let first = append_cluster_raft_command_uncommitted(
        &paths,
        &node_id,
        KvCommand::Op(KvOp::Put {
            key: "/committed/one".to_string(),
            value: b"one".to_vec(),
            lease_id: None,
        }),
    )
    .expect("append first");
    LocalClusterRaftCommandStorage::new(&paths, node_id.clone())
        .commit_cluster_raft_index_with_events(first.index)
        .expect("commit first");
    let second = append_cluster_raft_command_uncommitted(
        &paths,
        &node_id,
        KvCommand::Txn(KvTxn {
            compares: Vec::new(),
            success: vec![
                KvOp::Put {
                    key: "/committed/two".to_string(),
                    value: b"two".to_vec(),
                    lease_id: None,
                },
                KvOp::Put {
                    key: "/committed/three".to_string(),
                    value: b"three".to_vec(),
                    lease_id: None,
                },
            ],
            failure: Vec::new(),
        }),
    )
    .expect("append second");

    let committed = LocalClusterRaftCommandStorage::new(&paths, node_id.clone())
        .commit_cluster_raft_index_with_events(second.index)
        .expect("commit");

    assert_eq!(committed.events.len(), 2);
    assert_eq!(committed.events[0].key, "/committed/two");
    assert_eq!(committed.events[1].key, "/committed/three");
    assert!(
        committed
            .events
            .iter()
            .all(|event| event.revision > KvRevision(1))
    );
}

#[test]
fn cluster_raft_snapshot_event_history_is_bounded_when_compacted() {
    let root = sinomo_testdir::TestDir::new("sinomo-network-raft-snapshot-events");
    let data_dir = SinomoDataDir::new(&root);
    let paths = ClusterPaths::new(&data_dir);
    paths.ensure().expect("cluster paths");
    let node_id = NodeId::from_legacy_named("node_raft_snapshot_events").expect("node");

    // Compaction only fires once the un-snapshotted applied tail exceeds
    // 2 * RAFT_COMPACTION_RETAINED_ENTRIES, so commit well past that watermark for a
    // snapshot to be written at all; compaction then truncates the snapshot's event
    // history to MAX_CLUSTER_KV_RAFT_SNAPSHOT_EVENTS.
    for index in 0..(2 * sinomo_kv::RAFT_COMPACTION_RETAINED_ENTRIES as usize + 80) {
        let entry = append_cluster_raft_command_uncommitted(
            &paths,
            &node_id,
            KvCommand::Op(KvOp::Put {
                key: format!("/raft-snapshot/{index}"),
                value: vec![b'x'; 256],
                lease_id: None,
            }),
        )
        .expect("append");
        LocalClusterRaftCommandStorage::new(&paths, node_id.clone())
            .commit_cluster_raft_index_with_events(entry.index)
            .expect("commit");
    }

    let wal_paths = cluster_raft_wal_paths(&paths, &node_id);
    let stored: RaftSnapshot = read_kv_wal_object_file(&wal_paths.snapshot).expect("raft snapshot");
    assert!(
        stored.kv.events.len() <= MAX_CLUSTER_KV_RAFT_SNAPSHOT_EVENTS,
        "raft snapshots should not retain an unbounded event tail"
    );
}

fn certificate(
    cluster_id: ClusterId,
    node_id: NodeId,
    issuer_node_id: NodeId,
    public_key: &str,
    expires_at: time::OffsetDateTime,
) -> ClusterCertificate {
    ClusterCertificate {
        certificate_id: sinomo_base::Id::generate(),
        cluster_id,
        node_id,
        issuer_node_id,
        public_key: public_key.to_string(),
        capability_scope: Vec::new(),
        issued_at: time::OffsetDateTime::now_utc(),
        expires_at,
        signature: "sig".to_string(),
    }
}

#[test]
fn mdns_discovery_cache_returns_lan_quic_candidates_and_expires_records() {
    let cluster_id = ClusterId::from_legacy_named("cluster_home").expect("cluster");
    let node_id = NodeId::from_legacy_named("node_desktop").expect("node");
    let mut cache = MdnsDiscoveryCache::new();
    cache.upsert(MdnsDiscoveryRecord::lan_quic(
        cluster_id.clone(),
        node_id.clone(),
        "192.168.1.20:21355",
        10,
        5,
    ));

    let candidates = cache.endpoint_candidates_for_node(&node_id);

    assert_eq!(cache.endpoints_for_cluster(&cluster_id).len(), 1);
    assert_eq!(candidates.len(), 1);
    assert_eq!(
        candidates[0].endpoint.transport,
        ClusterTransportKind::LanQuic
    );
    assert_eq!(cache.expire_after_tick(14), 0);
    assert_eq!(cache.expire_after_tick(15), 1);
    assert!(cache.endpoint_candidates_for_node(&node_id).is_empty());
    assert!(cache.endpoints_for_cluster(&cluster_id).is_empty());
    assert_eq!(cache.index_record_counts_for_test(), (0, 0));
}

#[test]
fn mdns_discovery_cache_reindexes_replaced_records() {
    let cluster_id = ClusterId::from_legacy_named("cluster_mdns_replace").expect("cluster");
    let node_id = NodeId::from_legacy_named("node_mdns_replace").expect("node");
    let mut cache = MdnsDiscoveryCache::new();
    cache.upsert(MdnsDiscoveryRecord::lan_quic(
        cluster_id.clone(),
        node_id.clone(),
        "192.168.55.20:21355",
        10,
        5,
    ));
    cache.upsert(MdnsDiscoveryRecord::lan_quic(
        cluster_id.clone(),
        node_id.clone(),
        "192.168.55.20:21355",
        100,
        5,
    ));

    assert_eq!(
        cache.expire_after_tick(15),
        0,
        "a refreshed mDNS record must not be expired by its previous deadline index"
    );
    assert_eq!(cache.endpoint_candidates_for_node(&node_id).len(), 1);
    assert_eq!(cache.endpoints_for_cluster(&cluster_id).len(), 1);
    assert_eq!(cache.index_record_counts_for_test(), (1, 1));
    assert_eq!(cache.expire_after_tick(105), 1);
    assert!(cache.endpoint_candidates_for_node(&node_id).is_empty());
    assert!(cache.endpoints_for_cluster(&cluster_id).is_empty());
    assert_eq!(cache.index_record_counts_for_test(), (0, 0));
}

#[test]
fn mdns_discovery_records_clamp_advertised_ttl() {
    let cluster_id = ClusterId::from_legacy_named("cluster_mdns_ttl").expect("cluster");
    let node_id = NodeId::from_legacy_named("node_mdns_ttl").expect("node");
    let endpoint = MdnsDiscoveryRecord::lan_quic(
        cluster_id.clone(),
        node_id.clone(),
        "192.168.51.20:21355",
        10,
        u64::MAX,
    )
    .endpoint;
    let advertisement = MdnsDiscoveryAdvertisement {
        ttl_ticks: u64::MAX,
        ..MdnsDiscoveryAdvertisement::new(cluster_id.clone(), node_id.clone(), vec![endpoint], 10)
    };
    let records = advertisement.records();

    assert_eq!(records.len(), 1);
    assert_eq!(
        records[0].expires_after_tick,
        10 + sinomo_network::MAX_SINOMO_LAN_DISCOVERY_TTL_TICKS,
        "untrusted LAN advertisements must not pin stale roaming endpoints indefinitely"
    );

    let helper_record =
        MdnsDiscoveryRecord::lan_quic(cluster_id, node_id, "192.168.51.21:21355", 20, u64::MAX);
    assert_eq!(
        helper_record.expires_after_tick,
        20 + sinomo_network::MAX_SINOMO_LAN_DISCOVERY_TTL_TICKS,
        "direct record helpers should share the same TTL bound"
    );
}

